def _normalize_privacy_scope(value: str | None) -> str:
    scope = str(value or "").strip().lower()
    if scope not in PRIVACY_CONSENT_SCOPE_VALUES:
        raise HTTPException(status_code=400, detail="Invalid privacy consent scope")
    return scope


def _normalize_privacy_source_app(value: str | None) -> str:
    source_app = str(value or "").strip().lower() or "public"
    return source_app if source_app in PRIVACY_SOURCE_APP_VALUES else "public"


def _normalize_privacy_actor_type(value: str | None) -> str:
    actor_type = str(value or "").strip().lower() or "anonymous"
    return actor_type if actor_type in PRIVACY_ACTOR_TYPE_VALUES else "anonymous"


def _request_ip_address(request: Request) -> str | None:
    forwarded = str(request.headers.get("x-forwarded-for") or "").strip()
    if forwarded:
        return forwarded.split(",")[0].strip() or None
    real_ip = str(request.headers.get("x-real-ip") or "").strip()
    if real_ip:
        return real_ip
    client_host = getattr(request.client, "host", None)
    return str(client_host).strip() or None


def get_db():
    db = SessionLocal()
    try:
        _ensure_green_schema_ready(db)
        yield db
    finally:
        db.close()


def _ensure_green_schema_ready(db: Session):
    global _GREEN_SCHEMA_READY
    if _GREEN_SCHEMA_READY:
        return

    with _GREEN_SCHEMA_BOOTSTRAP_LOCK:
        if _GREEN_SCHEMA_READY:
            return

        advisory_lock_acquired = False
        try:
            # Serialize bootstrap across multiple API workers/processes.
            try:
                db.execute(
                    text("SELECT pg_advisory_lock(:lock_id)"),
                    {"lock_id": _GREEN_SCHEMA_ADVISORY_LOCK_ID},
                )
                advisory_lock_acquired = True
            except Exception:
                # If advisory lock is unavailable, continue with best effort.
                db.rollback()

            ensure_green_tables(db)
            _GREEN_SCHEMA_READY = True
        finally:
            if advisory_lock_acquired:
                try:
                    db.execute(
                        text("SELECT pg_advisory_unlock(:lock_id)"),
                        {"lock_id": _GREEN_SCHEMA_ADVISORY_LOCK_ID},
                    )
                    db.commit()
                except Exception:
                    db.rollback()


def _normalize_name(value: str | None) -> str:
    return (value or "").strip().lower()


def _slugify_text(value: str | None, fallback: str = "organization") -> str:
    raw = (value or "").strip().lower()
    raw = re.sub(r"[^a-z0-9]+", "-", raw).strip("-")
    return raw or fallback


def _pdf_response_with_r2(
    local_pdf_path: str,
    filename: str,
    *,
    category: str,
    project_id: int | None = None,
    organization_id: int | None = None,
):
    def _finalize_pdf(path: str):
        try:
            if os.path.exists(path):
                upload_export_file_best_effort(
                    path,
                    filename,
                    category=category,
                    project_id=project_id,
                    organization_id=organization_id,
                    content_type="application/pdf",
                )
        except Exception:
            pass
        finally:
            try:
                if os.path.exists(path):
                    os.remove(path)
            except Exception:
                pass

    response = FileResponse(
        local_pdf_path,
        media_type="application/pdf",
        filename=filename,
        background=BackgroundTask(_finalize_pdf, local_pdf_path),
    )
    response.headers["X-LandCheck-R2-Upload"] = "deferred"
    return response


def _normalize_export_object_key(raw_key: str) -> str:
    settings = _build_export_r2_settings() or {}
    bucket = str(settings.get("bucket") or "").strip()
    key = (raw_key or "").strip().lstrip("/")
    if not key:
        return ""
    for _ in range(3):
        decoded = unquote(key)
        if decoded == key:
            break
        key = decoded
    bucket_prefix = f"{bucket}/"
    if bucket and key.startswith(bucket_prefix):
        key = key[len(bucket_prefix):]
    return key


def _build_export_proxy_url(object_key: str | None, request: Request | None = None) -> str | None:
    raw_key = str(object_key or "").strip()
    if not raw_key:
        return None
    try:
        settings = _build_export_r2_settings()
    except Exception:
        settings = None
    if not settings:
        return None
    normalized = _normalize_export_object_key(raw_key)
    if not normalized:
        return None
    path = f"/green/exports/object/{quote(normalized, safe='/')}"
    base = ""
    if request is not None:
        base = str(request.base_url).rstrip("/")
    if not base:
        base = (os.getenv("BACKEND_URL") or "").strip().rstrip("/")
    return f"{base}{path}" if base else path


def _serialize_green_export_job(row: dict | None, request: Request | None = None) -> dict | None:
    if not row:
        return None
    data = dict(row)
    object_key = str(data.get("object_key") or "").strip()
    public_url = str(data.get("public_url") or "").strip()
    proxy_url = _build_export_proxy_url(object_key, request=request)
    return {
        "id": str(data.get("id") or ""),
        "export_type": str(data.get("export_type") or ""),
        "project_id": int(data.get("project_id") or 0) or None,
        "organization_id": int(data.get("organization_id") or 0) or None,
        "assignee_name": str(data.get("assignee_name") or "").strip() or None,
        "include_photos": bool(data.get("include_photos")),
        "status": str(data.get("status") or "queued"),
        "file_name": str(data.get("file_name") or "").strip() or None,
        "object_key": object_key or None,
        "public_url": public_url or None,
        "download_url": proxy_url or public_url or None,
        "error_text": str(data.get("error_text") or "").strip() or None,
        "requested_by": str(data.get("requested_by") or "").strip() or None,
        "created_at": data.get("created_at"),
        "started_at": data.get("started_at"),
        "completed_at": data.get("completed_at"),
        "updated_at": data.get("updated_at"),
    }


def _get_green_export_job(db: Session, job_id: str) -> dict | None:
    row = db.execute(
        text(
            """
            SELECT *
            FROM green_export_jobs
            WHERE id = :job_id
            LIMIT 1
            """
        ),
        {"job_id": str(job_id or "").strip()},
    ).mappings().first()
    return dict(row) if row else None


def _set_green_export_job_status(
    db: Session,
    job_id: str,
    *,
    status: str,
    error_text: str | None = None,
    object_key: str | None = None,
    public_url: str | None = None,
    file_name: str | None = None,
    started: bool = False,
    completed: bool = False,
):
    db.execute(
        text(
            """
            UPDATE green_export_jobs
            SET status = :status,
                error_text = :error_text,
                object_key = COALESCE(:object_key, object_key),
                public_url = COALESCE(:public_url, public_url),
                file_name = COALESCE(:file_name, file_name),
                started_at = CASE WHEN :started THEN COALESCE(started_at, NOW()) ELSE started_at END,
                completed_at = CASE WHEN :completed THEN NOW() ELSE completed_at END,
                updated_at = NOW()
            WHERE id = :job_id
            """
        ),
        {
            "job_id": str(job_id or "").strip(),
            "status": status,
            "error_text": (error_text or "").strip() or None,
            "object_key": (object_key or "").strip() or None,
            "public_url": (public_url or "").strip() or None,
            "file_name": (file_name or "").strip() or None,
            "started": bool(started),
            "completed": bool(completed),
        },
    )
    db.commit()


@router.get("/exports/object/{object_key:path}")
def get_exported_object(object_key: str):
    settings = _build_export_r2_settings()
    if not settings:
        raise HTTPException(status_code=404, detail="Export storage is not configured.")
    resolved_key = _normalize_export_object_key(object_key)
    if not resolved_key:
        raise HTTPException(status_code=400, detail="Invalid export key.")
    try:
        client = boto3.client(
            "s3",
            endpoint_url=settings["endpoint_url"],
            aws_access_key_id=settings["access_key"],
            aws_secret_access_key=settings["secret_key"],
            region_name=settings["region"],
        )
        obj = client.get_object(Bucket=settings["bucket"], Key=resolved_key)
    except ClientError as exc:
        code = (exc.response.get("Error") or {}).get("Code", "")
        if code in {"NoSuchKey", "404", "NotFound"}:
            raise HTTPException(status_code=404, detail="Export not found.")
        raise HTTPException(status_code=502, detail="Failed to read export from storage.")
    except Exception:
        raise HTTPException(status_code=502, detail="Failed to read export from storage.")

    content_type = obj.get("ContentType") or "application/pdf"
    cache_control = obj.get("CacheControl") or "private, max-age=0, no-store"
    file_name = Path(resolved_key).name or "export.pdf"
    return StreamingResponse(
        obj["Body"].iter_chunks(),
        media_type=content_type,
        headers={
            "Cache-Control": cache_control,
            "Content-Disposition": f'inline; filename="{file_name}"',
        },
    )


def _ensure_unique_org_slug(db: Session, slug_base: str, exclude_org_id: int | None = None) -> str:
    base = _slugify_text(slug_base)
    candidate = base
    suffix = 2
    while True:
        params = {"slug": candidate}
        if exclude_org_id is None:
            row = db.execute(
                text("SELECT id FROM green_organizations WHERE LOWER(slug) = LOWER(:slug) LIMIT 1"),
                params,
            ).first()
        else:
            row = db.execute(
                text(
                    """
                    SELECT id FROM green_organizations
                    WHERE LOWER(slug) = LOWER(:slug)
                      AND id <> :exclude_org_id
                    LIMIT 1
                    """
                ),
                {**params, "exclude_org_id": int(exclude_org_id)},
            ).first()
        if not row:
            return candidate
        candidate = f"{base}-{suffix}"
        suffix += 1


def _generate_prefixed_uid(prefix: str) -> str:
    token = uuid.uuid4().hex[:8].upper()
    return f"{prefix}-{token}"


def _ensure_unique_user_uid(db: Session, candidate: str | None = None, exclude_user_id: int | None = None) -> str:
    base = (candidate or "").strip().upper()
    if not base:
        base = _generate_prefixed_uid("USR")
    if not re.fullmatch(r"[A-Z0-9][A-Z0-9._-]{2,63}", base):
        base = re.sub(r"[^A-Z0-9._-]+", "-", base.upper()).strip("-")
        if not base:
            base = _generate_prefixed_uid("USR")
    value = base
    while True:
        if exclude_user_id is None:
            found = db.execute(
                text("SELECT id FROM green_users WHERE UPPER(COALESCE(user_uid, '')) = :uid LIMIT 1"),
                {"uid": value},
            ).first()
        else:
            found = db.execute(
                text(
                    """
                    SELECT id FROM green_users
                    WHERE UPPER(COALESCE(user_uid, '')) = :uid
                      AND id <> :user_id
                    LIMIT 1
                    """
                ),
                {"uid": value, "user_id": int(exclude_user_id)},
            ).first()
        if not found:
            return value
        value = _generate_prefixed_uid("USR")


