def _normalize_currency_code(value: str | None, default: str = "NGN") -> str:
    raw = str(value or "").strip().upper()
    letters_only = "".join(ch for ch in raw if ch.isalpha())
    if len(letters_only) == 3:
        return letters_only
    return default


