def _normalize_sponsor_agent_settlement_channel(value: str | None) -> str | None:
    normalized = _normalize_name(value)
    if normalized in {"flutterwave", "flutterwave_auto", "auto", "automatic", "gateway"}:
        return "flutterwave"
    if normalized in {"manual", "manual_settlement", "external", "bank_transfer", "offline"}:
        return "manual"
    return None


def _normalize_account_number(value: object) -> str:
    return "".join(ch for ch in str(value or "").strip() if ch.isdigit())


def _mask_account_number(value: object) -> str | None:
    digits = _normalize_account_number(value)
    if not digits:
        return None
    if len(digits) <= 4:
        return digits
    return f"{'*' * max(len(digits) - 4, 0)}{digits[-4:]}"


def _derive_default_sponsor_agent_fee(amount_per_tree: object, *, ratio: float) -> float:
    try:
        base_value = round(float(amount_per_tree or 0), 2)
    except Exception:
        base_value = 0.0
    if base_value <= 0 or ratio <= 0:
        return 0.0
    return round(base_value * ratio, 2)


def _flutterwave_secret_key() -> str | None:
    return str(os.getenv("FLW_SECRET_KEY") or os.getenv("FLUTTERWAVE_SECRET_KEY") or "").strip() or None


def _flutterwave_secret_hash() -> str | None:
    return str(os.getenv("FLW_SECRET_HASH") or os.getenv("FLUTTERWAVE_SECRET_HASH") or "").strip() or None


def _build_public_api_base_url(request: Request | None = None) -> str:
    if LANDCHECK_API_PUBLIC_URL:
        return LANDCHECK_API_PUBLIC_URL
    if request is not None:
        forwarded_proto = str(request.headers.get("x-forwarded-proto") or request.url.scheme or "https").split(",")[0].strip()
        forwarded_host = str(request.headers.get("x-forwarded-host") or request.headers.get("host") or request.url.netloc).split(",")[0].strip()
        if forwarded_proto and forwarded_host:
            return f"{forwarded_proto}://{forwarded_host}".rstrip("/")
        return str(request.base_url).rstrip("/")
    return ""


def _build_public_privacy_policy_url() -> str:
    return str(os.getenv("LANDCHECK_PRIVACY_POLICY_URL") or "").strip() or "https://landcheck.online/privacy"


def _build_sponsor_public_terms_url(request: Request | None = None) -> str | None:
    base_url = _build_public_api_base_url(request)
    return f"{base_url}/green/sponsor/public/terms" if base_url else None


def _build_sponsor_public_reset_password_url(token: str, request: Request | None = None) -> str | None:
    reset_token = str(token or "").strip()
    if not reset_token:
        return None
    base_url = _build_public_api_base_url(request)
    return f"{base_url}/green/sponsor/public/reset-password?token={quote(reset_token)}" if base_url else None


def _build_tree_best_photo_url(tree_id: object, request: Request | None = None) -> str | None:
    try:
        numeric = int(tree_id or 0)
    except Exception:
        return None
    if numeric <= 0:
        return None
    base_url = _build_public_api_base_url(request)
    return f"{base_url}/green/trees/{numeric}/photo?w=1280&q=76&fm=jpeg" if base_url else None


def _build_flutterwave_return_url(request: Request, order_uid: str) -> str:
    base_url = _build_public_api_base_url(request)
    if not base_url:
        raise HTTPException(status_code=500, detail="Could not determine the public API URL for payment callbacks")
    return f"{base_url}/green/sponsor/payments/flutterwave/return?order_uid={quote(str(order_uid or '').strip())}"


def _build_sponsor_payment_app_url(order_uid: str, status: str, message: str | None = None) -> str:
    query = f"order_uid={quote(str(order_uid or '').strip())}&status={quote(str(status or '').strip() or 'pending')}"
    if message:
        query += f"&message={quote(str(message).strip())}"
    return f"{LANDCHECK_MOBILE_SCHEME}://sponsor/payment-result?{query}"


def _render_sponsor_payment_return_page(title: str, message: str, deep_link_url: str) -> str:
    safe_title = html.escape(title)
    safe_message = html.escape(message)
    safe_link = html.escape(deep_link_url, quote=True)
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{safe_title}</title>
    <style>
      body {{
        margin: 0;
        font-family: Arial, sans-serif;
        background: linear-gradient(160deg, #0f5b2f 0%, #1f7d43 55%, #66be6d 100%);
        color: #ffffff;
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 24px;
      }}
      .card {{
        width: min(520px, 100%);
        background: rgba(7, 24, 14, 0.24);
        border: 1px solid rgba(255,255,255,0.16);
        border-radius: 24px;
        padding: 28px;
        box-shadow: 0 24px 48px rgba(7, 24, 14, 0.24);
      }}
      h1 {{
        margin: 0 0 12px;
        font-size: 28px;
        line-height: 1.15;
      }}
      p {{
        margin: 0 0 18px;
        line-height: 1.6;
        color: rgba(255,255,255,0.9);
      }}
      a {{
        display: inline-block;
        background: #ffffff;
        color: #0f5b2f;
        font-weight: 700;
        text-decoration: none;
        padding: 14px 18px;
        border-radius: 999px;
      }}
      small {{
        display: block;
        margin-top: 14px;
        color: rgba(255,255,255,0.72);
      }}
    </style>
  </head>
  <body>
    <div class="card">
      <h1>{safe_title}</h1>
      <p>{safe_message}</p>
      <a href="{safe_link}">Return to LC Green</a>
      <small>If the app does not open automatically, tap the button above.</small>
    </div>
    <script>
      window.setTimeout(function () {{
        window.location.href = "{safe_link}";
      }}, 250);
    </script>
  </body>
</html>"""


def _flutterwave_headers() -> dict[str, str]:
    secret_key = _flutterwave_secret_key()
    if not secret_key:
        raise HTTPException(status_code=503, detail="Flutterwave payment gateway is not configured on this server")
    return {
        "Authorization": f"Bearer {secret_key}",
        "Content-Type": "application/json",
    }


def _call_flutterwave_api(
    method: str,
    path: str,
    payload: dict | None = None,
    json: dict | None = None,
    params: dict | None = None,
    trace_id: str | None = None,
    idempotency_key: str | None = None,
    extra_headers: dict[str, str] | None = None,
    timeout: int = 30,
) -> dict:
    request_payload = json if isinstance(json, dict) else payload
    headers = dict(_flutterwave_headers())
    normalized_trace_id = str(trace_id or "").strip()
    normalized_idempotency_key = str(idempotency_key or "").strip()
    if normalized_trace_id:
        headers["X-Trace-Id"] = normalized_trace_id
    if normalized_idempotency_key:
        headers["X-Idempotency-Key"] = normalized_idempotency_key
    if extra_headers:
        for key, value in extra_headers.items():
            key_text = str(key or "").strip()
            value_text = str(value or "").strip()
            if key_text and value_text:
                headers[key_text] = value_text
    try:
        response = requests.request(
            method.upper(),
            f"{FLUTTERWAVE_API_BASE_URL}{path}",
            headers=headers,
            json=request_payload,
            params=params,
            timeout=timeout,
        )
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail="Could not reach Flutterwave. Please try again.") from exc
    try:
        body = response.json()
    except ValueError:
        body = {}
    if response.status_code >= 400:
        detail = str(body.get("message") or body.get("error") or "Flutterwave rejected the payment request.")
        raise HTTPException(status_code=502, detail=detail)
    if not isinstance(body, dict):
        raise HTTPException(status_code=502, detail="Flutterwave returned an unreadable response")
    return body


def _create_flutterwave_payment_link(request: Request, order_row: dict, sponsor_row: dict, project: dict) -> dict:
    tx_ref = str(order_row.get("payment_gateway_reference") or order_row.get("order_uid") or "").strip()
    if not tx_ref:
        raise HTTPException(status_code=500, detail="Sponsorship order is missing a transaction reference")
    amount_total = round(float(order_row.get("amount_total") or 0), 2)
    currency = _normalize_currency_code(order_row.get("currency"), "NGN")
    response = _call_flutterwave_api(
        "POST",
        "/payments",
        payload={
            "tx_ref": tx_ref,
            "amount": f"{amount_total:.2f}",
            "currency": currency,
            "redirect_url": _build_flutterwave_return_url(request, str(order_row.get("order_uid") or tx_ref)),
            "customer": {
                "email": str(sponsor_row.get("email") or "").strip(),
                "name": str(sponsor_row.get("full_name") or "").strip(),
                "phonenumber": str(sponsor_row.get("phone") or "").strip() or None,
            },
            "customizations": {
                "title": str(project.get("public_sponsor_title") or project.get("name") or "LandCheck Green").strip(),
                "description": "Secure sponsorship payment for verified tree planting and field updates.",
            },
            "meta": {
                "order_id": int(order_row.get("id") or 0),
                "order_uid": str(order_row.get("order_uid") or "").strip(),
                "project_id": int(order_row.get("project_id") or 0),
                "sponsor_account_id": int(order_row.get("sponsor_account_id") or 0),
            },
            "configurations": {
                "session_duration": 30,
                "max_retry_attempt": 3,
            },
        },
    )
    data = response.get("data") or {}
    link = str(data.get("link") or "").strip()
    if not link:
        raise HTTPException(status_code=502, detail="Flutterwave did not return a hosted checkout link")
    return {
        "link": link,
        "tx_ref": tx_ref,
        "raw": response,
    }


def _verify_flutterwave_webhook_signature(raw_body: bytes, signature: str | None) -> bool:
    secret_hash = _flutterwave_secret_hash()
    provided_signature = str(signature or "").strip()
    if not secret_hash or not provided_signature:
        return False
    expected_signature = hmac.new(secret_hash.encode("utf-8"), raw_body, hashlib.sha256).digest()
    expected_b64 = base64.b64encode(expected_signature).decode("utf-8")
    return hmac.compare_digest(expected_b64, provided_signature)


def _verify_flutterwave_transaction(transaction_id: int | None = None, tx_ref: str | None = None) -> dict:
    if int(transaction_id or 0) > 0:
        return _call_flutterwave_api("GET", f"/transactions/{int(transaction_id)}/verify")
    reference = str(tx_ref or "").strip()
    if not reference:
        raise HTTPException(status_code=400, detail="Missing Flutterwave transaction reference")
    return _call_flutterwave_api("GET", "/transactions/verify_by_reference", params={"tx_ref": reference})


def _sync_sponsorship_order_flutterwave_payment(
    db: Session,
    order_row: dict,
    transaction_id: int | None = None,
    tx_ref: str | None = None,
    actor: str | None = None,
    review_notes: str | None = None,
) -> dict:
    verification = _verify_flutterwave_transaction(transaction_id=transaction_id, tx_ref=tx_ref or order_row.get("payment_gateway_reference"))
    data = verification.get("data") or {}
    order_id = int(order_row.get("id") or 0)
    expected_amount = round(float(order_row.get("amount_total") or 0), 2)
    expected_currency = _normalize_currency_code(order_row.get("currency"), "NGN")
    expected_tx_ref = str(order_row.get("payment_gateway_reference") or order_row.get("order_uid") or "").strip()
    actual_status = _normalize_name(data.get("status"))
    actual_tx_ref = str(data.get("tx_ref") or tx_ref or expected_tx_ref).strip()
    actual_currency = _normalize_currency_code(data.get("currency"), expected_currency)
    charged_amount = round(float(data.get("charged_amount") or data.get("amount") or 0), 2)
    gateway_transaction_id = int(data.get("id") or transaction_id or 0) or None
    gateway_state = actual_status or "pending"
    flw_reference = str(data.get("flw_ref") or "").strip() or None
    note = _clean_text(review_notes, 500)
    already_verified = _normalize_sponsor_payment_status(order_row.get("payment_status")) == "verified"
    matches_reference = not expected_tx_ref or actual_tx_ref == expected_tx_ref
    matches_currency = actual_currency == expected_currency
    matches_amount = charged_amount + 0.01 >= expected_amount
    is_verified = actual_status in {"successful", "succeeded"} and matches_reference and matches_currency and matches_amount
    if is_verified:
        db.execute(
            text(
                """
                UPDATE green_sponsorship_orders
                SET payment_status = 'verified',
                    payment_reference = COALESCE(:payment_reference, payment_reference),
                    payment_gateway_transaction_id = :payment_gateway_transaction_id,
                    payment_gateway_status = :payment_gateway_status,
                    payment_gateway_payload = CAST(:payment_gateway_payload AS JSONB),
                    reviewed_by = COALESCE(:reviewed_by, reviewed_by),
                    reviewed_at = NOW(),
                    review_notes = COALESCE(:review_notes, review_notes),
                    payment_verified_at = NOW(),
                    updated_at = NOW()
                WHERE id = :order_id
                """
            ),
            {
                "order_id": order_id,
                "payment_reference": flw_reference,
                "payment_gateway_transaction_id": gateway_transaction_id,
                "payment_gateway_status": gateway_state,
                "payment_gateway_payload": _safe_json(data),
                "reviewed_by": _clean_text(actor, 120),
                "review_notes": note,
            },
        )
        db.execute(
            text(
                """
                UPDATE green_sponsorship_units
                SET sponsorship_status = 'awaiting_tree',
                    updated_at = NOW()
                WHERE order_id = :order_id
                  AND tree_id IS NULL
                  AND LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_payment'
                """
            ),
            {"order_id": order_id},
        )
        _refresh_sponsorship_order_status(db, order_id)
        return {
            "verified": True,
            "payment_status": "verified",
            "gateway_status": gateway_state,
            "transaction_id": gateway_transaction_id,
            "tx_ref": actual_tx_ref,
            "message": "Payment verified successfully.",
            "should_send_payment_confirmation": not already_verified,
        }
    db.execute(
        text(
            """
            UPDATE green_sponsorship_orders
            SET payment_gateway_transaction_id = COALESCE(:payment_gateway_transaction_id, payment_gateway_transaction_id),
                payment_gateway_status = :payment_gateway_status,
                payment_gateway_payload = CAST(:payment_gateway_payload AS JSONB),
                updated_at = NOW()
            WHERE id = :order_id
            """
        ),
        {
            "order_id": order_id,
            "payment_gateway_transaction_id": gateway_transaction_id,
            "payment_gateway_status": gateway_state,
            "payment_gateway_payload": _safe_json(data),
        },
    )
    _refresh_sponsorship_order_status(db, order_id)
    failure_message = "Payment is still pending confirmation."
    if actual_status in {"failed", "cancelled", "canceled"}:
        failure_message = "Payment was not completed. You can try again from the app."
    elif not matches_reference or not matches_currency or not matches_amount:
        failure_message = "Payment details did not match this sponsorship order."
    return {
        "verified": False,
        "payment_status": _normalize_sponsor_payment_status(order_row.get("payment_status")),
        "gateway_status": gateway_state,
        "transaction_id": gateway_transaction_id,
        "tx_ref": actual_tx_ref,
        "message": failure_message,
        "should_send_payment_confirmation": False,
    }


def _apply_project_access_fields(payload: dict) -> dict:
    payload["access_model"] = _normalize_project_access_model(payload.get("access_model"))
    payload["public_sponsor_enabled"] = bool(payload.get("public_sponsor_enabled"))
    price_value = payload.get("sponsor_price_per_tree")
    try:
        payload["sponsor_price_per_tree"] = round(float(price_value), 2) if price_value is not None else None
    except Exception:
        payload["sponsor_price_per_tree"] = None
    planting_fee_value = payload.get("sponsor_agent_planting_fee")
    try:
        payload["sponsor_agent_planting_fee"] = round(float(planting_fee_value), 2) if planting_fee_value is not None else None
    except Exception:
        payload["sponsor_agent_planting_fee"] = None
    maintenance_fee_value = payload.get("sponsor_agent_maintenance_fee")
    try:
        payload["sponsor_agent_maintenance_fee"] = round(float(maintenance_fee_value), 2) if maintenance_fee_value is not None else None
    except Exception:
        payload["sponsor_agent_maintenance_fee"] = None
    capacity_value = payload.get("sponsor_capacity")
    try:
        payload["sponsor_capacity"] = int(capacity_value) if capacity_value is not None else None
    except Exception:
        payload["sponsor_capacity"] = None
    max_per_order = payload.get("sponsor_max_per_order")
    try:
        payload["sponsor_max_per_order"] = max(1, int(max_per_order or 100))
    except Exception:
        payload["sponsor_max_per_order"] = 100
    payload["sponsor_currency"] = _normalize_currency_code(payload.get("sponsor_currency"), "NGN")
    payload["sponsor_dedication_enabled"] = bool(payload.get("sponsor_dedication_enabled", True))
    payload["public_sponsor_title"] = _clean_text(payload.get("public_sponsor_title"), 160)
    payload["public_sponsor_description"] = _clean_text(payload.get("public_sponsor_description"), 1200)
    payload["sponsor_payment_instructions"] = _clean_text(payload.get("sponsor_payment_instructions"), 1200)
    payload["public_sponsor_agent_user_ids"] = _normalize_positive_int_list(payload.get("public_sponsor_agent_user_ids"))
    return payload


def _normalize_positive_int_list(value: object) -> list[int]:
    if value is None:
        return []
    parsed_value = _json_value_or(value, value) if isinstance(value, str) else value
    items = parsed_value if isinstance(parsed_value, (list, tuple, set)) else []
    seen: set[int] = set()
    normalized: list[int] = []
    for item in items:
        try:
            numeric = int(item)
        except Exception:
            continue
        if numeric <= 0 or numeric in seen:
            continue
        seen.add(numeric)
        normalized.append(numeric)
    return normalized


def _normalize_string_list(value: object) -> list[str]:
    if value is None:
        return []
    items = value if isinstance(value, (list, tuple, set)) else []
    seen: set[str] = set()
    normalized: list[str] = []
    for item in items:
        text_value = str(item or "").strip()
        if not text_value or text_value in seen:
            continue
        seen.add(text_value)
        normalized.append(text_value)
    return normalized


def _json_value_or(value: object, fallback):
    if value is None:
        return fallback
    if isinstance(value, (dict, list)):
        return value
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return fallback
    return fallback


def _validate_public_sponsor_agent_user_ids(
    db: Session,
    *,
    organization_id: int | None,
    user_ids: list[int],
) -> list[int]:
    normalized = _normalize_positive_int_list(user_ids)
    if not normalized:
        return []
    valid_rows = db.execute(
        text(
            """
            SELECT id
            FROM green_users
            WHERE id IN :user_ids
              AND COALESCE(is_active, TRUE) = TRUE
              AND COALESCE(allow_green, TRUE) = TRUE
              AND (:organization_id IS NULL OR organization_id = :organization_id)
            """
        ).bindparams(bindparam("user_ids", expanding=True)),
        {"user_ids": normalized, "organization_id": organization_id},
    ).scalars().all()
    valid_ids = {int(row) for row in valid_rows}
    if len(valid_ids) != len(normalized):
        raise HTTPException(
            status_code=400,
            detail="Some selected sponsor agents are inactive, not Green-enabled, or outside this organization.",
        )
    return [user_id for user_id in normalized if user_id in valid_ids]


def _normalize_custodian_profile_data(value: object) -> dict | None:
    raw = _normalize_json_object(value) or {}
    if not raw:
        return None
    normalized: dict[str, object] = {}
    for key in ("farmer_code", "national_id", "state_name", "ward_name", "farmer_group", "primary_crop", "secondary_crops", "input_support_needs"):
        text_value = _clean_text(raw.get(key), 160 if key != "input_support_needs" else 240)
        if text_value:
            normalized[key] = text_value
    gender = _clean_choice(raw.get("gender"), AGRIC_GENDER_VALUES)
    if gender:
        normalized["gender"] = gender
    date_of_birth = _to_date_input(_parse_date_value(raw.get("date_of_birth")))
    if date_of_birth:
        normalized["date_of_birth"] = date_of_birth
    household_size = _clean_int(raw.get("household_size"), minimum=1, maximum=200)
    if household_size is not None:
        normalized["household_size"] = household_size
    land_tenure = _clean_choice(raw.get("land_tenure"), AGRIC_LAND_TENURE_VALUES)
    if land_tenure:
        normalized["land_tenure"] = land_tenure
    irrigation_access = _clean_choice(raw.get("irrigation_access"), AGRIC_ACCESS_LEVEL_VALUES)
    if irrigation_access:
        normalized["irrigation_access"] = irrigation_access
    finance_access = _clean_bool(raw.get("finance_access"))
    if finance_access is not None:
        normalized["finance_access"] = finance_access
    insurance_access = _clean_bool(raw.get("insurance_access"))
    if insurance_access is not None:
        normalized["insurance_access"] = insurance_access
    for key in (
        "beneficiary_code",
        "government_id",
        "origin_location",
        "current_settlement",
        "support_category",
        "priority_needs",
        "livelihood_type",
        "vulnerability_flags",
    ):
        text_value = _clean_text(raw.get(key), 240 if key in {"priority_needs", "vulnerability_flags"} else 160)
        if text_value:
            normalized[key] = text_value
    relief_gender = _clean_choice(raw.get("relief_gender"), RELIEF_GENDER_VALUES)
    if relief_gender:
        normalized["relief_gender"] = relief_gender
    displacement_status = _clean_choice(raw.get("displacement_status"), RELIEF_DISPLACEMENT_STATUS_VALUES)
    if displacement_status:
        normalized["displacement_status"] = displacement_status
    shelter_status = _clean_choice(raw.get("shelter_status"), RELIEF_SHELTER_STATUS_VALUES)
    if shelter_status:
        normalized["shelter_status"] = shelter_status
    women_count = _clean_int(raw.get("women_count"), minimum=0, maximum=500)
    if women_count is not None:
        normalized["women_count"] = women_count
    children_under_five = _clean_int(raw.get("children_under_five"), minimum=0, maximum=500)
    if children_under_five is not None:
        normalized["children_under_five"] = children_under_five
    elderly_count = _clean_int(raw.get("elderly_count"), minimum=0, maximum=500)
    if elderly_count is not None:
        normalized["elderly_count"] = elderly_count
    disability_count = _clean_int(raw.get("disability_count"), minimum=0, maximum=500)
    if disability_count is not None:
        normalized["disability_count"] = disability_count
    return normalized or None


def _normalize_tree_record_profile_data(value: object, *, existing_area_sqm: float | None = None) -> dict | None:
    raw = _normalize_json_object(value) or {}
    if not raw and existing_area_sqm is None:
        return None
    normalized: dict[str, object] = {}
    for key in ("plot_code", "plot_name", "commodity", "variety", "season_name", "land_use"):
        text_value = _clean_text(raw.get(key), 160)
        if text_value:
            normalized[key] = text_value
    season_year = _clean_int(raw.get("season_year"), minimum=2000, maximum=2100)
    if season_year is not None:
        normalized["season_year"] = season_year
    irrigation_type = _clean_choice(raw.get("irrigation_type"), AGRIC_IRRIGATION_TYPE_VALUES)
    if irrigation_type:
        normalized["irrigation_type"] = irrigation_type
    production_stage = _clean_choice(raw.get("production_stage"), AGRIC_PRODUCTION_STAGE_VALUES)
    if production_stage:
        normalized["production_stage"] = production_stage
    boundary_capture_method = _clean_choice(raw.get("boundary_capture_method"), AGRIC_BOUNDARY_CAPTURE_METHOD_VALUES)
    if boundary_capture_method:
        normalized["boundary_capture_method"] = boundary_capture_method
    estimated_yield_kg = _clean_float(raw.get("estimated_yield_kg"), minimum=0, maximum=100000000)
    if estimated_yield_kg is not None:
        normalized["estimated_yield_kg"] = estimated_yield_kg
    if existing_area_sqm is not None and existing_area_sqm > 0:
        normalized["area_hectares"] = round(float(existing_area_sqm) / 10000.0, 4)
    else:
        area_hectares = _clean_float(raw.get("area_hectares"), minimum=0, maximum=1000000)
        if area_hectares is not None:
            normalized["area_hectares"] = area_hectares
    support_placeholder = _clean_bool(raw.get("support_placeholder"))
    if support_placeholder is not None:
        normalized["support_placeholder"] = support_placeholder
    hidden_from_records = _clean_bool(raw.get("hidden_from_records"))
    if hidden_from_records is not None:
        normalized["hidden_from_records"] = hidden_from_records
    placeholder_reason = _clean_text(raw.get("placeholder_reason"), 120)
    if placeholder_reason:
        normalized["placeholder_reason"] = placeholder_reason
    for key in ("asset_code", "asset_name", "support_package", "safety_risks", "reported_need"):
        text_value = _clean_text(raw.get(key), 240 if key in {"safety_risks", "reported_need"} else 160)
        if text_value:
            normalized[key] = text_value
    asset_type = _clean_choice(raw.get("asset_type"), RELIEF_ASSET_TYPE_VALUES)
    if asset_type:
        normalized["asset_type"] = asset_type
    damage_level = _clean_choice(raw.get("damage_level"), RELIEF_DAMAGE_LEVEL_VALUES)
    if damage_level:
        normalized["damage_level"] = damage_level
    occupancy_status = _clean_choice(raw.get("occupancy_status"), RELIEF_OCCUPANCY_STATUS_VALUES)
    if occupancy_status:
        normalized["occupancy_status"] = occupancy_status
    tenure_status = _clean_choice(raw.get("tenure_status"), RELIEF_TENURE_STATUS_VALUES)
    if tenure_status:
        normalized["tenure_status"] = tenure_status
    response_pathway = _clean_choice(raw.get("response_pathway"), RELIEF_RESPONSE_PATHWAY_VALUES)
    if response_pathway:
        normalized["response_pathway"] = response_pathway
    relief_boundary_capture_method = _clean_choice(raw.get("relief_boundary_capture_method"), RELIEF_BOUNDARY_CAPTURE_METHOD_VALUES)
    if relief_boundary_capture_method:
        normalized["relief_boundary_capture_method"] = relief_boundary_capture_method
    floor_area_sqm = _clean_float(raw.get("floor_area_sqm"), minimum=0, maximum=100000000)
    if floor_area_sqm is not None:
        normalized["floor_area_sqm"] = floor_area_sqm
    rooms_count = _clean_int(raw.get("rooms_count"), minimum=0, maximum=10000)
    if rooms_count is not None:
        normalized["rooms_count"] = rooms_count
    estimated_repair_cost = _clean_float(raw.get("estimated_repair_cost"), minimum=0, maximum=100000000000)
    if estimated_repair_cost is not None:
        normalized["estimated_repair_cost"] = estimated_repair_cost
    population_served = _clean_int(raw.get("population_served"), minimum=0, maximum=100000000)
    if population_served is not None:
        normalized["population_served"] = population_served
    return normalized or None


HIDDEN_PLACEHOLDER_REASONS = {
    "support_visit_before_plot_capture",
    "field_capture_before_plot_capture",
}


def _is_hidden_tree_record(value: object) -> bool:
    raw = _normalize_json_object(value) or {}
    if _clean_bool(raw.get("hidden_from_records")) is True:
        return True
    if _clean_bool(raw.get("support_placeholder")) is True:
        return True
    return _clean_text(raw.get("placeholder_reason"), 120) in HIDDEN_PLACEHOLDER_REASONS


def _get_or_create_support_placeholder_tree(
    db: Session,
    *,
    project_id: int,
    custodian_id: int,
    workflow_profile: str | None = None,
    event_species: str | None = None,
    actor_name: str | None = None,
    placeholder_reason: str = "support_visit_before_plot_capture",
    plot_name: str = "Plot pending capture",
    notes: str | None = None,
) -> dict:
    labels = _get_workflow_labels(workflow_profile)
    placeholder_reason_clean = _clean_text(placeholder_reason, 120) or "support_visit_before_plot_capture"
    existing = db.execute(
        text(
            """
            SELECT id, species, status, planting_date, ST_X(geom) AS lng, ST_Y(geom) AS lat
            FROM trees
            WHERE project_id = :project_id
              AND custodian_id = :custodian_id
              AND LOWER(COALESCE(record_profile_data->>'placeholder_reason', '')) = :placeholder_reason
            ORDER BY created_at ASC, id ASC
            LIMIT 1
            """
        ),
        {
            "project_id": int(project_id),
            "custodian_id": int(custodian_id),
            "placeholder_reason": placeholder_reason_clean,
        },
    ).mappings().first()
    if existing:
        return dict(existing)

    project_tree_no = _next_project_tree_no(db, int(project_id))
    placeholder_species = _clean_text(event_species, 160) or labels["placeholder_species"]
    placeholder_record_profile = _normalize_tree_record_profile_data(
        {
            "plot_name": plot_name,
            "commodity": placeholder_species if placeholder_species != labels["placeholder_species"] else None,
            "asset_name": plot_name,
            "support_package": placeholder_species if placeholder_species != labels["placeholder_species"] else None,
            "support_placeholder": True,
            "hidden_from_records": True,
            "placeholder_reason": placeholder_reason_clean,
        }
    )
    row = db.execute(
        text(
            """
            INSERT INTO trees (
                project_id, project_tree_no, geom, species, planting_date, status, notes, photo_url, photo_urls, created_by,
                tree_origin, custodian_id, custody_started_at, attribution_scope,
                count_in_planting_kpis, count_in_carbon_scope, source_project_id, tree_height_m, tree_age_months,
                inventory_tree_count, existing_area_geojson, existing_area_sqm, record_profile_data
            )
            VALUES (
                :project_id,
                :project_tree_no,
                NULL,
                :species,
                NULL,
                'healthy',
                :notes,
                NULL,
                CAST(:photo_urls AS JSONB),
                :created_by,
                'existing_inventory',
                :custodian_id,
                NULL,
                'monitor_only',
                FALSE,
                FALSE,
                NULL,
                NULL,
                NULL,
                1,
                NULL,
                NULL,
                CAST(:record_profile_data AS JSONB)
            )
            RETURNING id, species, status, planting_date
            """
        ),
        {
            "project_id": int(project_id),
            "project_tree_no": int(project_tree_no),
            "species": placeholder_species,
            "notes": (notes or "").strip()
            or (
                f"Hidden placeholder {labels['entity_singular']} created automatically before field activity capture."
                if placeholder_reason_clean == "field_capture_before_plot_capture"
                else f"Hidden placeholder {labels['entity_singular']} created automatically before the first support visit capture."
            ),
            "photo_urls": _safe_json([]),
            "created_by": (actor_name or "").strip() or "system",
            "custodian_id": int(custodian_id),
            "record_profile_data": _safe_json(placeholder_record_profile),
        },
    ).mappings().first()
    tree_row = {
        "id": int(row.get("id") or 0),
        "species": row.get("species"),
        "status": row.get("status"),
        "planting_date": row.get("planting_date"),
        "lng": None,
        "lat": None,
    }
    _log_audit_event(
        db,
        project_id=int(project_id),
        entity_type="tree",
        entity_id=int(tree_row["id"]),
        action="support_placeholder_created",
        actor=(actor_name or "").strip() or "system",
        details={
            "custodian_id": int(custodian_id),
            "reason": placeholder_reason_clean,
        },
    )
    return tree_row


def _close_pending_field_capture_tasks_for_custodian(
    db: Session,
    *,
    project_id: int,
    custodian_id: int,
    created_tree_id: int,
) -> list[int]:
    rows = db.execute(
        text(
            """
            SELECT t.id
            FROM tree_tasks t
            JOIN trees tr ON tr.id = t.tree_id
            WHERE tr.project_id = :project_id
              AND t.custodian_id = :custodian_id
              AND LOWER(COALESCE(t.task_type, '')) = :task_type
              AND NOT (
                  LOWER(COALESCE(t.review_state, 'none')) = 'approved'
                  OR (
                      LOWER(COALESCE(t.status, '')) IN ('done', 'completed', 'closed')
                      AND LOWER(COALESCE(t.review_state, 'none')) IN ('none', 'approved')
                  )
              )
            """
        ),
        {
            "project_id": int(project_id),
            "custodian_id": int(custodian_id),
            "task_type": FIELD_CAPTURE_TASK_TYPE,
        },
    ).mappings().all()
    task_ids = [int(row.get("id") or 0) for row in rows if int(row.get("id") or 0) > 0]
    if not task_ids:
        return []
    db.execute(
        text(
            """
            UPDATE tree_tasks
            SET
                status = 'done',
                review_state = 'approved',
                completed_at = COALESCE(completed_at, NOW()),
                submitted_at = COALESCE(submitted_at, NOW()),
                notes = CONCAT(
                    COALESCE(NULLIF(notes, ''), ''),
                    CASE WHEN COALESCE(NULLIF(notes, ''), '') = '' THEN '' ELSE E'\n' END,
                    'Field capture completed automatically after plot #',
                    :created_tree_id,
                    ' was saved.'
                )
            WHERE id IN :task_ids
            """
        ).bindparams(bindparam("task_ids", expanding=True)),
        {
            "created_tree_id": int(created_tree_id),
            "task_ids": task_ids,
        },
    )
    return task_ids


def _normalize_photo_urls(value: object) -> list[str]:
    raw: object = value
    if isinstance(raw, str):
        text_value = raw.strip()
        if not text_value:
            return []
        try:
            parsed = json.loads(text_value)
            raw = parsed
        except Exception:
            raw = [text_value]
    if isinstance(raw, tuple):
        raw = list(raw)
    if not isinstance(raw, list):
        return []
    seen: set[str] = set()
    items: list[str] = []
    for item in raw:
        url = str(item or "").strip()
        if not url or url in seen:
            continue
        seen.add(url)
        items.append(url)
    return items[:30]


def _merge_photo_evidence(photo_url: str | None, photo_urls: object) -> tuple[str | None, list[str]]:
    merged = _normalize_photo_urls(photo_urls)
    single = (photo_url or "").strip()
    if single and single not in merged:
        merged.append(single)
    primary = merged[-1] if merged else None
    return primary, merged


def _is_valid_position_pair(point: object) -> bool:
    if not isinstance(point, (list, tuple)) or len(point) < 2:
        return False
    try:
        float(point[0])
        float(point[1])
        return True
    except Exception:
        return False


def _is_valid_line_string(points: object, minimum_points: int = 2) -> bool:
    if not isinstance(points, list) or len(points) < minimum_points:
        return False
    return all(_is_valid_position_pair(point) for point in points)


def _is_valid_linear_ring(ring: object) -> bool:
    if not isinstance(ring, list) or len(ring) < 4:
        return False
    return _is_valid_line_string(ring, minimum_points=4)


def _normalize_work_area_geojson(value: dict | str | None) -> dict | None:
    if value is None:
        return None

    raw: object = value
    if isinstance(raw, str):
        raw = raw.strip()
        if not raw:
            return None
        try:
            raw = json.loads(raw)
        except Exception:
            return None

    if not isinstance(raw, dict):
        return None

    geometry = raw.get("geometry") if str(raw.get("type") or "").strip() == "Feature" else raw
    if not isinstance(geometry, dict):
        return None

    geom_type = str(geometry.get("type") or "").strip()
    coords = geometry.get("coordinates")

    if geom_type == "Point":
        if not _is_valid_position_pair(coords):
            return None
        return {"type": "Point", "coordinates": [float(coords[0]), float(coords[1])]}

    if geom_type == "LineString":
        if not _is_valid_line_string(coords):
            return None
        return {"type": "LineString", "coordinates": [[float(point[0]), float(point[1])] for point in coords]}

    if geom_type == "MultiLineString":
        if not isinstance(coords, list) or len(coords) == 0:
            return None
        normalized_lines: list[list[list[float]]] = []
        for line in coords:
            if not _is_valid_line_string(line):
                return None
            normalized_lines.append([[float(point[0]), float(point[1])] for point in line])
        return {"type": "MultiLineString", "coordinates": normalized_lines}

    if geom_type == "Polygon":
        if not isinstance(coords, list) or len(coords) == 0:
            return None
        normalized_rings: list[list[list[float]]] = []
        for ring in coords:
            if not _is_valid_linear_ring(ring):
                return None
            normalized_ring = [[float(point[0]), float(point[1])] for point in ring]
            normalized_rings.append(normalized_ring)
        return {"type": "Polygon", "coordinates": normalized_rings}

    if geom_type == "MultiPolygon":
        if not isinstance(coords, list) or len(coords) == 0:
            return None
        normalized_polygons: list[list[list[list[float]]]] = []
        for polygon in coords:
            if not isinstance(polygon, list) or len(polygon) == 0:
                return None
            normalized_rings: list[list[list[float]]] = []
            for ring in polygon:
                if not _is_valid_linear_ring(ring):
                    return None
                normalized_ring = [[float(point[0]), float(point[1])] for point in ring]
                normalized_rings.append(normalized_ring)
            normalized_polygons.append(normalized_rings)
        return {"type": "MultiPolygon", "coordinates": normalized_polygons}

    return None


def _normalize_polygon_area_geojson(value: dict | str | None) -> dict | None:
    normalized = _normalize_work_area_geojson(value)
    if not normalized:
        return None
    if str(normalized.get("type") or "").strip() not in {"Polygon", "MultiPolygon"}:
        return None
    return normalized


def _is_polygonal_work_area(value: dict | str | None) -> bool:
    normalized = _normalize_work_area_geojson(value)
    if not normalized:
        return False
    return str(normalized.get("type") or "").strip() in {"Polygon", "MultiPolygon"}


def _compute_existing_area_sqm(db: Session, geometry: dict | None) -> float | None:
    if not geometry:
        return None
    geom_type = str(geometry.get("type") or "").strip()
    if geom_type not in {"Polygon", "MultiPolygon"}:
        return 0.0
    try:
        return float(
            db.execute(
                text(
                    """
                    SELECT ST_Area(
                        ST_Transform(
                            ST_SetSRID(ST_GeomFromGeoJSON(:geojson), 4326),
                            3857
                        )
                    )
                    """
                ),
                {"geojson": _safe_json(geometry)},
            ).scalar()
            or 0.0
        )
    except Exception as exc:
        raise HTTPException(status_code=400, detail="Invalid existing_area_geojson") from exc


def _get_maintenance_intervals(activity: str, tree_age_days: int, season: str) -> dict:
    activity_key = _normalize_name(activity)
    season_key = "dry" if _normalize_name(season) == "dry" else "rainy"
    age = max(int(tree_age_days or 0), 0)

    if activity_key == "watering":
        if season_key == "rainy":
            return {"first_days": 0, "repeat_days": 14 if age < 90 else 21}
        return {"first_days": 0, "repeat_days": 5 if age < 90 else 7}

    if activity_key == "weeding":
        if season_key == "rainy":
            if age < 365:
                return {"first_days": 21, "repeat_days": 45}
            if age < 730:
                return {"first_days": 30, "repeat_days": 90}
            return {"first_days": 30, "repeat_days": 150}
        if age < 365:
            return {"first_days": 35, "repeat_days": 90}
        if age < 730:
            return {"first_days": 45, "repeat_days": 150}
        return {"first_days": 45, "repeat_days": 210}

    if activity_key == "protection":
        if season_key == "rainy":
            return {"first_days": 0, "repeat_days": 45}
        return {"first_days": 0, "repeat_days": 21}

    if activity_key == "inspection":
        if season_key == "rainy":
            return {"first_days": 14, "repeat_days": 30 if age < 180 else 90}
        return {"first_days": 7, "repeat_days": 21 if age < 180 else 60}

    if activity_key == "replacement":
        if season_key == "rainy":
            return {"first_days": 42, "repeat_days": 180}
        return {"first_days": 56, "repeat_days": 210}

    return {"first_days": 30, "repeat_days": 90}


def _should_skip_existing_tree_routine_activity(
    activity: str,
    tree_origin: str,
    tree_age_days: int | None,
    tree_status: str,
    has_open_task: bool,
) -> bool:
    origin_key = _normalize_tree_origin(tree_origin)
    activity_key = _normalize_name(activity)
    status_key = _normalize_tree_status(tree_status)
    if origin_key != "existing_inventory" or has_open_task:
        return False
    if activity_key == "watering":
        if status_key == "need_watering":
            return False
        return tree_age_days is None or tree_age_days >= 365
    if activity_key == "weeding":
        return tree_age_days is None or tree_age_days >= 730
    return False


def _point_in_ring(lng: float, lat: float, ring: list[list[float]]) -> bool:
    if not isinstance(ring, list) or len(ring) < 4:
        return False
    inside = False
    j = len(ring) - 1
    for i in range(len(ring)):
        try:
            xi, yi = float(ring[i][0]), float(ring[i][1])
            xj, yj = float(ring[j][0]), float(ring[j][1])
        except Exception:
            j = i
            continue
        intersects = ((yi > lat) != (yj > lat)) and (
            lng < ((xj - xi) * (lat - yi) / ((yj - yi) or 1e-12) + xi)
        )
        if intersects:
            inside = not inside
        j = i
    return inside


def _point_in_polygon_geojson(lng: float, lat: float, geometry: dict | None) -> bool:
    if not isinstance(geometry, dict):
        return False
    geom_type = str(geometry.get("type") or "").strip()
    coordinates = geometry.get("coordinates")
    if geom_type == "Polygon":
        polygons = [coordinates]
    elif geom_type == "MultiPolygon":
        polygons = coordinates if isinstance(coordinates, list) else []
    else:
        return False
    for polygon in polygons:
        if not isinstance(polygon, list) or not polygon:
            continue
        outer = polygon[0]
        holes = polygon[1:] if len(polygon) > 1 else []
        if not _point_in_ring(lng, lat, outer):
            continue
        if any(_point_in_ring(lng, lat, hole) for hole in holes if isinstance(hole, list)):
            continue
        return True
    return False


def _serialize_remote_monitoring_area(row: dict | None) -> dict | None:
    if not row:
        return None
    item = dict(row)
    raw_geojson = item.get("area_geojson")
    if isinstance(raw_geojson, str):
        try:
            raw_geojson = json.loads(raw_geojson)
        except Exception:
            raw_geojson = None
    item["area_geojson"] = _normalize_work_area_geojson(raw_geojson)
    item["area_sqm"] = float(item.get("area_sqm") or 0.0) if item.get("area_sqm") is not None else None
    item["tree_count"] = int(item.get("tree_count") or 0)
    item["tree_record_count"] = int(item.get("tree_record_count") or 0)
    item["new_planting_tree_count"] = int(item.get("new_planting_tree_count") or 0)
    item["existing_inventory_tree_count"] = int(item.get("existing_inventory_tree_count") or 0)
    item["other_tree_count"] = int(item.get("other_tree_count") or 0)
    return item


def _is_remote_monitoring_schema_error(exc: Exception) -> bool:
    message = str(exc or "").strip().lower()
    if not message:
        return False
    return (
        "green_remote_monitoring_areas" in message
        and (
            "does not exist" in message
            or "undefinedtable" in message
            or "undefined column" in message
            or "undefinedcolumn" in message
        )
    )


def _run_remote_monitoring_query(db: Session, statement: str, params: dict | None = None):
    query_params = params or {}
    try:
        return db.execute(text(statement), query_params)
    except Exception as exc:
        if not _is_remote_monitoring_schema_error(exc):
            raise
        db.rollback()
        ensure_green_tables(db)
        db.commit()
        return db.execute(text(statement), query_params)


def _count_trees_in_geojson(db: Session, *, project_id: int, area_geojson: dict) -> dict[str, int]:
    row = db.execute(
        text(
            """
            SELECT
                COUNT(*) AS tree_record_count,
                COALESCE(SUM(GREATEST(COALESCE(inventory_tree_count, 1), 1)), 0) AS tree_count,
                COALESCE(
                    SUM(
                        CASE
                            WHEN LOWER(COALESCE(tree_origin, 'new_planting')) = 'new_planting'
                            THEN GREATEST(COALESCE(inventory_tree_count, 1), 1)
                            ELSE 0
                        END
                    ),
                    0
                ) AS new_planting_tree_count,
                COALESCE(
                    SUM(
                        CASE
                            WHEN LOWER(COALESCE(tree_origin, 'new_planting')) = 'existing_inventory'
                            THEN GREATEST(COALESCE(inventory_tree_count, 1), 1)
                            ELSE 0
                        END
                    ),
                    0
                ) AS existing_inventory_tree_count,
                COALESCE(
                    SUM(
                        CASE
                            WHEN LOWER(COALESCE(tree_origin, 'new_planting')) NOT IN ('new_planting', 'existing_inventory')
                            THEN GREATEST(COALESCE(inventory_tree_count, 1), 1)
                            ELSE 0
                        END
                    ),
                    0
                ) AS other_tree_count
            FROM trees
            WHERE project_id = :project_id
              AND geom IS NOT NULL
              AND ST_Contains(
                    ST_SetSRID(ST_GeomFromGeoJSON(:geojson), 4326),
                    geom
              )
            """
        ),
        {"project_id": int(project_id), "geojson": _safe_json(area_geojson)},
    ).mappings().first()
    return {
        "tree_record_count": int(row.get("tree_record_count") or 0) if row else 0,
        "tree_count": int(row.get("tree_count") or 0) if row else 0,
        "new_planting_tree_count": int(row.get("new_planting_tree_count") or 0) if row else 0,
        "existing_inventory_tree_count": int(row.get("existing_inventory_tree_count") or 0) if row else 0,
        "other_tree_count": int(row.get("other_tree_count") or 0) if row else 0,
    }


def _list_trees_in_geojson(db: Session, *, project_id: int, area_geojson: dict) -> list[dict]:
    rows = db.execute(
        text(
            """
            SELECT
                id,
                project_id,
                project_tree_no,
                species,
                planting_date,
                status,
                tree_origin,
                created_by,
                created_at,
                COALESCE(inventory_tree_count, 1) AS inventory_tree_count,
                ST_X(geom) AS lng,
                ST_Y(geom) AS lat
            FROM trees
            WHERE project_id = :project_id
              AND geom IS NOT NULL
              AND ST_Contains(
                    ST_SetSRID(ST_GeomFromGeoJSON(:geojson), 4326),
                    geom
              )
            ORDER BY COALESCE(project_tree_no, 99999999) ASC, id ASC
            """
        ),
        {"project_id": int(project_id), "geojson": _safe_json(area_geojson)},
    ).mappings().all()
    items = [dict(row) for row in rows]
    for item in items:
        item["profile_data"] = _normalize_custodian_profile_data(item.get("profile_data"))
    return items


def _compute_geojson_area_sqm(db: Session, *, area_geojson: dict) -> float:
    try:
        return float(
            db.execute(
                text(
                    """
                    SELECT ST_Area(
                        ST_Transform(
                            ST_SetSRID(ST_GeomFromGeoJSON(:geojson), 4326),
                            3857
                        )
                    )
                    """
                ),
                {"geojson": _safe_json(area_geojson)},
            ).scalar()
            or 0.0
        )
    except Exception as exc:
        raise HTTPException(status_code=400, detail="Invalid monitoring polygon") from exc


def _find_matching_auto_first_cycle_work_order(
    db: Session,
    *,
    project_id: int,
    assignee_name: str,
    species: str | None,
    lng: float,
    lat: float,
) -> dict | None:
    assignee_clean = (assignee_name or "").strip()
    if not assignee_clean:
        return None
    rows = db.execute(
        text(
            """
            SELECT id, assignee_name, maintenance_schedule, species_allocations,
                   COALESCE(area_enabled, FALSE) AS area_enabled, area_geojson,
                   status, created_at
            FROM green_work_orders
            WHERE project_id = :project_id
              AND work_type = 'planting'
              AND COALESCE(auto_assign_first_cycle_maintenance, FALSE) = TRUE
              AND LOWER(TRIM(assignee_name)) = LOWER(TRIM(:assignee_name))
              AND LOWER(COALESCE(status, 'assigned')) NOT IN ('done', 'completed', 'closed', 'cancelled')
            ORDER BY created_at DESC, id DESC
            """
        ),
        {"project_id": int(project_id), "assignee_name": assignee_clean},
    ).mappings().all()
    species_key = _normalize_name(species)
    for raw in rows:
        item = dict(raw)
        raw_species_allocations = item.get("species_allocations")
        if isinstance(raw_species_allocations, str):
            try:
                raw_species_allocations = json.loads(raw_species_allocations)
            except Exception:
                raw_species_allocations = []
        normalized_species_allocations = _normalize_species_allocations(raw_species_allocations)
        if normalized_species_allocations:
            allowed_keys = {
                _normalize_name(entry.get("species"))
                for entry in normalized_species_allocations
                if str(entry.get("species") or "").strip()
            }
            if not species_key or species_key not in allowed_keys:
                continue

        area_enabled = bool(item.get("area_enabled"))
        if area_enabled:
            raw_geojson = item.get("area_geojson")
            if isinstance(raw_geojson, str):
                try:
                    raw_geojson = json.loads(raw_geojson)
                except Exception:
                    raw_geojson = None
            normalized_geojson = _normalize_work_area_geojson(raw_geojson) if raw_geojson else None
            if not normalized_geojson or not _point_in_polygon_geojson(lng, lat, normalized_geojson):
                continue
        return item
    return None


def _auto_assign_first_cycle_maintenance_from_order(
    db: Session,
    *,
    project_id: int,
    tree_id: int,
    assignee_name: str,
    planting_date_value: str | None,
    order_row: dict,
) -> list[int]:
    assignee_clean = (assignee_name or "").strip()
    if not assignee_clean:
        return []
    base_date = _parse_date_value(planting_date_value) or date.today()
    season_key = _normalize_name(order_row.get("maintenance_schedule"))
    if season_key not in SEASON_VALUES:
        season_key = "rainy"
    created_task_ids: list[int] = []
    for activity in ("watering", "weeding", "protection", "inspection"):
        existing_task_id = db.execute(
            text(
                """
                SELECT id
                FROM tree_tasks
                WHERE tree_id = :tree_id
                  AND LOWER(task_type) = :task_type
                LIMIT 1
                """
            ),
            {"tree_id": int(tree_id), "task_type": activity},
        ).scalar()
        if existing_task_id:
            continue
        intervals = _get_maintenance_intervals(activity, 0, season_key)
        due_date = _add_days(base_date, int(intervals.get("first_days") or 0))
        task_id = db.execute(
            text(
                """
                INSERT INTO tree_tasks (
                    tree_id, task_type, assignee_name, due_date, priority, status, notes,
                    review_state, auto_generated, model_season
                )
                VALUES (
                    :tree_id, :task_type, :assignee_name, :due_date, 'normal', 'pending', :notes,
                    'none', FALSE, :model_season
                )
                RETURNING id
                """
            ),
            {
                "tree_id": int(tree_id),
                "task_type": activity,
                "assignee_name": assignee_clean,
                "due_date": _to_date_input(due_date),
                "notes": f"Auto-assigned first-cycle maintenance from planting order #{int(order_row.get('id') or 0)}.",
                "model_season": season_key,
            },
        ).scalar()
        if not task_id:
            continue
        created_task_ids.append(int(task_id))
        _log_audit_event(
            db,
            project_id=int(project_id),
            entity_type="task",
            entity_id=int(task_id),
            action="first_cycle_task_auto_assigned",
            actor="system",
            details={
                "tree_id": int(tree_id),
                "source_work_order_id": int(order_row.get("id") or 0),
                "task_type": activity,
                "due_date": _to_date_input(due_date),
                "season": season_key,
            },
        )
    return created_task_ids


def _get_lifecycle_start_date(planting_date_obj: date | None, replacement_done_obj: date | None) -> date | None:
    if planting_date_obj and replacement_done_obj:
        return replacement_done_obj if replacement_done_obj > planting_date_obj else planting_date_obj
    return replacement_done_obj or planting_date_obj


def _get_project_id_for_tree(db: Session, tree_id: int) -> int | None:
    return db.execute(
        text("SELECT project_id FROM trees WHERE id = :tree_id"),
        {"tree_id": tree_id},
    ).scalar()


def _get_project_settings(db: Session, project_id: int) -> dict:
    row = db.execute(
        text(
            """
            SELECT id, workflow_profile, agric_config, relief_config, planting_model, allow_existing_tree_link, default_existing_tree_scope
            FROM tree_projects
            WHERE id = :project_id
            """
        ),
        {"project_id": project_id},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Project not found")
    return {
        "id": int(row.get("id")),
        "workflow_profile": _normalize_workflow_profile(row.get("workflow_profile")),
        "agric_config": _normalize_agric_config(row.get("agric_config")),
        "relief_config": _normalize_relief_config(row.get("relief_config")),
        "planting_model": _normalize_planting_model(row.get("planting_model")),
        "allow_existing_tree_link": bool(row.get("allow_existing_tree_link")),
        "default_existing_tree_scope": _normalize_existing_tree_scope(row.get("default_existing_tree_scope")),
    }


def _record_tree_status_history(
    db: Session,
    tree_id: int,
    status: str,
    project_id: int | None = None,
    status_date: date | datetime | str | None = None,
    source: str = "manual",
    source_task_id: int | None = None,
    changed_by: str | None = None,
    notes: str | None = None,
):
    normalized_status = _normalize_tree_status(status)
    if normalized_status not in TREE_STATUS_VALUES:
        return

    resolved_project_id = int(project_id) if project_id is not None else _get_project_id_for_tree(db, tree_id)
    if resolved_project_id is None:
        return

    resolved_date = _parse_date_value(status_date) or date.today()
    existing = db.execute(
        text(
            """
            SELECT id
            FROM green_tree_status_history
            WHERE tree_id = :tree_id
              AND status = :status
              AND status_date = :status_date
              AND COALESCE(source, '') = COALESCE(:source, '')
              AND COALESCE(source_task_id, 0) = COALESCE(:source_task_id, 0)
            ORDER BY id DESC
            LIMIT 1
            """
        ),
        {
            "tree_id": int(tree_id),
            "status": normalized_status,
            "status_date": resolved_date,
            "source": source or "manual",
            "source_task_id": source_task_id,
        },
    ).scalar()
    if existing:
        return

    db.execute(
        text(
            """
            INSERT INTO green_tree_status_history (
                tree_id, project_id, status, status_date, source, source_task_id, changed_by, notes
            )
            VALUES (
                :tree_id, :project_id, :status, :status_date, :source, :source_task_id, :changed_by, :notes
            )
            """
        ),
        {
            "tree_id": int(tree_id),
            "project_id": int(resolved_project_id),
            "status": normalized_status,
            "status_date": resolved_date,
            "source": source or "manual",
            "source_task_id": source_task_id,
            "changed_by": (changed_by or "").strip() or None,
            "notes": notes or None,
        },
    )


def _get_project_id_for_task(db: Session, task_id: int) -> int | None:
    return db.execute(
        text("""
            SELECT tr.project_id
            FROM tree_tasks t
            JOIN trees tr ON tr.id = t.tree_id
            WHERE t.id = :task_id
        """),
        {"task_id": task_id},
    ).scalar()


def _log_audit_event(
    db: Session,
    project_id: int | None,
    entity_type: str,
    entity_id: int | None,
    action: str,
    actor: str | None = None,
    details: dict | None = None,
):
    db.execute(
        text("""
            INSERT INTO green_audit_events (
                project_id, entity_type, entity_id, action, actor, details
            )
            VALUES (:project_id, :entity_type, :entity_id, :action, :actor, CAST(:details AS JSONB))
        """),
        {
            "project_id": project_id,
            "entity_type": entity_type,
            "entity_id": entity_id,
            "action": action,
            "actor": actor,
            "details": _safe_json(details),
        },
    )


def _get_species_maturity_map(project_id: int, db: Session) -> dict[str, int]:
    rows = db.execute(
        text("""
            SELECT species_key, maturity_years
            FROM green_species_maturity
            WHERE project_id = :project_id
        """),
        {"project_id": project_id},
    ).mappings().all()
    result: dict[str, int] = {}
    for row in rows:
        key = _normalize_name(row.get("species_key"))
        years = int(row.get("maturity_years") or 0)
        if key and years > 0:
            result[key] = years
    return result


def _task_needs_evidence(task_type: str | None) -> dict:
    # Premium default: every maintenance completion requires note + photo proof.
    activity = _normalize_name(task_type)
    if activity in ASSIGNABLE_TASK_TYPES:
        return {"require_notes": True, "require_photo": True}
    return {"require_notes": False, "require_photo": False}


def _has_required_evidence(
    task_type: str | None,
    notes: str | None,
    photo_url: str | None,
    photo_urls: object = None,
) -> tuple[bool, str]:
    policy = _task_needs_evidence(task_type)
    notes_ok = bool((notes or "").strip())
    merged_primary, merged_urls = _merge_photo_evidence(photo_url, photo_urls)
    photo_ok = bool(merged_primary) or bool(merged_urls)
    if policy["require_notes"] and not notes_ok:
        return False, "Notes are required before submission."
    if policy["require_photo"] and not photo_ok:
        return False, "Photo proof is required before submission."
    return True, ""


def _is_replacement_trigger_status(status: str | None) -> bool:
    return _normalize_tree_status(status) in REPLACEMENT_TRIGGER_STATUSES


def _tree_status_color_hex(status: str | None) -> str:
    return TREE_STATUS_COLOR_HEX.get(_normalize_tree_status(status), "22c55e")


def _record_alert(
    db: Session,
    project_id: int,
    alert_type: str,
    severity: str,
    message: str,
    tree_id: int | None = None,
    task_id: int | None = None,
    payload: dict | None = None,
):
    existing = db.execute(
        text("""
            SELECT id
            FROM green_alerts
            WHERE project_id = :project_id
              AND COALESCE(tree_id, 0) = COALESCE(:tree_id, 0)
              AND COALESCE(task_id, 0) = COALESCE(:task_id, 0)
              AND alert_type = :alert_type
              AND status = 'open'
            LIMIT 1
        """),
        {
            "project_id": project_id,
            "tree_id": tree_id,
            "task_id": task_id,
            "alert_type": alert_type,
        },
    ).scalar()
    if existing:
        return existing
    return db.execute(
        text("""
            INSERT INTO green_alerts (
                project_id, tree_id, task_id, alert_type, severity, message, payload
            )
            VALUES (
                :project_id, :tree_id, :task_id, :alert_type, :severity, :message, CAST(:payload AS JSONB)
            )
            RETURNING id
        """),
        {
            "project_id": project_id,
            "tree_id": tree_id,
            "task_id": task_id,
            "alert_type": alert_type,
            "severity": severity,
            "message": message,
            "payload": _safe_json(payload),
        },
    ).scalar()


def _resolve_task_alerts(db: Session, task_id: int):
    db.execute(
        text("""
            UPDATE green_alerts
            SET status = 'resolved',
                resolved_at = NOW()
            WHERE task_id = :task_id
              AND status = 'open'
        """),
        {"task_id": task_id},
    )


def _refresh_project_alerts(db: Session, project_id: int):
    db.execute(
        text("""
            DELETE FROM green_alerts
            WHERE project_id = :project_id
              AND status = 'open'
              AND alert_type IN ('task_overdue', 'task_due_soon', 'task_submitted', 'missing_evidence')
        """),
        {"project_id": project_id},
    )

    rows = db.execute(
        text("""
            SELECT t.id AS task_id, t.tree_id, t.task_type, t.assignee_name, t.status, t.review_state,
                   t.due_date, t.notes, t.photo_url, t.completed_at,
                   tr.project_id
            FROM tree_tasks t
            JOIN trees tr ON tr.id = t.tree_id
            WHERE tr.project_id = :project_id
        """),
        {"project_id": project_id},
    ).mappings().all()

    today = date.today()
    due_soon_limit = today + timedelta(days=3)
    for row in rows:
        task_id = int(row["task_id"])
        tree_id = int(row["tree_id"])
        status = _normalize_name(row.get("status"))
        review_state = _normalize_name(row.get("review_state"))
        due_date = _parse_date_value(row.get("due_date"))
        evidence_ok, _ = _has_required_evidence(row.get("task_type"), row.get("notes"), row.get("photo_url"))

        if review_state == "submitted":
            _record_alert(
                db,
                project_id=project_id,
                alert_type="task_submitted",
                severity="warning",
                message=f"Task #{task_id} is awaiting supervisor review.",
                tree_id=tree_id,
                task_id=task_id,
                payload={"review_state": review_state},
            )

        if status != "done" and due_date:
            if due_date < today:
                days = abs(_day_diff(due_date, today))
                _record_alert(
                    db,
                    project_id=project_id,
                    alert_type="task_overdue",
                    severity="danger",
                    message=f"Task #{task_id} overdue by {days} day{'s' if days != 1 else ''}.",
                    tree_id=tree_id,
                    task_id=task_id,
                    payload={"due_date": _to_date_input(due_date)},
                )
            elif due_date <= due_soon_limit:
                left_days = max(_day_diff(due_date, today), 0)
                _record_alert(
                    db,
                    project_id=project_id,
                    alert_type="task_due_soon",
                    severity="warning",
                    message=f"Task #{task_id} due in {left_days} day{'s' if left_days != 1 else ''}.",
                    tree_id=tree_id,
                    task_id=task_id,
                    payload={"due_date": _to_date_input(due_date)},
                )

        if _is_done_status(status) and review_state == "submitted" and not evidence_ok:
            _record_alert(
                db,
                project_id=project_id,
                alert_type="missing_evidence",
                severity="danger",
                message=f"Task #{task_id} submitted without complete evidence.",
                tree_id=tree_id,
                task_id=task_id,
                payload={"task_type": row.get("task_type")},
            )


def _compute_live_maintenance_rows(
    db: Session,
    project_id: int,
    season_mode: str = "rainy",
    assignee_name: str | None = None,
    tree_scope: str = "new_planting",
) -> dict:
    season = "dry" if _normalize_name(season_mode) == "dry" else "rainy"
    assignee_key = _normalize_name(assignee_name)
    scope_key = _normalize_name(tree_scope or "new_planting")
    if scope_key not in {"new_planting", "existing_inventory", "all"}:
        scope_key = "new_planting"
    trees = db.execute(
        text("""
            SELECT
                id,
                created_by,
                status,
                species,
                planting_date,
                tree_origin,
                created_at,
                tree_age_months,
                COALESCE(count_in_planting_kpis, TRUE) AS count_in_planting_kpis
            FROM trees
            WHERE project_id = :project_id
            ORDER BY id ASC
        """),
        {"project_id": project_id},
    ).mappings().all()
    filtered_trees: list[dict] = []
    for row in trees:
        item = dict(row)
        origin_key = _normalize_tree_origin(item.get("tree_origin"))
        in_new_scope = origin_key == "new_planting" and bool(item.get("count_in_planting_kpis", True))
        in_existing_scope = origin_key == "existing_inventory"
        if scope_key == "new_planting" and not in_new_scope:
            continue
        if scope_key == "existing_inventory" and not in_existing_scope:
            continue
        filtered_trees.append(item)
    task_rows = db.execute(
        text("""
            SELECT t.id, t.tree_id, t.task_type, t.assignee_name, t.status, t.review_state, t.due_date,
                   t.priority, t.notes, t.photo_url, t.created_at, t.completed_at, t.submitted_at
            FROM tree_tasks t
            JOIN trees tr ON tr.id = t.tree_id
            WHERE tr.project_id = :project_id
              AND (:assignee_name IS NULL OR t.assignee_name = :assignee_name)
            ORDER BY t.created_at DESC
        """),
        {"project_id": project_id, "assignee_name": assignee_name},
    ).mappings().all()

    species_maturity_map = _get_species_maturity_map(project_id, db)
    task_buckets: dict[str, list[dict]] = {}
    planting_task_buckets: dict[int, list[dict]] = {}
    for task in task_rows:
        task_type_key = _normalize_name(task.get("task_type"))
        tree_id = int(task.get("tree_id") or 0)
        task_item = dict(task)
        if task_type_key == "planting" and tree_id > 0:
            planting_task_buckets.setdefault(tree_id, []).append(task_item)
        if task_type_key not in MAINTENANCE_ACTIVITY_ORDER:
            continue
        key = f"{tree_id}:{task_type_key}"
        task_buckets.setdefault(key, []).append(task_item)

    today = date.today()
    rows: list[dict] = []
    for tree in filtered_trees:
        tree_id = int(tree["id"])
        tree_assignee = str(tree.get("created_by") or "-")
        origin_key = _normalize_tree_origin(tree.get("tree_origin"))
        if assignee_key:
            has_matching_task = any(
                _normalize_name(str(task.get("assignee_name") or "")) == assignee_key and int(task["tree_id"]) == tree_id
                for task in task_rows
            )
            if _normalize_name(tree_assignee) != assignee_key and not has_matching_task:
                continue

        tree_status = _normalize_tree_status(tree.get("status") or "alive")
        planting_submission_task = None
        if tree_status == "pending_planting":
            planting_rows = planting_task_buckets.get(tree_id, [])
            submitted_plantings = [
                task
                for task in planting_rows
                if _is_done_status(task.get("status")) and _normalize_name(task.get("review_state")) == "submitted"
            ]
            submitted_plantings.sort(
                key=lambda task: _parse_date_value(task.get("submitted_at") or task.get("created_at") or task.get("due_date")) or date.min,
                reverse=True,
            )
            planting_submission_task = submitted_plantings[0] if submitted_plantings else None
            if not planting_submission_task:
                # No submitted planting evidence yet, so no provisional maintenance preview.
                continue
        provisional_pending_approval = tree_status == "pending_planting" and planting_submission_task is not None
        replacement_required = _is_replacement_trigger_status(tree_status)
        planting_date_obj = _parse_date_value(tree.get("planting_date"))
        inferred_tree_age_days = _infer_tree_age_days_for_maintenance(tree, today)
        replacement_key = f"{tree_id}:replacement"
        replacement_done = sorted(
            [
                _parse_date_value(task.get("completed_at") or task.get("due_date") or task.get("created_at"))
                for task in task_buckets.get(replacement_key, [])
                if _is_done_status(task.get("status")) and _normalize_name(task.get("review_state")) in {"approved", "none"}
            ],
            reverse=True,
        )
        latest_replacement_date = replacement_done[0] if replacement_done else None
        base_lifecycle_start = planting_date_obj
        if base_lifecycle_start is None and inferred_tree_age_days is not None:
            base_lifecycle_start = _add_days(today, -int(inferred_tree_age_days))
        lifecycle_start = _get_lifecycle_start_date(base_lifecycle_start, latest_replacement_date)
        tree_age_days = _day_diff(today, lifecycle_start) if lifecycle_start else inferred_tree_age_days
        species_key = _normalize_name(tree.get("species"))
        maturity_years = species_maturity_map.get(species_key) if species_key else None
        maturity_reached = (
            tree_status in HEALTHY_TREE_STATUSES
            and maturity_years is not None
            and tree_age_days is not None
            and tree_age_days >= maturity_years * 365
        )

        for activity in MAINTENANCE_ACTIVITY_ORDER:
            if activity == "replacement" and not replacement_required:
                # Replacement is condition-triggered only; hide it unless current tree status requires it.
                continue
            bucket = task_buckets.get(f"{tree_id}:{activity}", [])
            done_tasks = [
                task
                for task in bucket
                if _is_done_status(task.get("status")) and _normalize_name(task.get("review_state")) in {"approved", "none"}
            ]
            open_tasks = [task for task in bucket if not (_is_done_status(task.get("status")) and _normalize_name(task.get("review_state")) in {"approved", "none"})]
            done_tasks.sort(
                key=lambda task: _parse_date_value(task.get("completed_at") or task.get("due_date") or task.get("created_at")) or date.min,
                reverse=True,
            )
            open_tasks.sort(
                key=lambda task: _parse_date_value(task.get("due_date") or task.get("created_at")) or date.max,
            )
            latest_done = done_tasks[0] if done_tasks else None
            active_task = open_tasks[0] if open_tasks else None

            if _should_skip_existing_tree_routine_activity(
                activity,
                origin_key,
                tree_age_days,
                tree_status,
                bool(active_task),
            ):
                continue

            status_text = "No open task"
            tone = "ok"
            indicator = "On schedule"
            model_due: date | None = None
            assigned_due = _parse_date_value(active_task.get("due_date")) if active_task else None

            if replacement_required and activity != "replacement":
                tone = "danger"
                status_text = "Paused"
                indicator = f"Tree status '{tree_status.replace('_', ' ')}' requires replacement first."
            elif activity == "replacement" and replacement_required:
                model_due = today
                if active_task:
                    tone = "warning"
                    status_text = f"Task #{active_task['id']} {active_task.get('status') or 'pending'}"
                    indicator = "Replacement assigned."
                else:
                    tone = "danger"
                    status_text = "Replacement required"
                    indicator = "Replacement due immediately."
            elif tree_status == "need_watering" and activity == "watering":
                model_due = today
                tone = "warning"
                status_text = f"Task #{active_task['id']} {active_task.get('status') or 'pending'}" if active_task else "Action required"
                indicator = "Inspection flagged need watering. Due immediately."
            elif tree_status == "need_protection" and activity == "protection":
                model_due = today
                tone = "warning"
                status_text = f"Task #{active_task['id']} {active_task.get('status') or 'pending'}" if active_task else "Action required"
                indicator = "Inspection flagged need protection. Due immediately."
            elif maturity_reached:
                tone = "info"
                status_text = "Lifecycle complete"
                indicator = f"Tree reached maturity (~{maturity_years} years)."
            else:
                intervals = _get_maintenance_intervals(activity, tree_age_days or 0, season)
                latest_done_date = _parse_date_value(
                    latest_done.get("completed_at") if latest_done else None
                ) or _parse_date_value(latest_done.get("due_date") if latest_done else None) or _parse_date_value(
                    latest_done.get("created_at") if latest_done else None
                )
                if latest_done_date:
                    model_due = _add_days(latest_done_date, intervals["repeat_days"])
                elif lifecycle_start:
                    model_due = _add_days(lifecycle_start, intervals["first_days"])

                if active_task:
                    rs = _normalize_name(active_task.get("review_state"))
                    if rs == "submitted":
                        status_text = f"Task #{active_task['id']} submitted"
                    elif rs == "rejected":
                        status_text = f"Task #{active_task['id']} rejected"
                    else:
                        status_text = f"Task #{active_task['id']} {active_task.get('status') or 'pending'}"

            effective_due: date | None = None
            if model_due and assigned_due:
                effective_due = model_due if model_due <= assigned_due else assigned_due
            else:
                effective_due = model_due or assigned_due

            countdown_days = _day_diff(effective_due, today) if effective_due else None
            if countdown_days is not None:
                if countdown_days < 0:
                    tone = "danger"
                    indicator = f"Not done, overdue by {abs(countdown_days)} day{'s' if abs(countdown_days) != 1 else ''}."
                elif countdown_days == 0:
                    tone = "warning"
                    indicator = "Due today."
                elif countdown_days <= 7:
                    tone = "warning"
                    indicator = f"Due in {countdown_days} day{'s' if countdown_days != 1 else ''}."

            overdue_open = 0
            for task in open_tasks:
                due = _parse_date_value(task.get("due_date"))
                if due and due < today:
                    overdue_open += 1

            intervals = _get_maintenance_intervals(activity, tree_age_days or 0, season)
            if activity == "replacement":
                rationale = (
                    "Replacement is condition-triggered (dead/damaged/removed/needs replacement) "
                    "and is not treated as a routine cyclical task."
                )
            else:
                rationale = f"{season.title()} season model: first {intervals['first_days']}d, repeat {intervals['repeat_days']}d."

            if provisional_pending_approval:
                planting_task_label = f"Planting task #{int(planting_submission_task['id'])}" if planting_submission_task else "Planting task"
                status_text = f"{planting_task_label} submitted (awaiting supervisor approval)"
                if countdown_days is None:
                    tone = "warning"
                    indicator = "Provisional preview while planting approval is pending."
                elif countdown_days < 0:
                    tone = "danger"
                    indicator = (
                        f"Provisional: due from planting date and now {abs(countdown_days)} day"
                        f"{'s' if abs(countdown_days) != 1 else ''} overdue while approval is pending."
                    )
                elif countdown_days == 0:
                    tone = "warning"
                    indicator = "Provisional: due today from planting date once approved."
                elif countdown_days <= 7:
                    tone = "warning"
                    indicator = f"Provisional: due in {countdown_days} day{'s' if countdown_days != 1 else ''} from planting date."
                else:
                    tone = "info"
                    indicator = f"Provisional: scheduled from planting date in {countdown_days} day{'s' if countdown_days != 1 else ''}."
                rationale = (
                    f"{rationale} Provisional preview only: planting submission is awaiting supervisor approval. "
                    "Rows are shown for planning visibility, but maintenance workflow becomes active after approval."
                )

            rows.append(
                {
                    "key": f"{tree_id}:{activity}",
                    "treeId": tree_id,
                    "treeOrigin": origin_key,
                    "assignee": tree_assignee,
                    "activity": activity,
                    "activityLabel": activity.replace("_", " ").title(),
                    "plantingDate": _to_date_input(planting_date_obj),
                    "treeAgeDays": tree_age_days,
                    "lastDoneAt": _to_date_input(_parse_date_value(latest_done.get("completed_at") if latest_done else None) or _parse_date_value(latest_done.get("due_date") if latest_done else None)),
                    "modelDueDate": _to_date_input(model_due),
                    "assignedDueDate": _to_date_input(assigned_due),
                    "effectiveDueDate": _to_date_input(effective_due),
                    "countdownDays": countdown_days,
                    "tone": tone,
                    "indicator": indicator,
                    "statusText": status_text,
                    "doneCount": len(done_tasks),
                    "pendingCount": len(open_tasks),
                    "overdueCount": overdue_open,
                    "openTaskId": int(active_task["id"]) if active_task else None,
                    "modelRationale": rationale,
                }
            )

    tone_order = {"danger": 0, "warning": 1, "info": 2, "ok": 3}
    rows.sort(
        key=lambda item: (
            tone_order.get(item.get("tone"), 3),
            item.get("countdownDays") if item.get("countdownDays") is not None else 999999,
            int(item.get("treeId") or 0),
        )
    )

    summary = {
        "total": len(rows),
        "danger": sum(1 for item in rows if item.get("tone") == "danger"),
        "warning": sum(1 for item in rows if item.get("tone") == "warning"),
        "ok": sum(1 for item in rows if item.get("tone") == "ok"),
        "info": sum(1 for item in rows if item.get("tone") == "info"),
        "dueSoon": sum(1 for item in rows if isinstance(item.get("countdownDays"), int) and 0 <= item["countdownDays"] <= 7),
    }
    return {"rows": rows, "summary": summary}


def _auto_schedule_next_cycle(db: Session, task_id: int, season_hint: str | None = None) -> int | None:
    task = db.execute(
        text("""
            SELECT t.id, t.tree_id, t.task_type, t.assignee_name, t.priority, t.status, t.review_state,
                   t.completed_at, t.due_date, t.model_season,
                   tr.project_id, tr.status AS tree_status, tr.species, tr.planting_date
            FROM tree_tasks t
            JOIN trees tr ON tr.id = t.tree_id
            WHERE t.id = :task_id
        """),
        {"task_id": task_id},
    ).mappings().first()
    if not task:
        return None

    if _normalize_name(task.get("task_type")) not in MAINTENANCE_ACTIVITY_ORDER:
        return None
    if not _is_done_status(task.get("status")):
        return None
    if _normalize_name(task.get("review_state")) != "approved":
        return None

    tree_status = _normalize_tree_status(task.get("tree_status") or "alive")
    activity = _normalize_name(task.get("task_type"))
    if activity == "replacement":
        # Replacement is condition-triggered only; do not auto-generate recurring replacement cycles.
        return None
    if _is_replacement_trigger_status(tree_status):
        return None

    season = _normalize_name(season_hint or task.get("model_season") or "rainy")
    if season not in SEASON_VALUES:
        season = "rainy"

    project_id = int(task["project_id"])
    tree_id = int(task["tree_id"])
    today = date.today()
    completed_date = _parse_date_value(task.get("completed_at")) or _parse_date_value(task.get("due_date")) or today

    replacement_done = db.execute(
        text("""
            SELECT COALESCE(completed_at::date, due_date, created_at::date) AS stamp
            FROM tree_tasks
            WHERE tree_id = :tree_id
              AND LOWER(task_type) = 'replacement'
              AND LOWER(status) IN ('done', 'completed', 'closed')
              AND LOWER(review_state) = 'approved'
            ORDER BY stamp DESC
            LIMIT 1
        """),
        {"tree_id": tree_id},
    ).scalar()
    lifecycle_start = _get_lifecycle_start_date(
        _parse_date_value(task.get("planting_date")),
        _parse_date_value(replacement_done),
    )
    tree_age_days = _day_diff(today, lifecycle_start) if lifecycle_start else 0
    species_key = _normalize_name(task.get("species"))
    maturity_map = _get_species_maturity_map(project_id, db)
    maturity_years = maturity_map.get(species_key) if species_key else None
    if tree_status in HEALTHY_TREE_STATUSES and maturity_years and tree_age_days >= maturity_years * 365:
        return None

    open_exists = db.execute(
        text("""
            SELECT id
            FROM tree_tasks
            WHERE tree_id = :tree_id
              AND LOWER(task_type) = :task_type
              AND (
                LOWER(status) NOT IN ('done', 'completed', 'closed')
                OR LOWER(review_state) IN ('submitted', 'rejected', 'reopened')
              )
            LIMIT 1
        """),
        {"tree_id": tree_id, "task_type": activity},
    ).scalar()
    if open_exists:
        return None

    intervals = _get_maintenance_intervals(activity, tree_age_days, season)
    next_due = _add_days(completed_date, intervals["repeat_days"])
    new_task_id = db.execute(
        text("""
            INSERT INTO tree_tasks (
                tree_id, task_type, assignee_name, due_date, priority, status, notes,
                auto_generated, model_season, source_task_id, review_state
            )
            VALUES (
                :tree_id, :task_type, :assignee_name, :due_date, :priority, 'pending', :notes,
                TRUE, :model_season, :source_task_id, 'none'
            )
            RETURNING id
        """),
        {
            "tree_id": tree_id,
            "task_type": activity,
            "assignee_name": task.get("assignee_name"),
            "due_date": next_due,
            "priority": task.get("priority") or "normal",
            "notes": f"Auto-generated next cycle from Task #{task_id}.",
            "model_season": season,
            "source_task_id": task_id,
        },
    ).scalar()

    db.execute(
        text("""
            INSERT INTO green_maintenance_cycles (
                project_id, tree_id, task_type, model_season, source_task_id, generated_task_id, due_date, status
            )
            VALUES (
                :project_id, :tree_id, :task_type, :model_season, :source_task_id, :generated_task_id, :due_date, 'scheduled'
            )
        """),
        {
            "project_id": project_id,
            "tree_id": tree_id,
            "task_type": activity,
            "model_season": season,
            "source_task_id": task_id,
            "generated_task_id": new_task_id,
            "due_date": next_due,
        },
    )
    _log_audit_event(
        db,
        project_id=project_id,
        entity_type="task",
        entity_id=int(new_task_id),
        action="auto_cycle_generated",
        actor="system",
        details={
            "source_task_id": task_id,
            "season": season,
            "due_date": _to_date_input(next_due),
        },
    )
    return int(new_task_id)


