@router.post("/privacy/consents")
def record_privacy_consent(
    payload: PrivacyConsentPayload,
    request: Request,
    db: Session = Depends(get_db),
):
    scope_key = _normalize_privacy_scope(payload.scope_key)
    consent_version = str(payload.consent_version or PRIVACY_CONSENT_VERSION).strip() or PRIVACY_CONSENT_VERSION
    source_app = _normalize_privacy_source_app(payload.source_app)
    actor_type = _normalize_privacy_actor_type(payload.actor_type)
    metadata_value = payload.metadata if isinstance(payload.metadata, dict) else {}
    row = db.execute(
        text(
            """
            INSERT INTO green_privacy_consents (
                scope_key,
                consent_version,
                source_app,
                source_path,
                actor_type,
                actor_id,
                actor_name,
                organization_id,
                organization_name,
                accepted,
                legal_basis,
                consent_text,
                metadata,
                ip_address,
                user_agent
            )
            VALUES (
                :scope_key,
                :consent_version,
                :source_app,
                :source_path,
                :actor_type,
                :actor_id,
                :actor_name,
                :organization_id,
                :organization_name,
                :accepted,
                :legal_basis,
                :consent_text,
                CAST(:metadata AS JSONB),
                :ip_address,
                :user_agent
            )
            RETURNING id, scope_key, consent_version, source_app, actor_type, accepted, created_at
            """
        ),
        {
            "scope_key": scope_key,
            "consent_version": consent_version,
            "source_app": source_app,
            "source_path": str(payload.source_path or "").strip() or None,
            "actor_type": actor_type,
            "actor_id": int(payload.actor_id) if payload.actor_id is not None else None,
            "actor_name": str(payload.actor_name or "").strip() or None,
            "organization_id": int(payload.organization_id) if payload.organization_id is not None else None,
            "organization_name": str(payload.organization_name or "").strip() or None,
            "accepted": bool(payload.accepted),
            "legal_basis": str(payload.legal_basis or "").strip() or None,
            "consent_text": str(payload.consent_text or "").strip() or None,
            "metadata": json.dumps(metadata_value),
            "ip_address": _request_ip_address(request),
            "user_agent": str(request.headers.get("user-agent") or "").strip() or None,
        },
    ).mappings().first()
    db.commit()
    return {
        "ok": True,
        "record": dict(row or {}),
    }


def _http_get_binary(url: str, timeout: int = 15) -> bytes | None:
    try:
        import requests

        resp = requests.get(url, timeout=timeout)
        if resp.status_code == 200 and resp.content:
            return resp.content
    except Exception:
        pass

    try:
        import urllib.request

        req = urllib.request.Request(url, headers={"User-Agent": "LandCheck/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = resp.read()
            if data:
                return data
    except Exception:
        return None
    return None


def _guess_image_media_type(payload: bytes, source_url: str | None = None, fallback: str = "image/png") -> str:
    if payload:
        try:
            with Image.open(io.BytesIO(payload)) as image:
                fmt = str(image.format or "").strip().lower()
                if fmt == "jpg":
                    fmt = "jpeg"
                if fmt in {"jpeg", "png", "webp", "gif", "bmp", "tiff"}:
                    return f"image/{fmt}"
        except Exception:
            pass
    guessed = mimetypes.guess_type(str(source_url or "").strip())[0] or ""
    if guessed.startswith("image/"):
        return guessed
    return fallback


def _coerce_optional_float(value: object) -> float | None:
    if value is None:
        return None
    try:
        if isinstance(value, bool):
            return None
        return float(value)
    except Exception:
        return None


def _extract_report_geometry_points(geometry: dict | str | None) -> list[tuple[float, float]]:
    normalized = _normalize_work_area_geojson(geometry)
    if not normalized:
        return []
    geom_type = str(normalized.get("type") or "").strip()
    coords = normalized.get("coordinates") or []
    points: list[tuple[float, float]] = []

    def _append_point(point: object):
        if not isinstance(point, list) or len(point) < 2:
            return
        try:
            points.append((float(point[0]), float(point[1])))
        except Exception:
            return

    def _append_ring(ring: object):
        if not isinstance(ring, list):
            return
        for point in ring:
            _append_point(point)

    if geom_type == "Point":
        _append_point(coords)
    elif geom_type == "LineString":
        _append_ring(coords)
    elif geom_type == "MultiLineString":
        for line in coords if isinstance(coords, list) else []:
            _append_ring(line)
    elif geom_type == "Polygon":
        for ring in coords if isinstance(coords, list) else []:
            _append_ring(ring)
    elif geom_type == "MultiPolygon":
        for polygon in coords if isinstance(coords, list) else []:
            if not isinstance(polygon, list):
                continue
            for ring in polygon:
                _append_ring(ring)
    return points


def _estimate_report_map_view(
    map_rows: list[dict],
    lng: float | None = None,
    lat: float | None = None,
    zoom: float | None = None,
    bearing: float | None = 0.0,
    pitch: float | None = 0.0,
    *,
    width: int = 800,
    height: int = 500,
) -> dict | None:
    if not map_rows:
        return None

    lng_value = _coerce_optional_float(lng)
    lat_value = _coerce_optional_float(lat)
    zoom_value = _coerce_optional_float(zoom)
    bearing_value = _coerce_optional_float(bearing)
    pitch_value = _coerce_optional_float(pitch)

    lats: list[float] = []
    lngs: list[float] = []
    for row in map_rows:
        try:
            if row.get("lat") is not None and row.get("lng") is not None:
                lats.append(float(row.get("lat")))
                lngs.append(float(row.get("lng")))
        except Exception:
            pass
        for point_lng, point_lat in _extract_report_geometry_points(row.get("existing_area_geojson")):
            lngs.append(point_lng)
            lats.append(point_lat)
    if not lats or not lngs:
        return None

    center_lat = lat_value if lat_value is not None else sum(lats) / len(lats)
    center_lng = lng_value if lng_value is not None else sum(lngs) / len(lngs)
    z = zoom_value if zoom_value is not None else 13
    b = bearing_value if bearing_value is not None else 0
    p = pitch_value if pitch_value is not None else 0
    has_explicit_view = lng_value is not None and lat_value is not None and zoom_value is not None

    def _estimate_zoom_to_fit() -> int:
        import math

        min_lng = min(lngs)
        max_lng = max(lngs)
        min_lat = min(lats)
        max_lat = max(lats)
        lng_span = max(max_lng - min_lng, 0.0008)
        lat_span = max(max_lat - min_lat, 0.0008)
        usable_width = width * 0.74
        usable_height = height * 0.74
        zoom_x = math.log2((360.0 * usable_width) / (512.0 * lng_span))
        zoom_y = math.log2((170.1022 * usable_height) / (512.0 * lat_span))
        zoom_fit = math.floor(min(zoom_x, zoom_y))
        return max(2, min(17, int(zoom_fit)))

    if not has_explicit_view:
        z = _estimate_zoom_to_fit()

    return {
        "lng": center_lng,
        "lat": center_lat,
        "zoom": z,
        "bearing": b,
        "pitch": p,
        "has_explicit_view": has_explicit_view,
        "width": width,
        "height": height,
    }


def _build_report_map_png(
    map_rows: list[dict],
    lng: float | None = None,
    lat: float | None = None,
    zoom: float | None = None,
    bearing: float | None = 0.0,
    pitch: float | None = 0.0,
    *,
    include_markers: bool = True,
) -> bytes | None:
    if not map_rows:
        return None
    map_view = _estimate_report_map_view(
        map_rows,
        lng=lng,
        lat=lat,
        zoom=zoom,
        bearing=bearing,
        pitch=pitch,
        width=800,
        height=500,
    )
    if not map_view:
        return None
    center_lng = float(map_view.get("lng") or 0.0)
    center_lat = float(map_view.get("lat") or 0.0)
    z = float(map_view.get("zoom") or 13)
    b = float(map_view.get("bearing") or 0.0)
    p = float(map_view.get("pitch") or 0.0)
    has_explicit_view = bool(map_view.get("has_explicit_view"))

    token = _load_env_token()
    if token:
        markers = []
        for r in map_rows[:60]:
            if not include_markers or r.get("lng") is None or r.get("lat") is None:
                continue
            color = _tree_status_color_hex(r.get("status"))
            markers.append(f"pin-s+{color}({r['lng']},{r['lat']})")
        overlay = ",".join(markers) if markers else ""
        overlay_part = f"{quote(overlay, safe='(),:+')}/" if overlay else ""
        for style in ("mapbox/satellite-streets-v12", "mapbox/satellite-v9"):
            if overlay and not has_explicit_view:
                url = (
                    f"https://api.mapbox.com/styles/v1/{style}/static/"
                    f"{overlay_part}auto/800x500@2x?padding=64,64,64,64&access_token={token}"
                )
                map_png = _http_get_binary(url)
                if map_png:
                    return map_png
            if overlay:
                url = (
                    f"https://api.mapbox.com/styles/v1/{style}/static/"
                    f"{overlay_part}{center_lng},{center_lat},{z},{b},{p}/800x500@2x?access_token={token}"
                )
                map_png = _http_get_binary(url)
                if map_png:
                    return map_png
            url = (
                f"https://api.mapbox.com/styles/v1/{style}/static/"
                f"{center_lng},{center_lat},{z},{b},{p}/800x500@2x?access_token={token}"
            )
            map_png = _http_get_binary(url)
            if map_png:
                return map_png

    marker_qs = ""
    if include_markers:
        markers = "|".join([f"{r['lat']},{r['lng']},lightgreen1" for r in map_rows[:50] if r.get("lat") is not None and r.get("lng") is not None])
        marker_qs = f"&markers={quote(markers, safe='|,')}" if markers else ""
    osm_url = (
        "https://staticmap.openstreetmap.de/staticmap.php?"
        f"center={center_lat},{center_lng}&zoom={int(round(z))}&size=800x500{marker_qs}"
    )
    return _http_get_binary(osm_url)


def _build_r2_settings() -> dict:
    default_endpoint = "https://751ea1abdb3fb6ff7f276b3753e4c6a1.r2.cloudflarestorage.com"
    default_bucket = "photosgreen"
    default_public_base = f"{default_endpoint}/{default_bucket}"

    endpoint_raw = (os.getenv("R2_ENDPOINT_URL") or default_endpoint).strip()
    public_base = (os.getenv("R2_PUBLIC_BASE_URL") or default_public_base).strip()
    bucket = (os.getenv("R2_BUCKET") or default_bucket).strip()
    access_key = (os.getenv("R2_ACCESS_KEY_ID") or "").strip()
    secret_key = (os.getenv("R2_SECRET_ACCESS_KEY") or "").strip()
    region = (os.getenv("R2_REGION") or "auto").strip()

    raw_for_parse = endpoint_raw or public_base
    if not raw_for_parse:
        raise HTTPException(
            status_code=500,
            detail="R2 is not configured. Set R2_ENDPOINT_URL (or R2_PUBLIC_BASE_URL), R2_BUCKET, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY.",
        )

    parsed = urlparse(raw_for_parse)
    if not parsed.scheme or not parsed.netloc:
        raise HTTPException(status_code=500, detail="Invalid R2 endpoint/public base URL format.")

    path_parts = [part for part in parsed.path.split("/") if part]
    if path_parts and not bucket:
        bucket = path_parts[0]

    endpoint_url = endpoint_raw.strip() if endpoint_raw else f"{parsed.scheme}://{parsed.netloc}"
    endpoint_parsed = urlparse(endpoint_url)
    endpoint_url = f"{endpoint_parsed.scheme}://{endpoint_parsed.netloc}"

    if not public_base:
        public_base = f"{endpoint_url.rstrip('/')}/{bucket}"

    if not bucket:
        raise HTTPException(status_code=500, detail="R2 bucket is not configured. Set R2_BUCKET.")
    if not access_key or not secret_key:
        raise HTTPException(
            status_code=500,
            detail="R2 credentials are not configured. Set R2_ACCESS_KEY_ID and R2_SECRET_ACCESS_KEY.",
        )

    return {
        "endpoint_url": endpoint_url,
        "public_base": public_base.rstrip("/"),
        "bucket": bucket,
        "access_key": access_key,
        "secret_key": secret_key,
        "region": region,
    }


def _make_r2_client(settings: dict):
    return boto3.client(
        "s3",
        endpoint_url=settings["endpoint_url"],
        aws_access_key_id=settings["access_key"],
        aws_secret_access_key=settings["secret_key"],
        region_name=settings["region"],
    )


def _normalize_object_key(raw_key: str, bucket: str) -> str:
    key = (raw_key or "").strip().lstrip("/")
    if not key:
        return ""

    # Handle keys that were encoded once/twice by older clients.
    for _ in range(3):
        decoded = unquote(key)
        if decoded == key:
            break
        key = decoded

    bucket_prefix = f"{bucket}/"
    if key.startswith(bucket_prefix):
        key = key[len(bucket_prefix):]
    return key


def _normalize_logo_asset_path(raw_value: str | None) -> str | None:
    raw = str(raw_value or "").strip()
    if not raw:
        return None
    if "/green/uploads/object/" in raw:
        idx = raw.find("/green/uploads/object/")
        return raw[idx:]
    if raw.startswith("green/uploads/object/") or raw.startswith("/green/uploads/object/"):
        return f"/{raw.lstrip('/')}"
    try:
        settings = _build_r2_settings()
    except Exception:
        settings = None

    if not raw.lower().startswith(("http://", "https://")):
        bucket = str((settings or {}).get("bucket") or "")
        key = _normalize_object_key(raw, bucket)
        return f"/green/uploads/object/{quote(key, safe='/')}" if key else raw

    if not settings:
        return raw

    public_base = str(settings.get("public_base") or "").rstrip("/")
    if public_base and raw.startswith(f"{public_base}/"):
        key = raw[len(public_base) + 1 :]
        normalized = _normalize_object_key(key, str(settings.get("bucket") or ""))
        return f"/green/uploads/object/{quote(normalized, safe='/')}" if normalized else raw
    return raw


def _extract_object_key_from_asset_value(raw_value: str | None) -> str | None:
    normalized = _normalize_logo_asset_path(raw_value)
    raw = str(normalized or "").strip()
    if not raw:
        return None
    marker = "/green/uploads/object/"
    if marker in raw:
        idx = raw.find(marker)
        raw = raw[idx + len(marker) :]
    elif raw.startswith("green/uploads/object/"):
        raw = raw[len("green/uploads/object/") :]
    elif raw.startswith("/green/uploads/object/"):
        raw = raw[len("/green/uploads/object/") :]
    else:
        try:
            settings = _build_r2_settings()
        except Exception:
            settings = None
        bucket = str((settings or {}).get("bucket") or "")
        raw = _normalize_object_key(raw, bucket)
    if not raw:
        return None
    try:
        settings = _build_r2_settings()
    except Exception:
        settings = None
    return _normalize_object_key(raw, str((settings or {}).get("bucket") or ""))


def _load_uploaded_photo_payload(
    resolved_key: str,
    *,
    w: int | None = None,
    h: int | None = None,
    q: int = 72,
    fm: str | None = None,
) -> tuple[bytes, str, str]:
    settings = _build_r2_settings()
    resolved_key = _normalize_object_key(resolved_key, settings["bucket"])
    if not resolved_key:
        raise HTTPException(status_code=400, detail="Invalid photo key.")
    try:
        client = _make_r2_client(settings)
        obj = client.get_object(Bucket=settings["bucket"], Key=resolved_key)
    except ClientError as exc:
        code = (exc.response.get("Error") or {}).get("Code", "")
        if code in {"NoSuchKey", "404", "NotFound"}:
            raise HTTPException(status_code=404, detail="Photo not found.")
        raise HTTPException(status_code=502, detail="Failed to read photo from storage.")
    except Exception:
        raise HTTPException(status_code=502, detail="Failed to read photo from storage.")

    content_type = obj.get("ContentType") or "application/octet-stream"
    cache_control = obj.get("CacheControl") or "public, max-age=86400"
    want_resize = bool(w or h or fm)

    if not want_resize:
        source_bytes = obj["Body"].read()
        return source_bytes, content_type, cache_control

    source_bytes = b""
    try:
        source_bytes = obj["Body"].read()
        with Image.open(io.BytesIO(source_bytes)) as image:
            image = ImageOps.exif_transpose(image)
            src_w, src_h = image.size
            target_w = int(w or 0)
            target_h = int(h or 0)

            if target_w and target_h:
                image.thumbnail((target_w, target_h), Image.Resampling.LANCZOS)
            elif target_w and src_w > 0 and src_h > 0:
                scaled_h = max(1, int(round(src_h * (target_w / src_w))))
                image = image.resize((target_w, scaled_h), Image.Resampling.LANCZOS)
            elif target_h and src_w > 0 and src_h > 0:
                scaled_w = max(1, int(round(src_w * (target_h / src_h))))
                image = image.resize((scaled_w, target_h), Image.Resampling.LANCZOS)

            output_format_raw = (fm or "").strip().lower()
            if output_format_raw == "jpg":
                output_format_raw = "jpeg"
            if output_format_raw not in {"webp", "jpeg", "png"}:
                if content_type.startswith("image/"):
                    output_format_raw = content_type.split("/", 1)[1].lower()
                if output_format_raw not in {"webp", "jpeg", "jpg", "png"}:
                    output_format_raw = "jpeg"
            if output_format_raw == "jpg":
                output_format_raw = "jpeg"

            if output_format_raw in {"jpeg", "jpg"} and image.mode not in {"RGB", "L"}:
                image = image.convert("RGB")
            elif output_format_raw == "png" and image.mode not in {"RGB", "RGBA", "L", "LA"}:
                image = image.convert("RGBA")

            out = io.BytesIO()
            save_kwargs: dict[str, object] = {}
            if output_format_raw in {"jpeg", "webp"}:
                save_kwargs["quality"] = int(q or 72)
            if output_format_raw == "jpeg":
                save_kwargs["optimize"] = True
            image.save(out, format=output_format_raw.upper(), **save_kwargs)
            out.seek(0)
            rendered_type = {
                "jpeg": "image/jpeg",
                "webp": "image/webp",
                "png": "image/png",
            }.get(output_format_raw, content_type)
            return out.getvalue(), rendered_type, cache_control
    except HTTPException:
        raise
    except Exception:
        if source_bytes:
            return source_bytes, content_type, cache_control
        raise HTTPException(status_code=502, detail="Failed to transform photo.")


def _stream_uploaded_photo_object(
    resolved_key: str,
    *,
    w: int | None = None,
    h: int | None = None,
    q: int = 72,
    fm: str | None = None,
):
    payload, media_type, cache_control = _load_uploaded_photo_payload(resolved_key, w=w, h=h, q=q, fm=fm)
    return Response(
        content=payload,
        media_type=media_type,
        headers={"Cache-Control": cache_control},
    )


def _sanitize_storage_segment(value: object, fallback: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9._-]+", "-", str(value or "").strip()).strip("-.")
    return cleaned or fallback


def _build_scoped_upload_folder(
    db: Session,
    *,
    folder: str,
    tree_id: int | None = None,
    task_id: int | None = None,
) -> str:
    folder_parts = [part for part in str(folder or "trees").split("/") if part and part not in {".", ".."}]
    safe_folder = "/".join(_sanitize_storage_segment(part, "file") for part in folder_parts) or "trees"

    if task_id is not None:
        task_scope = db.execute(
            text(
                """
                SELECT
                    tt.id AS task_id,
                    tr.id AS tree_id,
                    tr.project_id,
                    p.organization_id
                FROM tree_tasks tt
                JOIN trees tr ON tr.id = tt.tree_id
                LEFT JOIN tree_projects p ON p.id = tr.project_id
                WHERE tt.id = :task_id
                """
            ),
            {"task_id": int(task_id)},
        ).mappings().first()
        if task_scope:
            segments: list[str] = []
            if task_scope.get("organization_id") is not None:
                segments.extend(["organizations", _sanitize_storage_segment(f"org_{int(task_scope['organization_id'])}", "organization")])
            if task_scope.get("project_id") is not None:
                segments.extend(["projects", _sanitize_storage_segment(f"project_{int(task_scope['project_id'])}", "project")])
            if task_scope.get("tree_id") is not None:
                segments.extend(["trees", _sanitize_storage_segment(f"tree_{int(task_scope['tree_id'])}", "tree")])
            segments.extend(["tasks", _sanitize_storage_segment(f"task_{int(task_scope['task_id'])}", "task"), "photos"])
            return "/".join(segments)

    if tree_id is not None:
        tree_scope = db.execute(
            text(
                """
                SELECT
                    t.id AS tree_id,
                    t.project_id,
                    p.organization_id
                FROM trees t
                LEFT JOIN tree_projects p ON p.id = t.project_id
                WHERE t.id = :tree_id
                """
            ),
            {"tree_id": int(tree_id)},
        ).mappings().first()
        if tree_scope:
            segments = []
            if tree_scope.get("organization_id") is not None:
                segments.extend(["organizations", _sanitize_storage_segment(f"org_{int(tree_scope['organization_id'])}", "organization")])
            if tree_scope.get("project_id") is not None:
                segments.extend(["projects", _sanitize_storage_segment(f"project_{int(tree_scope['project_id'])}", "project")])
            segments.extend(["trees", _sanitize_storage_segment(f"tree_{int(tree_scope['tree_id'])}", "tree"), "photos"])
            return "/".join(segments)

    return safe_folder


@router.get("/uploads/object/{object_key:path}")
def get_uploaded_photo(
    object_key: str,
    w: int | None = Query(default=None, ge=64, le=4096),
    h: int | None = Query(default=None, ge=64, le=4096),
    q: int = Query(default=72, ge=35, le=95),
    fm: str | None = Query(default=None, pattern="^(?i:webp|jpeg|jpg|png)$"),
):
    return _stream_uploaded_photo_object(object_key, w=w, h=h, q=q, fm=fm)


def _append_photo_candidates(bucket: list[str], photo_url: str | None, photo_urls: object) -> None:
    merged = _normalize_photo_urls(photo_urls)
    primary = str(photo_url or "").strip()
    if primary and primary not in merged:
        merged.append(primary)
    for raw in merged:
        candidate = str(raw or "").strip()
        if candidate and candidate not in bucket:
            bucket.append(candidate)


@router.get("/trees/{tree_id}/photo")
def get_tree_best_photo(
    tree_id: int,
    w: int | None = Query(default=None, ge=64, le=4096),
    h: int | None = Query(default=None, ge=64, le=4096),
    q: int = Query(default=72, ge=35, le=95),
    fm: str | None = Query(default=None, pattern="^(?i:webp|jpeg|jpg|png)$"),
    db: Session = Depends(get_db),
):
    tree = db.execute(
        text(
            """
            SELECT id, photo_url, photo_urls
            FROM trees
            WHERE id = :tree_id
            """
        ),
        {"tree_id": tree_id},
    ).mappings().first()
    if not tree:
        raise HTTPException(status_code=404, detail="Tree not found.")

    candidates: list[str] = []
    _append_photo_candidates(candidates, tree.get("photo_url"), tree.get("photo_urls"))

    task_rows = list_tree_tasks(tree_id, db)
    for task in task_rows:
        _append_photo_candidates(candidates, task.get("photo_url"), task.get("photo_urls"))

    visit_rows = db.execute(
        text(
            """
            SELECT photo_url
            FROM tree_visits
            WHERE tree_id = :tree_id
            ORDER BY visit_date DESC, created_at DESC, id DESC
            """
        ),
        {"tree_id": tree_id},
    ).mappings().all()
    for visit in visit_rows:
        _append_photo_candidates(candidates, visit.get("photo_url"), None)

    last_not_found: HTTPException | None = None
    for candidate in candidates:
        object_key = _extract_object_key_from_asset_value(candidate)
        if not object_key:
            continue
        try:
            return _stream_uploaded_photo_object(object_key, w=w, h=h, q=q, fm=fm)
        except HTTPException as exc:
            if exc.status_code == 404:
                last_not_found = exc
                continue
            raise

    raise last_not_found or HTTPException(status_code=404, detail="Tree photo not found.")


@router.get("/trees/{tree_id}/photo-inline")
def get_tree_best_photo_inline(
    tree_id: int,
    w: int | None = Query(default=1280, ge=64, le=4096),
    h: int | None = Query(default=None, ge=64, le=4096),
    q: int = Query(default=76, ge=35, le=95),
    fm: str | None = Query(default="jpeg", pattern="^(?i:webp|jpeg|jpg|png)$"),
    db: Session = Depends(get_db),
):
    tree = db.execute(
        text(
            """
            SELECT id, photo_url, photo_urls
            FROM trees
            WHERE id = :tree_id
            """
        ),
        {"tree_id": tree_id},
    ).mappings().first()
    if not tree:
        raise HTTPException(status_code=404, detail="Tree not found.")

    candidates: list[str] = []
    _append_photo_candidates(candidates, tree.get("photo_url"), tree.get("photo_urls"))

    task_rows = list_tree_tasks(tree_id, db)
    for task in task_rows:
        _append_photo_candidates(candidates, task.get("photo_url"), task.get("photo_urls"))

    visit_rows = db.execute(
        text(
            """
            SELECT photo_url
            FROM tree_visits
            WHERE tree_id = :tree_id
            ORDER BY visit_date DESC, created_at DESC, id DESC
            """
        ),
        {"tree_id": tree_id},
    ).mappings().all()
    for visit in visit_rows:
        _append_photo_candidates(candidates, visit.get("photo_url"), None)

    last_not_found: HTTPException | None = None
    for candidate in candidates:
        object_key = _extract_object_key_from_asset_value(candidate)
