def _build_tree_carbon_summary(tree_row: dict) -> dict:
    if not bool(tree_row.get("count_in_carbon_scope", True)):
        return {"current_co2_kg": 0.0, "annual_co2_kg": 0.0, "lifetime_co2_kg": 0.0}
    age_years = 0.0
    if tree_row.get("tree_age_months") is not None:
        try:
            age_years = max(float(tree_row.get("tree_age_months") or 0) / 12.0, 0.0)
        except Exception:
            age_years = 0.0
    if age_years <= 0:
        planting_date = _parse_date_value(tree_row.get("planting_date"))
        age_years = tree_age_years(planting_date, date.today()) if planting_date else 0.0
    multiplier = max(int(tree_row.get("inventory_tree_count") or 1), 1)
    current = round(estimate_tree_co2_kg(tree_row.get("species"), age_years) * multiplier, 2)
    annual = round(estimate_annual_co2_kg(tree_row.get("species"), max(age_years, 0.5)) * multiplier, 2)
    lifetime = round(estimate_lifetime_co2_kg(tree_row.get("species"), 40) * multiplier, 2)
    return {"current_co2_kg": current, "annual_co2_kg": annual, "lifetime_co2_kg": lifetime}


@router.delete("/projects/{project_id}")
def delete_project(
    project_id: int,
    db: Session = Depends(get_db),
    confirm_name: str = Body(..., embed=True),
):
    project = db.execute(
        text(
            """
            SELECT id, name
            FROM tree_projects
            WHERE id = :project_id
            """
        ),
        {"project_id": project_id},
    ).mappings().first()
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    expected_name = str(project.get("name") or "").strip()
    provided_name = str(confirm_name or "").strip()
    if not provided_name:
        raise HTTPException(status_code=400, detail="Project name confirmation is required")
    if provided_name != expected_name:
        raise HTTPException(status_code=400, detail="Project name confirmation does not match")

    tree_count = int(
        db.execute(
            text(
                """
                SELECT COUNT(*) AS total
                FROM trees
                WHERE project_id = :project_id
                """
            ),
            {"project_id": project_id},
        ).scalar()
        or 0
    )
    task_count = int(
        db.execute(
            text(
                """
                SELECT COUNT(*) AS total
                FROM tree_tasks
                WHERE tree_id IN (
                    SELECT id
                    FROM trees
                    WHERE project_id = :project_id
                )
                """
            ),
            {"project_id": project_id},
        ).scalar()
        or 0
    )
    work_order_count = int(
        db.execute(
            text(
                """
                SELECT COUNT(*) AS total
                FROM green_work_orders
                WHERE project_id = :project_id
                """
            ),
            {"project_id": project_id},
        ).scalar()
        or 0
    )

    try:
        deleted = db.execute(
            text(
                """
                DELETE FROM tree_projects
                WHERE id = :project_id
                RETURNING id
                """
            ),
            {"project_id": project_id},
        ).scalar()
        if not deleted:
            db.rollback()
            raise HTTPException(status_code=404, detail="Project not found")
        db.commit()
    except HTTPException:
        raise
    except Exception:
        db.rollback()
        raise HTTPException(status_code=409, detail="Project could not be deleted. Please retry.")

    return {
        "status": "ok",
        "deleted_project_id": project_id,
        "deleted_project_name": expected_name,
        "deleted_summary": {
            "trees": tree_count,
            "tasks": task_count,
            "work_orders": work_order_count,
        },
    }


@router.patch("/projects/{project_id}/settings")
def update_project_settings(
    project_id: int,
    db: Session = Depends(get_db),
    workflow_profile: str | None = Body(default=None),
    access_model: str | None = Body(default=None),
    public_sponsor_enabled: bool | None = Body(default=None),
    public_sponsor_title: str | None = Body(default=None),
    public_sponsor_description: str | None = Body(default=None),
    sponsor_price_per_tree: float | None = Body(default=None),
    sponsor_currency: str | None = Body(default=None),
    sponsor_capacity: int | None = Body(default=None),
    sponsor_max_per_order: int | None = Body(default=None),
    sponsor_dedication_enabled: bool | None = Body(default=None),
    sponsor_payment_instructions: str | None = Body(default=None),
    public_sponsor_agent_user_ids: list[int] | None = Body(default=None),
    sponsor_agent_planting_fee: float | None = Body(default=None),
    sponsor_agent_maintenance_fee: float | None = Body(default=None),
    agric_config: dict | None = Body(default=None),
    relief_config: dict | None = Body(default=None),
    planting_model: str | None = Body(default=None),
    allow_existing_tree_link: bool | None = Body(default=None),
    default_existing_tree_scope: str | None = Body(default=None),
    status: str | None = Body(default=None),
):
    existing = db.execute(
        text(
            """
            SELECT id, status, name, workflow_profile, access_model, public_sponsor_enabled, public_sponsor_title, public_sponsor_description,
                   sponsor_price_per_tree, sponsor_currency, sponsor_capacity, sponsor_max_per_order,
                   sponsor_dedication_enabled, sponsor_payment_instructions, public_sponsor_agent_user_ids,
                   sponsor_agent_planting_fee, sponsor_agent_maintenance_fee, organization_id,
                   agric_config, relief_config, planting_model, allow_existing_tree_link, default_existing_tree_scope
            FROM tree_projects
            WHERE id = :project_id
            """
        ),
        {"project_id": project_id},
    ).mappings().first()
    if not existing:
        raise HTTPException(status_code=404, detail="Project not found")

    next_status = (
        status.strip().lower()
        if status is not None
        else (existing.get("status") or "ongoing")
    )
    if next_status not in ("ongoing", "paused", "closed"):
        next_status = "ongoing"

    next_workflow_profile = (
        _normalize_workflow_profile(workflow_profile)
        if workflow_profile is not None
        else _normalize_workflow_profile(existing.get("workflow_profile"))
    )
    next_access_model = (
        _normalize_project_access_model(access_model)
        if access_model is not None
        else _normalize_project_access_model(existing.get("access_model"))
    )
    next_public_sponsor_enabled = (
        bool(public_sponsor_enabled)
        if public_sponsor_enabled is not None
        else bool(existing.get("public_sponsor_enabled"))
    )
    next_public_title = (
        _clean_text(public_sponsor_title, 160)
        if public_sponsor_title is not None
        else _clean_text(existing.get("public_sponsor_title"), 160)
    )
    next_public_description = (
        _clean_text(public_sponsor_description, 1200)
        if public_sponsor_description is not None
        else _clean_text(existing.get("public_sponsor_description"), 1200)
    )
    next_sponsor_price = (
        round(float(sponsor_price_per_tree), 2)
        if sponsor_price_per_tree is not None
        else (round(float(existing.get("sponsor_price_per_tree")), 2) if existing.get("sponsor_price_per_tree") is not None else None)
    )
    next_sponsor_currency = (
        _normalize_currency_code(sponsor_currency, "NGN")
        if sponsor_currency is not None
        else _normalize_currency_code(existing.get("sponsor_currency"), "NGN")
    )
    next_sponsor_capacity = (
        int(sponsor_capacity)
        if sponsor_capacity is not None
        else (int(existing.get("sponsor_capacity")) if existing.get("sponsor_capacity") is not None else None)
    )
    next_sponsor_max_per_order = (
        max(1, int(sponsor_max_per_order or 1))
        if sponsor_max_per_order is not None
        else max(1, int(existing.get("sponsor_max_per_order") or 100))
    )
    next_sponsor_dedication_enabled = (
        bool(sponsor_dedication_enabled)
        if sponsor_dedication_enabled is not None
        else bool(existing.get("sponsor_dedication_enabled", True))
    )
    next_sponsor_payment_instructions = (
        _clean_text(sponsor_payment_instructions, 1200)
        if sponsor_payment_instructions is not None
        else _clean_text(existing.get("sponsor_payment_instructions"), 1200)
    )
    next_sponsor_agent_planting_fee = (
        round(float(sponsor_agent_planting_fee), 2)
        if sponsor_agent_planting_fee is not None
        else (
            round(float(existing.get("sponsor_agent_planting_fee")), 2)
            if existing.get("sponsor_agent_planting_fee") is not None
            else _derive_default_sponsor_agent_fee(next_sponsor_price, ratio=SPONSOR_AGENT_DEFAULT_PLANTING_RATIO)
        )
    )
    next_sponsor_agent_maintenance_fee = (
        round(float(sponsor_agent_maintenance_fee), 2)
        if sponsor_agent_maintenance_fee is not None
        else (
            round(float(existing.get("sponsor_agent_maintenance_fee")), 2)
            if existing.get("sponsor_agent_maintenance_fee") is not None
            else _derive_default_sponsor_agent_fee(next_sponsor_price, ratio=SPONSOR_AGENT_DEFAULT_MAINTENANCE_RATIO)
        )
    )
    next_public_sponsor_agent_user_ids = (
        _validate_public_sponsor_agent_user_ids(
            db,
            organization_id=int(existing.get("organization_id")) if existing.get("organization_id") is not None else None,
            user_ids=public_sponsor_agent_user_ids,
        )
        if public_sponsor_agent_user_ids is not None and _is_public_sponsorship_enabled(next_access_model, next_public_sponsor_enabled)
        else (
            _normalize_positive_int_list(existing.get("public_sponsor_agent_user_ids"))
            if _is_public_sponsorship_enabled(next_access_model, next_public_sponsor_enabled)
            else []
        )
    )
    next_agric_config = (
        _normalize_agric_config(agric_config)
        if agric_config is not None
        else _normalize_agric_config(existing.get("agric_config"))
    )
    next_relief_config = (
        _normalize_relief_config(relief_config)
        if relief_config is not None
        else _normalize_relief_config(existing.get("relief_config"))
    )
    next_model = _normalize_planting_model(planting_model) if planting_model is not None else _normalize_planting_model(existing.get("planting_model"))
    next_allow_existing = (
        bool(allow_existing_tree_link)
        if allow_existing_tree_link is not None
        else bool(existing.get("allow_existing_tree_link"))
    )
    next_scope = (
        _normalize_existing_tree_scope(default_existing_tree_scope)
        if default_existing_tree_scope is not None
        else _normalize_existing_tree_scope(existing.get("default_existing_tree_scope"))
    )

    row = db.execute(
        text(
            """
            UPDATE tree_projects
            SET status = :status,
                workflow_profile = :workflow_profile,
                access_model = :access_model,
                public_sponsor_enabled = :public_sponsor_enabled,
                public_sponsor_title = :public_sponsor_title,
                public_sponsor_description = :public_sponsor_description,
                sponsor_price_per_tree = :sponsor_price_per_tree,
                sponsor_currency = :sponsor_currency,
                sponsor_capacity = :sponsor_capacity,
                sponsor_max_per_order = :sponsor_max_per_order,
                sponsor_dedication_enabled = :sponsor_dedication_enabled,
                sponsor_payment_instructions = :sponsor_payment_instructions,
                public_sponsor_agent_user_ids = CAST(:public_sponsor_agent_user_ids AS JSONB),
                sponsor_agent_planting_fee = :sponsor_agent_planting_fee,
                sponsor_agent_maintenance_fee = :sponsor_agent_maintenance_fee,
                agric_config = CAST(:agric_config AS JSONB),
                relief_config = CAST(:relief_config AS JSONB),
                planting_model = :planting_model,
                allow_existing_tree_link = :allow_existing_tree_link,
                default_existing_tree_scope = :default_existing_tree_scope
            WHERE id = :project_id
            RETURNING id, status, name, location_text, sponsor, workflow_profile, access_model,
                      public_sponsor_enabled, public_sponsor_title, public_sponsor_description,
                      sponsor_price_per_tree, sponsor_currency, sponsor_capacity, sponsor_max_per_order,
                      sponsor_dedication_enabled, sponsor_payment_instructions, public_sponsor_agent_user_ids,
                      sponsor_agent_planting_fee, sponsor_agent_maintenance_fee,
                      agric_config, relief_config,
                      planting_model, allow_existing_tree_link, default_existing_tree_scope, created_at
            """
        ),
        {
            "project_id": project_id,
            "status": next_status,
            "workflow_profile": next_workflow_profile,
            "access_model": next_access_model,
            "public_sponsor_enabled": next_public_sponsor_enabled,
            "public_sponsor_title": next_public_title,
            "public_sponsor_description": next_public_description,
            "sponsor_price_per_tree": next_sponsor_price,
            "sponsor_currency": next_sponsor_currency,
            "sponsor_capacity": next_sponsor_capacity,
            "sponsor_max_per_order": next_sponsor_max_per_order,
            "sponsor_dedication_enabled": next_sponsor_dedication_enabled,
            "sponsor_payment_instructions": next_sponsor_payment_instructions,
            "public_sponsor_agent_user_ids": _safe_json(next_public_sponsor_agent_user_ids),
            "sponsor_agent_planting_fee": next_sponsor_agent_planting_fee,
            "sponsor_agent_maintenance_fee": next_sponsor_agent_maintenance_fee,
            "agric_config": _safe_json(next_agric_config),
            "relief_config": _safe_json(next_relief_config),
            "planting_model": next_model,
            "allow_existing_tree_link": next_allow_existing,
            "default_existing_tree_scope": next_scope,
        },
    ).mappings().first()
    payload = dict(row)
    payload["workflow_profile"] = _normalize_workflow_profile(payload.get("workflow_profile"))
    payload["agric_config"] = _normalize_agric_config(payload.get("agric_config"))
    payload["relief_config"] = _normalize_relief_config(payload.get("relief_config"))
    payload = _apply_project_access_fields(payload)
    
    _log_activity(
        db,
        "backend_api",
        "project_settings_updated",
        f"Project settings for '{existing.get('name')}' updated to status '{next_status}'",
        "admin",
        {"project_id": project_id, "status": next_status}
    )

    _log_audit_event(
        db,
        project_id=project_id,
        entity_type="project",
        entity_id=project_id,
        action="project_settings_updated",
        details={
            "before": dict(existing),
            "after": {
                "workflow_profile": next_workflow_profile,
                "access_model": next_access_model,
                "public_sponsor_enabled": next_public_sponsor_enabled,
                "sponsor_price_per_tree": next_sponsor_price,
                "public_sponsor_agent_user_ids": next_public_sponsor_agent_user_ids,
                "sponsor_agent_planting_fee": next_sponsor_agent_planting_fee,
                "sponsor_agent_maintenance_fee": next_sponsor_agent_maintenance_fee,
                "agric_config": next_agric_config,
                "relief_config": next_relief_config,
                "planting_model": next_model,
                "allow_existing_tree_link": next_allow_existing,
                "default_existing_tree_scope": next_scope,
            },
        },
    )
    db.commit()
    existing_agent_ids = _normalize_positive_int_list(existing.get("public_sponsor_agent_user_ids"))
    new_agent_ids = next_public_sponsor_agent_user_ids or []
    newly_added_ids = [uid for uid in new_agent_ids if uid not in existing_agent_ids]
    if newly_added_ids:
        _notify_agent_added_to_project(db, project_id, newly_added_ids)
    return payload


@router.patch("/projects/{project_id}/organization")
def assign_project_organization(
    project_id: int,
    db: Session = Depends(get_db),
    organization_id: int | None = Body(default=None),
):
    project_row = db.execute(
        text("SELECT id, name, organization_id FROM tree_projects WHERE id = :project_id"),
        {"project_id": project_id},
    ).mappings().first()
    if not project_row:
        raise HTTPException(status_code=404, detail="Project not found")
    org_id_value = int(organization_id) if organization_id is not None else None
    org_row = None
    if org_id_value is not None:
        org_row = db.execute(
            text("SELECT id, name, slug, status, logo_url FROM green_organizations WHERE id = :org_id"),
            {"org_id": org_id_value},
        ).mappings().first()
        if not org_row:
            raise HTTPException(status_code=404, detail="Organization not found")
    updated = db.execute(
        text(
            """
            UPDATE tree_projects
            SET organization_id = :organization_id
            WHERE id = :project_id
            RETURNING id, organization_id, name
            """
        ),
        {"organization_id": org_id_value, "project_id": project_id},
    ).mappings().first()
    _log_audit_event(
        db,
        project_id=project_id,
        entity_type="project",
        entity_id=project_id,
        action="project_organization_assigned",
        actor="super_admin",
        details={
            "before_organization_id": project_row.get("organization_id"),
            "after_organization_id": org_id_value,
            "after_organization_name": (org_row or {}).get("name") if org_row else None,
        },
    )
    db.commit()
    payload = dict(updated)
    if org_row:
        payload["organization_name"] = org_row.get("name")
        payload["organization_slug"] = org_row.get("slug")
        payload["organization_status"] = org_row.get("status")
        payload["organization_logo_url"] = org_row.get("logo_url")
    else:
        payload["organization_name"] = None
        payload["organization_slug"] = None
        payload["organization_status"] = None
        payload["organization_logo_url"] = None
    return payload


@router.get("/public-projects")
def list_public_sponsorship_projects(db: Session = Depends(get_db)):
    rows = db.execute(
        text(
            """
            SELECT
                p.id, p.organization_id, p.name, p.location_text, p.sponsor,
                p.access_model, p.public_sponsor_enabled, p.public_sponsor_title, p.public_sponsor_description,
                p.sponsor_price_per_tree, p.sponsor_currency, p.sponsor_capacity, p.sponsor_max_per_order,
                p.sponsor_dedication_enabled, p.sponsor_payment_instructions,
                p.workflow_profile, p.status, p.created_at,
                o.name AS organization_name, o.slug AS organization_slug, o.status AS organization_status,
                COALESCE(o.is_active, TRUE) AS organization_is_active,
                o.logo_url AS organization_logo_url
            FROM tree_projects p
            LEFT JOIN green_organizations o ON o.id = p.organization_id
            WHERE (
                    LOWER(COALESCE(p.access_model, 'partner_org')) = 'public_sponsorship'
                 OR COALESCE(p.public_sponsor_enabled, FALSE) = TRUE
                  )
              AND (o.id IS NULL OR COALESCE(o.is_active, TRUE) = TRUE)
            ORDER BY
                CASE WHEN COALESCE(p.sponsor_price_per_tree, 0) > 0 THEN 0 ELSE 1 END,
                p.created_at DESC
            """
        )
    ).mappings().all()
    items: list[dict] = []
    for row in rows:
        item = dict(row)
        item["organization_logo_url"] = _normalize_logo_asset_path(item.get("organization_logo_url"))
        items.append(_build_public_project_snapshot(item, db))
    return items


@router.get("/public/partner-organizations")
def list_public_partner_organizations(db: Session = Depends(get_db)):
    rows = db.execute(
        text(
            """
            SELECT id, name, logo_url
            FROM green_organizations
            WHERE COALESCE(is_active, TRUE) = TRUE
              AND logo_url IS NOT NULL
              AND logo_url != ''
            ORDER BY name
            """
        )
    ).mappings().all()
    return [
        {
            "id": row["id"],
            "name": row["name"],
            "logo_url": _normalize_logo_asset_path(row["logo_url"]),
        }
        for row in rows
    ]


@router.get("/public-projects/{project_id}")
def get_public_sponsorship_project(project_id: int, db: Session = Depends(get_db)):
    project = get_project(project_id=project_id, db=db, assignee_name=None)
    if not _is_public_sponsorship_project(project):
        raise HTTPException(status_code=404, detail="Public sponsorship project not found")
    return _build_public_project_snapshot(project, db)


@router.post("/sponsor-auth/signup")
def sponsor_auth_signup(payload: SponsorSignupPayload, request: Request, db: Session = Depends(get_db)):
    full_name = str(payload.full_name or "").strip()
    if not full_name:
        raise HTTPException(status_code=400, detail="Full name is required")
    email = _normalize_email_address(payload.email)
    existing = db.execute(
        text("SELECT id FROM green_sponsor_accounts WHERE LOWER(email) = LOWER(:email) LIMIT 1"),
        {"email": email},
    ).scalar()
    if existing:
        raise HTTPException(status_code=409, detail="Email already registered")
    referred_by_id = None
    if payload.referral_code:
        ref_code = str(payload.referral_code).strip()
        if ref_code:
            referrer = db.execute(
                text("SELECT id FROM green_sponsor_accounts WHERE UPPER(referral_code) = UPPER(:ref_code) LIMIT 1"),
                {"ref_code": ref_code}
            ).scalar()
            if referrer:
                referred_by_id = int(referrer)
                db.execute(
                    text("""
                        UPDATE green_sponsor_accounts
                        SET green_points = green_points + 25,
                            lifetime_points = lifetime_points + 25,
                            updated_at = NOW()
                        WHERE id = :referrer_id
                    """),
                    {"referrer_id": referred_by_id}
                )

    row = db.execute(
        text(
            """
            INSERT INTO green_sponsor_accounts (
                sponsor_uid, account_type, full_name, organization_name, email, phone, password_hash, referred_by_id, is_active,
                green_points, lifetime_points
            )
            VALUES (
                :sponsor_uid, :account_type, :full_name, :organization_name, :email, :phone, :password_hash, :referred_by_id, TRUE,
                :green_points, :lifetime_points
            )
            RETURNING id, sponsor_uid, account_type, full_name, organization_name, email, phone, is_active,
                      entity_category, leaderboard_visibility, green_points, lifetime_points
            """
        ),
        {
            "sponsor_uid": _ensure_unique_sponsor_uid(db, None),
            "account_type": _normalize_sponsor_account_type(payload.account_type),
            "full_name": full_name,
            "organization_name": _clean_text(payload.organization_name, 160),
            "email": email,
            "phone": _clean_text(payload.phone, 80),
            "password_hash": _hash_password_value(payload.password),
            "referred_by_id": referred_by_id,
            "green_points": 10 if referred_by_id else 0,
            "lifetime_points": 10 if referred_by_id else 0,
        },
    ).mappings().first()
    _log_audit_event(
        db,
        project_id=None,
        entity_type="sponsor_account",
        entity_id=int(row["id"]),
        action="sponsor_account_created",
        actor=full_name,
        details={"account_type": row.get("account_type"), "email": row.get("email")},
    )
    _log_activity(
        db,
        "sponsor_app",
        "sponsor_signup",
        f"Sponsor {row.get('full_name')} ({row.get('email')}) signed up successfully",
        row.get('full_name'),
        {"sponsor_id": int(row["id"]), "account_type": row.get("account_type")}
    )
    db.commit()
    try:
        _notify_sponsor_welcome_email(db, int(row["id"]), request=request)
    except Exception:
        db.rollback()
    return _build_sponsor_auth_payload(dict(row))


@router.post("/sponsor-auth/login")
def sponsor_auth_login(payload: SponsorLoginPayload, db: Session = Depends(get_db)):
    email = _normalize_email_address(payload.email)
    row = db.execute(
        text(
            """
            SELECT id, sponsor_uid, account_type, full_name, organization_name, email, phone, password_hash, is_active,
                   entity_category, leaderboard_visibility
            FROM green_sponsor_accounts
            WHERE LOWER(email) = LOWER(:email)
            LIMIT 1
            """
        ),
        {"email": email},
    ).mappings().first()
    if not row or not _verify_password_value(payload.password, row.get("password_hash")):
        raise HTTPException(status_code=401, detail="Invalid email or password")
    if not bool(row.get("is_active", True)):
        raise HTTPException(status_code=403, detail="Sponsor account is inactive")
    _log_activity(
        db,
        "sponsor_app",
        "sponsor_login",
        f"Sponsor {row.get('full_name')} logged in successfully",
        row.get('full_name'),
        {"sponsor_id": int(row["id"])}
    )
    return _build_sponsor_auth_payload(dict(row))


@router.post("/sponsor-auth/forgot-password")
def sponsor_auth_forgot_password(payload: SponsorForgotPasswordPayload, request: Request, db: Session = Depends(get_db)):
    email = _normalize_email_address(payload.email)
    row = db.execute(
        text(
            """
            SELECT id, full_name, email
            FROM green_sponsor_accounts
            WHERE LOWER(email) = LOWER(:email)
              AND COALESCE(is_active, TRUE) = TRUE
            LIMIT 1
            """
        ),
        {"email": email},
    ).mappings().first()
    if not row:
        return {"ok": True, "message": "If that sponsor email exists, a reset link has been sent."}

    token = secrets.token_urlsafe(32)
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    expires_at = datetime.utcnow() + timedelta(hours=SPONSOR_RESET_TOKEN_TTL_HOURS)
    db.execute(
        text(
            """
            UPDATE green_sponsor_accounts
            SET password_reset_token_hash = :token_hash,
                password_reset_token_expires_at = :expires_at,
                password_reset_requested_at = NOW(),
                updated_at = NOW()
            WHERE id = :sponsor_id
            """
        ),
        {
            "sponsor_id": int(row["id"]),
            "token_hash": token_hash,
            "expires_at": expires_at,
        },
    )
    _log_audit_event(
        db,
        project_id=None,
        entity_type="sponsor_account",
        entity_id=int(row["id"]),
        action="sponsor_password_reset_requested",
        actor=str(row.get("email") or "").strip(),
        details={"expires_at": expires_at.isoformat()},
    )
    db.commit()
    reset_url = _build_sponsor_public_reset_password_url(token, request=request)
    if reset_url:
        try:
            _send_sponsor_password_reset_email(
                to_email=str(row.get("email") or "").strip(),
                full_name=str(row.get("full_name") or ""),
                reset_url=reset_url,
                expires_at=expires_at,
            )
        except Exception:
            pass
    return {"ok": True, "message": "If that sponsor email exists, a reset link has been sent."}


@router.post("/sponsor-auth/reset-password")
def sponsor_auth_reset_password(payload: SponsorResetPasswordPayload, db: Session = Depends(get_db)):
    token = str(payload.token or "").strip()
    if len(token) < 20:
        raise HTTPException(status_code=400, detail="Invalid reset token")
    new_password = str(payload.new_password or "")
    if len(new_password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    row = db.execute(
        text(
            """
            SELECT id, email
            FROM green_sponsor_accounts
            WHERE password_reset_token_hash = :token_hash
              AND password_reset_token_expires_at IS NOT NULL
              AND password_reset_token_expires_at >= NOW()
            LIMIT 1
            """
        ),
        {"token_hash": token_hash},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=400, detail="This reset link is invalid or has expired")
    db.execute(
        text(
            """
            UPDATE green_sponsor_accounts
            SET password_hash = :password_hash,
                password_reset_token_hash = NULL,
                password_reset_token_expires_at = NULL,
                updated_at = NOW()
            WHERE id = :sponsor_id
            """
        ),
        {
            "sponsor_id": int(row["id"]),
            "password_hash": _hash_password_value(new_password),
        },
    )
    _log_audit_event(
        db,
        project_id=None,
        entity_type="sponsor_account",
        entity_id=int(row["id"]),
        action="sponsor_password_reset_completed",
        actor=str(row.get("email") or "").strip(),
        details={},
    )
    db.commit()
    return {"ok": True, "message": "Password updated successfully. You can sign in now."}


@router.post("/sponsor/orders")
def create_sponsor_order(
    payload: SponsorOrderPayload,
    request: Request,
    db: Session = Depends(get_db),
):
    sponsor_id = int(payload.sponsor_id or 0)
    if sponsor_id <= 0:
        raise HTTPException(status_code=400, detail="Sponsor account is required")
    sponsor_row = db.execute(
        text("SELECT id, full_name, email, phone, is_active FROM green_sponsor_accounts WHERE id = :sponsor_id"),
        {"sponsor_id": int(sponsor_id)},
    ).mappings().first()
    if not sponsor_row or not bool(sponsor_row.get("is_active", True)):
        raise HTTPException(status_code=404, detail="Sponsor account not found")
    project = get_project(project_id=int(payload.project_id), db=db, assignee_name=None)
    if not _is_public_sponsorship_project(project):
        raise HTTPException(status_code=400, detail="Project is not open for public sponsorship")
    quantity = max(1, int(payload.quantity or 1))
    max_per_order = max(1, int(project.get("sponsor_max_per_order") or 100))
    if quantity > max_per_order:
        raise HTTPException(status_code=400, detail=f"Maximum trees per order is {max_per_order}")
    if not bool(payload.accepted_terms):
        raise HTTPException(status_code=400, detail="You must accept the sponsor terms before checkout")
    if not bool(payload.accepted_policy):
        raise HTTPException(status_code=400, detail="You must accept the privacy policy before checkout")
    usage = _project_sponsorship_usage(db, int(project["id"]))
    capacity = project.get("sponsor_capacity")
    if capacity is not None and int(usage["reserved_slots"]) + quantity > int(capacity):
        raise HTTPException(status_code=409, detail="Not enough sponsorship slots remaining in this project")
    amount_per_tree = round(float(project.get("sponsor_price_per_tree") or 0), 2)
    if amount_per_tree <= 0:
        raise HTTPException(
            status_code=400,
            detail="This sponsor project is visible, but pricing is still being finalized. Please try again after the project team updates payment details.",
        )
    primary_proof_url, proof_urls = _merge_photo_evidence(payload.payment_proof_url, payload.payment_proof_urls)
    payment_reference = _clean_text(payload.payment_reference, 120)
    raw_payment_method = _normalize_name(payload.payment_method)
    manual_payment_requested = raw_payment_method in {"manual_transfer", "manual", "bank_transfer"} or bool(primary_proof_url or payment_reference)
    use_flutterwave = not manual_payment_requested
    if use_flutterwave and not _flutterwave_secret_key():
        raise HTTPException(status_code=503, detail="Flutterwave payment gateway is not configured on this server")
    if manual_payment_requested and not primary_proof_url and not payment_reference:
        raise HTTPException(status_code=400, detail="Attach payment proof or provide payment reference")
    payment_status = "pending" if use_flutterwave else "proof_submitted"
    order_status = "pending_payment" if use_flutterwave else "payment_review"
    payment_method = "flutterwave_standard" if use_flutterwave else _clean_text(payload.payment_method or "manual_transfer", 80)
    dedication_type = _normalize_sponsor_dedication_type(payload.dedication_type)
    dedication_name = _clean_text(payload.dedication_name, 160)
    dedication_message = _clean_text(payload.dedication_message, 500)
    consent_version = _clean_text(payload.consent_version, 80) or SPONSOR_TERMS_VERSION
    consent_ip = _request_ip_address(request)
    order_uid = _generate_prefixed_uid("ORD")
    amount_total = round(amount_per_tree * quantity, 2)
    payment_session: dict | None = None
    order_id = 0
    try:
        order_row = db.execute(
            text(
                """
                INSERT INTO green_sponsorship_orders (
                    order_uid, sponsor_account_id, project_id, quantity, amount_per_tree, amount_total, currency,
                    payment_method, payment_reference, payment_status, order_status,
                    payment_provider, payment_link, payment_gateway_reference, payment_gateway_status, payment_gateway_payload,
                    payment_proof_url, payment_proof_urls,
                    dedication_type, dedication_name, dedication_message, purchaser_note,
                    accepted_terms, accepted_policy, consent_version, consent_ip
                )
                VALUES (
                    :order_uid, :sponsor_account_id, :project_id, :quantity, :amount_per_tree, :amount_total, :currency,
                    :payment_method, :payment_reference, :payment_status, :order_status,
                    :payment_provider, :payment_link, :payment_gateway_reference, :payment_gateway_status, CAST(:payment_gateway_payload AS JSONB),
                    :payment_proof_url, CAST(:payment_proof_urls AS JSONB),
                    :dedication_type, :dedication_name, :dedication_message, :purchaser_note,
                    :accepted_terms, :accepted_policy, :consent_version, :consent_ip
                )
                RETURNING id, order_uid
                """
            ),
            {
                "order_uid": order_uid,
                "sponsor_account_id": int(sponsor_id),
                "project_id": int(project["id"]),
                "quantity": quantity,
                "amount_per_tree": amount_per_tree,
                "amount_total": amount_total,
                "currency": str(project.get("sponsor_currency") or "NGN"),
                "payment_method": payment_method,
                "payment_reference": payment_reference,
                "payment_status": payment_status,
                "order_status": order_status,
                "payment_provider": "flutterwave" if use_flutterwave else None,
                "payment_link": None,
                "payment_gateway_reference": order_uid if use_flutterwave else None,
                "payment_gateway_status": "created" if use_flutterwave else None,
                "payment_gateway_payload": _safe_json({}) if use_flutterwave else None,
                "payment_proof_url": primary_proof_url,
                "payment_proof_urls": _safe_json(proof_urls),
                "dedication_type": dedication_type,
                "dedication_name": dedication_name,
                "dedication_message": dedication_message,
                "purchaser_note": _clean_text(payload.purchaser_note, 500),
                "accepted_terms": True,
                "accepted_policy": True,
                "consent_version": consent_version,
                "consent_ip": consent_ip,
            },
        ).mappings().first()
        order_id = int(order_row["id"])
        for _ in range(quantity):
            db.execute(
                text(
                    """
                    INSERT INTO green_sponsorship_units (
                        unit_uid, order_id, sponsor_account_id, project_id, sponsorship_status,
                        dedication_type, dedication_name, dedication_message
                    )
                    VALUES (
                        :unit_uid, :order_id, :sponsor_account_id, :project_id, 'awaiting_payment',
                        :dedication_type, :dedication_name, :dedication_message
                    )
                    """
                ),
                {
                    "unit_uid": _generate_prefixed_uid("UNT"),
                    "order_id": order_id,
                    "sponsor_account_id": int(sponsor_id),
                    "project_id": int(project["id"]),
                    "dedication_type": dedication_type,
                    "dedication_name": dedication_name,
                    "dedication_message": dedication_message,
                },
            )
        _refresh_sponsorship_order_status(db, order_id)
        if use_flutterwave:
            payment_session = _create_flutterwave_payment_link(
                request=request,
                order_row={
                    "id": order_id,
                    "order_uid": order_uid,
                    "project_id": int(project["id"]),
                    "sponsor_account_id": int(sponsor_id),
                    "amount_total": amount_total,
                    "currency": str(project.get("sponsor_currency") or "NGN"),
                    "payment_gateway_reference": order_uid,
                },
                sponsor_row=dict(sponsor_row),
                project=project,
            )
            db.execute(
                text(
                    """
                    UPDATE green_sponsorship_orders
                    SET payment_link = :payment_link,
                        payment_gateway_reference = :payment_gateway_reference,
                        payment_gateway_status = :payment_gateway_status,
                        payment_gateway_payload = CAST(:payment_gateway_payload AS JSONB),
                        updated_at = NOW()
                    WHERE id = :order_id
                    """
                ),
                {
                    "order_id": order_id,
                    "payment_link": payment_session.get("link"),
                    "payment_gateway_reference": payment_session.get("tx_ref") or order_uid,
                    "payment_gateway_status": "created",
                    "payment_gateway_payload": _safe_json(payment_session.get("raw") or {}),
                },
            )
        _log_audit_event(
            db,
            project_id=int(project["id"]),
            entity_type="sponsorship_order",
            entity_id=order_id,
            action="sponsorship_order_created",
            actor=str(sponsor_row.get("full_name") or "").strip() or str(sponsor_row.get("email") or "").strip(),
            details={
                "quantity": quantity,
                "payment_status": payment_status,
                "amount_total": amount_total,
                "payment_method": payment_method,
                "consent_version": consent_version,
            },
        )
        db.commit()
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        raise
    try:
        _notify_sponsor_order_created_email(db, order_id, request=request)
    except Exception:
        db.rollback()
    return {
        "ok": True,
        "order_id": order_id,
        "order_uid": order_uid,
        "payment_method": payment_method,
        "payment_status": payment_status,
        "payment_link": payment_session.get("link") if payment_session else None,
    }


@router.get("/sponsor/orders/{order_uid}/payment-status")
def get_sponsor_order_payment_status(
    order_uid: str,
    sponsor_id: int = Query(...),
    refresh: bool = Query(default=False),
    db: Session = Depends(get_db),
):
    row = db.execute(
        text(
            """
            SELECT
                o.id, o.order_uid, o.project_id, o.quantity, o.amount_per_tree, o.amount_total, o.currency,
                o.payment_method, o.payment_reference, o.payment_status, o.order_status,
                o.payment_provider, o.payment_link, o.payment_gateway_reference, o.payment_gateway_transaction_id,
                o.payment_gateway_status, o.payment_verified_at,
                o.payment_proof_url, o.payment_proof_urls, o.dedication_type, o.dedication_name,
                o.dedication_message, o.purchaser_note, o.reviewed_by, o.reviewed_at, o.review_notes,
                o.created_at, o.updated_at,
                p.name AS project_name, p.location_text
            FROM green_sponsorship_orders o
            JOIN tree_projects p ON p.id = o.project_id
            WHERE o.sponsor_account_id = :sponsor_id
              AND UPPER(o.order_uid) = UPPER(:order_uid)
            LIMIT 1
            """
        ),
        {"sponsor_id": int(sponsor_id), "order_uid": str(order_uid or "").strip()},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsorship order not found")
    item = dict(row)
    sync_result: dict | None = None
    if refresh and _normalize_name(item.get("payment_method")) == "flutterwave_standard" and item.get("payment_status") != "verified":
        try:
            sync_result = _sync_sponsorship_order_flutterwave_payment(
                db,
                item,
                transaction_id=int(item.get("payment_gateway_transaction_id") or 0) or None,
                tx_ref=item.get("payment_gateway_reference"),
                actor="sponsor_app",
            )
            db.commit()
            if bool((sync_result or {}).get("should_send_payment_confirmation")):
                try:
                    _notify_sponsor_payment_confirmed_email(db, int(item.get("id") or 0))
                except Exception:
                    db.rollback()
        except HTTPException:
            db.rollback()
        row = db.execute(
            text(
                """
                SELECT
                    o.id, o.order_uid, o.project_id, o.quantity, o.amount_per_tree, o.amount_total, o.currency,
                    o.payment_method, o.payment_reference, o.payment_status, o.order_status,
                    o.payment_provider, o.payment_link, o.payment_gateway_reference, o.payment_gateway_transaction_id,
                    o.payment_gateway_status, o.payment_verified_at,
                    o.payment_proof_url, o.payment_proof_urls, o.dedication_type, o.dedication_name,
                    o.dedication_message, o.purchaser_note, o.reviewed_by, o.reviewed_at, o.review_notes,
                    o.created_at, o.updated_at,
                    p.name AS project_name, p.location_text
                FROM green_sponsorship_orders o
                JOIN tree_projects p ON p.id = o.project_id
                WHERE o.sponsor_account_id = :sponsor_id
                  AND UPPER(o.order_uid) = UPPER(:order_uid)
                LIMIT 1
                """
            ),
            {"sponsor_id": int(sponsor_id), "order_uid": str(order_uid or "").strip()},
        ).mappings().first()
        item = dict(row or {})
    counts = db.execute(
        text(
            """
            SELECT
                COUNT(*) AS total_units,
                COUNT(*) FILTER (WHERE tree_id IS NOT NULL) AS linked_units,
                COUNT(*) FILTER (WHERE LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_tree') AS awaiting_tree_units,
                COUNT(*) FILTER (WHERE LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_payment') AS awaiting_payment_units
            FROM green_sponsorship_units
            WHERE order_id = :order_id
            """
        ),
        {"order_id": int(item.get("id") or 0)},
    ).mappings().first() or {}
    item["payment_status"] = _normalize_sponsor_payment_status(item.get("payment_status"))
    item["order_status"] = _normalize_sponsor_order_status(item.get("order_status"))
    item["payment_proof_urls"] = _normalize_photo_urls(item.get("payment_proof_urls"))
    item["total_units"] = int(counts.get("total_units") or 0)
    item["linked_units"] = int(counts.get("linked_units") or 0)
    item["awaiting_tree_units"] = int(counts.get("awaiting_tree_units") or 0)
    item["awaiting_payment_units"] = int(counts.get("awaiting_payment_units") or 0)
    return item


@router.get("/sponsor/payments/flutterwave/return")
def sponsor_flutterwave_return(
    order_uid: str,
    status: str | None = Query(default=None),
    tx_ref: str | None = Query(default=None),
    transaction_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
):
    order = db.execute(
        text(
            """
            SELECT
                id, order_uid, sponsor_account_id, project_id, amount_total, currency,
                payment_method, payment_status, payment_gateway_reference, payment_gateway_transaction_id
            FROM green_sponsorship_orders
            WHERE UPPER(order_uid) = UPPER(:order_uid)
            LIMIT 1
            """
        ),
        {"order_uid": str(order_uid or "").strip()},
    ).mappings().first()
    if not order:
        deep_link = _build_sponsor_payment_app_url(str(order_uid or "").strip(), "failed", "We could not find that sponsorship order.")
        return Response(
            content=_render_sponsor_payment_return_page("Order not found", "We could not find that sponsorship order. Return to the app and try again.", deep_link),
            media_type="text/html",
        )
    payment_state = "pending"
    message = "We are checking your payment. Return to the app to see the latest status."
    status_key = _normalize_name(status)
    if status_key in {"failed", "cancelled", "canceled"}:
        payment_state = "failed"
        message = "Payment was not completed. You can try again from the app."
    if status_key in {"successful", "completed", "pending"} or tx_ref or transaction_id:
        try:
            result = _sync_sponsorship_order_flutterwave_payment(
                db,
                dict(order),
                transaction_id=int(transaction_id or 0) or None,
                tx_ref=tx_ref or order.get("payment_gateway_reference"),
                actor="flutterwave_redirect",
                review_notes="Verified after Flutterwave redirect",
            )
            db.commit()
            if bool(result.get("should_send_payment_confirmation")):
                try:
                    _notify_sponsor_payment_confirmed_email(db, int(order.get("id") or 0))
                except Exception:
                    db.rollback()
            payment_state = "verified" if result.get("verified") else ("failed" if result.get("gateway_status") in {"failed", "cancelled", "canceled"} else "pending")
            message = str(result.get("message") or message)
        except HTTPException:
            db.rollback()
            payment_state = "pending"
            message = "We could not confirm the payment automatically yet. Return to the app and refresh the order status."
    deep_link = _build_sponsor_payment_app_url(str(order.get("order_uid") or order_uid), payment_state, message)
    title = "Payment pending"
    if payment_state == "verified":
        title = "Payment received"
    elif payment_state == "failed":
        title = "Payment incomplete"
    return Response(content=_render_sponsor_payment_return_page(title, message, deep_link), media_type="text/html")


@router.post("/sponsor/payments/flutterwave/webhook")
async def sponsor_flutterwave_webhook(request: Request, db: Session = Depends(get_db)):
    raw_body = await request.body()
    signature = request.headers.get("flutterwave-signature")
    secret_hash_configured = bool(_flutterwave_secret_hash())
    if secret_hash_configured and not _verify_flutterwave_webhook_signature(raw_body, signature):
        raise HTTPException(status_code=401, detail="Invalid webhook signature")
    # If FLW_SECRET_HASH is not configured, accept all webhooks from Flutterwave
    # (they are still validated against the actual Flutterwave API when processing)
    try:
        payload = json.loads(raw_body.decode("utf-8") or "{}")
    except Exception as exc:
        raise HTTPException(status_code=400, detail="Invalid webhook payload") from exc
    event_type = _normalize_name(payload.get("type"))
    data = payload.get("data") or {}
    tx_ref = str(data.get("tx_ref") or data.get("reference") or "").strip()
    gateway_transaction_id = int(data.get("id") or 0) or None
    if event_type != "charge.completed" or not tx_ref:
        return {"ok": True, "ignored": True}
    order = db.execute(
        text(
            """
            SELECT
                id, order_uid, sponsor_account_id, project_id, amount_total, currency,
                payment_method, payment_status, payment_gateway_reference, payment_gateway_transaction_id
            FROM green_sponsorship_orders
            WHERE UPPER(COALESCE(payment_gateway_reference, order_uid)) = UPPER(:tx_ref)
               OR UPPER(order_uid) = UPPER(:tx_ref)
            LIMIT 1
            """
        ),
        {"tx_ref": tx_ref},
    ).mappings().first()
    if not order:
        return {"ok": True, "ignored": True}
    try:
        result = _sync_sponsorship_order_flutterwave_payment(
            db,
            dict(order),
            transaction_id=gateway_transaction_id,
            tx_ref=tx_ref,
            actor="flutterwave_webhook",
            review_notes="Verified by Flutterwave webhook",
        )
        _log_audit_event(
            db,
            project_id=int(order.get("project_id") or 0) or None,
            entity_type="sponsorship_order",
            entity_id=int(order.get("id") or 0),
            action="sponsorship_payment_webhook",
            actor="flutterwave_webhook",
            details={"tx_ref": tx_ref, "verified": bool(result.get("verified")), "gateway_status": result.get("gateway_status")},
        )
        db.commit()
        if bool(result.get("should_send_payment_confirmation")):
            try:
                _notify_sponsor_payment_confirmed_email(db, int(order.get("id") or 0), request=request)
            except Exception:
                db.rollback()
        return {"ok": True, "verified": bool(result.get("verified"))}
    except HTTPException as exc:
        db.rollback()
        if exc.status_code >= 500:
            raise
        return {"ok": False, "detail": exc.detail}


@router.get("/sponsor/orders")
def list_sponsor_orders(sponsor_id: int = Query(...), db: Session = Depends(get_db)):
    sponsor_row = db.execute(
        text("SELECT id FROM green_sponsor_accounts WHERE id = :sponsor_id AND COALESCE(is_active, TRUE) = TRUE"),
        {"sponsor_id": int(sponsor_id)},
    ).scalar()
    if not sponsor_row:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
    rows = db.execute(
        text(
            """
            SELECT
                o.id, o.order_uid, o.project_id, o.quantity, o.amount_per_tree, o.amount_total, o.currency,
                o.payment_method, o.payment_reference, o.payment_status, o.order_status,
                o.payment_provider, o.payment_link, o.payment_gateway_reference, o.payment_gateway_transaction_id,
                o.payment_gateway_status, o.payment_verified_at,
                o.payment_proof_url, o.payment_proof_urls, o.dedication_type, o.dedication_name,
                o.dedication_message, o.purchaser_note, o.reviewed_by, o.reviewed_at, o.review_notes,
                o.created_at, o.updated_at,
                p.name AS project_name, p.location_text
            FROM green_sponsorship_orders o
            JOIN tree_projects p ON p.id = o.project_id
            WHERE o.sponsor_account_id = :sponsor_id
            ORDER BY o.created_at DESC, o.id DESC
            """
        ),
        {"sponsor_id": int(sponsor_id)},
    ).mappings().all()
    order_ids = [int(row["id"]) for row in rows]
    unit_counts: dict[int, dict[str, int]] = {}
    if order_ids:
        count_rows = db.execute(
            text(
                """
                SELECT
                    order_id,
                    COUNT(*) AS total_units,
                    COUNT(*) FILTER (WHERE tree_id IS NOT NULL) AS linked_units,
                    COUNT(*) FILTER (WHERE LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_tree') AS awaiting_tree_units
                FROM green_sponsorship_units
                WHERE order_id IN :order_ids
                GROUP BY order_id
                """
            ).bindparams(bindparam("order_ids", expanding=True)),
            {"order_ids": order_ids},
        ).mappings().all()
        unit_counts = {
            int(item["order_id"]): {
                "total_units": int(item.get("total_units") or 0),
                "linked_units": int(item.get("linked_units") or 0),
                "awaiting_tree_units": int(item.get("awaiting_tree_units") or 0),
            }
            for item in count_rows
        }
    payload: list[dict] = []
    for row in rows:
        item = dict(row)
        counts = unit_counts.get(int(item["id"]), {"total_units": 0, "linked_units": 0, "awaiting_tree_units": 0})
        item["payment_status"] = _normalize_sponsor_payment_status(item.get("payment_status"))
        item["order_status"] = _normalize_sponsor_order_status(item.get("order_status"))
        item["payment_proof_urls"] = _normalize_photo_urls(item.get("payment_proof_urls"))
        item["linked_units"] = counts["linked_units"]
        item["awaiting_tree_units"] = counts["awaiting_tree_units"]
        item["total_units"] = counts["total_units"]
        payload.append(item)
    return payload


@router.get("/sponsor/trees")
def list_sponsor_trees(sponsor_id: int = Query(...), db: Session = Depends(get_db)):
    sponsor_row = db.execute(
        text("SELECT id FROM green_sponsor_accounts WHERE id = :sponsor_id AND COALESCE(is_active, TRUE) = TRUE"),
        {"sponsor_id": int(sponsor_id)},
    ).scalar()
    if not sponsor_row:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
    rows = db.execute(
        text(
            """
            SELECT
                u.id AS unit_id, u.unit_uid, u.sponsorship_status, u.linked_at,
                u.dedication_type, u.dedication_name, u.dedication_message,
                o.id AS order_id, o.order_uid, o.payment_status, o.order_status, o.created_at AS order_created_at,
                p.id AS project_id, p.name AS project_name, p.location_text,
                t.id AS tree_id, t.project_tree_no, t.species, t.status AS tree_status,
                t.planting_date, t.photo_url, t.photo_urls, t.tree_height_m, t.tree_age_months,
                t.inventory_tree_count, t.count_in_carbon_scope, t.created_at AS tree_created_at,
                ST_X(t.geom) AS lng, ST_Y(t.geom) AS lat
            FROM green_sponsorship_units u
            JOIN green_sponsorship_orders o ON o.id = u.order_id
            JOIN tree_projects p ON p.id = u.project_id
            LEFT JOIN trees t ON t.id = u.tree_id
            WHERE u.sponsor_account_id = :sponsor_id
            ORDER BY u.created_at DESC, u.id DESC
            """
        ),
        {"sponsor_id": int(sponsor_id)},
    ).mappings().all()
    payload: list[dict] = []
    for row in rows:
        item = dict(row)
        item["sponsorship_status"] = _normalize_sponsor_unit_status(item.get("sponsorship_status"))
        item["payment_status"] = _normalize_sponsor_payment_status(item.get("payment_status"))
        item["order_status"] = _normalize_sponsor_order_status(item.get("order_status"))
        item["photo_urls"] = _normalize_photo_urls(item.get("photo_urls"))
        if item.get("tree_id"):
            item["carbon"] = _build_tree_carbon_summary(item)
        else:
            item["carbon"] = {"current_co2_kg": 0.0, "annual_co2_kg": 0.0, "lifetime_co2_kg": 0.0}
        payload.append(item)
    return payload


def _calculate_sponsor_achievement(db: Session, sponsor_id: int) -> dict:
    total_trees = db.execute(
        text(
            """
            SELECT COALESCE(SUM(quantity), 0)
            FROM green_sponsorship_orders
            WHERE sponsor_account_id = :sponsor_id
            AND (
                LOWER(payment_status) IN ('verified', 'paid')
                OR LOWER(order_status) IN ('paid', 'allocated', 'completed')
            )
            """
        ),
        {"sponsor_id": int(sponsor_id)},
    ).scalar() or 0
    
    level = "Seed Supporter"
    badge_code = "seed_supporter"
    badge_emoji = "🌱"
    next_level = "Green Supporter"
    next_level_threshold = 10
    
    if total_trees >= 500:
        level = "Earth Guardian"
        badge_code = "earth_guardian"
        badge_emoji = "🌍"
        next_level = None
        next_level_threshold = None
    elif total_trees >= 100:
        level = "Climate Champion"
        badge_code = "climate_champion"
        badge_emoji = "🌲"
        next_level = "Earth Guardian"
        next_level_threshold = 500
    elif total_trees >= 50:
        level = "Forest Builder"
        badge_code = "forest_builder"
        badge_emoji = "🌳"
        next_level = "Climate Champion"
        next_level_threshold = 100
    elif total_trees >= 10:
        level = "Green Supporter"
        badge_code = "green_supporter"
        badge_emoji = "🌿"
        next_level = "Forest Builder"
        next_level_threshold = 50
    elif total_trees >= 1:
        level = "Seed Supporter"
        badge_code = "seed_supporter"
        badge_emoji = "🌱"
        next_level = "Green Supporter"
        next_level_threshold = 10
    else:
        level = "Climate Contributor"
        badge_code = "climate_contributor"
        badge_emoji = "🌱"
        next_level = "Seed Supporter"
        next_level_threshold = 1
        
    progress_percentage = 0.0
    if next_level_threshold is not None:
        prev_threshold = 0
        if level == "Seed Supporter":
            prev_threshold = 1
        elif level == "Green Supporter":
            prev_threshold = 10
        elif level == "Forest Builder":
            prev_threshold = 50
        elif level == "Climate Champion":
            prev_threshold = 100
            
        range_size = next_level_threshold - prev_threshold
        if range_size > 0:
            progress_percentage = min(100.0, max(0.0, ((total_trees - prev_threshold) / range_size) * 100.0))
            
    return {
        "total_trees": int(total_trees),
        "level": level,
        "badge_code": badge_code,
        "badge_emoji": badge_emoji,
        "next_level": next_level,
        "next_level_threshold": next_level_threshold,
        "progress_percentage": round(progress_percentage, 1)
    }


def _get_leaderboard_data(db: Session) -> dict:
    from datetime import datetime
    start_of_month = datetime.utcnow().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    
    rows = db.execute(
        text(
            """
            SELECT
                sa.id,
                COALESCE(sa.organization_name, sa.full_name) AS display_name,
                sa.entity_category,
                SUM(o.quantity) AS monthly_trees,
                (
                    SELECT COALESCE(SUM(q.quantity), 0)
                    FROM green_sponsorship_orders q
                    WHERE q.sponsor_account_id = sa.id
                    AND (
                        LOWER(q.payment_status) IN ('verified', 'paid')
                        OR LOWER(q.order_status) IN ('paid', 'allocated', 'completed')
                    )
                ) AS all_time_trees
            FROM green_sponsorship_orders o
            JOIN green_sponsor_accounts sa ON sa.id = o.sponsor_account_id
            WHERE o.created_at >= :start_of_month
            AND (
                LOWER(o.payment_status) IN ('verified', 'paid')
                OR LOWER(o.order_status) IN ('paid', 'allocated', 'completed')
            )
            AND sa.leaderboard_visibility = 'public'
            GROUP BY sa.id, sa.organization_name, sa.full_name, sa.entity_category
            ORDER BY monthly_trees DESC, sa.id ASC
            LIMIT 50
            """
        ),
        {"start_of_month": start_of_month},
    ).mappings().all()
    
    top_overall = []
    top_schools = []
    top_communities = []
    top_companies = []
    
    for r in rows:
        all_time = int(r["all_time_trees"] or 0)
        
        level = "Seed Supporter"
        if all_time >= 500:
            level = "Earth Guardian"
        elif all_time >= 100:
            level = "Climate Champion"
        elif all_time >= 50:
            level = "Forest Builder"
        elif all_time >= 10:
            level = "Green Supporter"
        elif all_time >= 1:
            level = "Seed Supporter"
        else:
            level = "Climate Contributor"
            
        entry = {
            "sponsor_id": r["id"],
            "display_name": str(r["display_name"]).strip(),
            "entity_category": r["entity_category"],
            "monthly_trees": int(r["monthly_trees"] or 0),
            "all_time_trees": all_time,
            "achievement_level": level
        }
        top_overall.append(entry)
        
        cat = r["entity_category"]
        if cat == "school":
            top_schools.append(entry)
        elif cat == "community":
            top_communities.append(entry)
        elif cat == "company":
            top_companies.append(entry)
            
    def add_ranks(lst):
        ranked = []
        for idx, item in enumerate(lst):
            item_copy = dict(item)
            item_copy["rank"] = idx + 1
            ranked.append(item_copy)
        return ranked
        
    return {
        "top_overall": add_ranks(top_overall)[:20],
        "top_schools": add_ranks(top_schools)[:20],
        "top_communities": add_ranks(top_communities)[:20],
        "top_companies": add_ranks(top_companies)[:20]
    }


