def _normalize_optional_text(value: str | None) -> str | None:
    if value is None:
        return None
    cleaned = str(value).strip()
    return cleaned or None


def _social_follow_reward_already_awarded(db: Session, sponsor_id: int) -> bool:
    approved_claim = db.execute(
        text(
            """
            SELECT 1
            FROM green_sponsor_social_follow_claims
            WHERE sponsor_id = :sponsor_id
              AND COALESCE(points_awarded, FALSE) = TRUE
            LIMIT 1
            """
        ),
        {"sponsor_id": sponsor_id},
    ).scalar()
    if approved_claim:
        return True

    legacy_award = db.execute(
        text(
            """
            SELECT 1
            FROM green_activity_logs
            WHERE actor = :actor
              AND event_type = 'follow_landcheck_social_reward'
            LIMIT 1
            """
        ),
        {"actor": str(sponsor_id)},
    ).scalar()
    return bool(legacy_award)


def _serialize_sponsor_social_follow_claim(row) -> dict | None:
    if not row:
        return None
    item = dict(row)
    item["id"] = int(item.get("id") or 0)
    item["sponsor_id"] = int(item.get("sponsor_id") or 0)
    item["facebook_opened"] = bool(item.get("facebook_opened"))
    item["instagram_opened"] = bool(item.get("instagram_opened"))
    item["points_awarded"] = bool(item.get("points_awarded"))
    item["status"] = str(item.get("status") or "pending")
    item["facebook_screenshot_url"] = _normalize_optional_text(item.get("facebook_screenshot_url"))
    item["instagram_screenshot_url"] = _normalize_optional_text(item.get("instagram_screenshot_url"))
    item["supervisor_note"] = _normalize_optional_text(item.get("supervisor_note"))
    item["sponsor_name"] = _normalize_optional_text(item.get("sponsor_name"))
    item["sponsor_email"] = _normalize_optional_text(item.get("sponsor_email"))
    return item


def _get_latest_sponsor_social_follow_claim(db: Session, sponsor_id: int) -> dict | None:
    row = db.execute(
        text(
            """
            SELECT c.id,
                   c.sponsor_id,
                   c.facebook_screenshot_url,
                   c.instagram_screenshot_url,
                   c.facebook_opened,
                   c.instagram_opened,
                   c.status,
                   c.supervisor_note,
                   c.points_awarded,
                   c.created_at,
                   c.updated_at,
                   COALESCE(c.updated_at, c.created_at) AS submitted_at,
                   c.reviewed_at,
                   sa.full_name AS sponsor_name,
                   sa.email AS sponsor_email
            FROM green_sponsor_social_follow_claims c
            JOIN green_sponsor_accounts sa ON sa.id = c.sponsor_id
            WHERE c.sponsor_id = :sponsor_id
            ORDER BY COALESCE(c.updated_at, c.created_at) DESC, c.id DESC
            LIMIT 1
            """
        ),
        {"sponsor_id": sponsor_id},
    ).mappings().first()
    return _serialize_sponsor_social_follow_claim(row)


def _compute_active_referrer_rules(db: Session, sponsor_id: int) -> dict:
    personal_trees_sponsored = db.execute(
        text("""
            SELECT COALESCE(SUM(quantity), 0)
            FROM green_sponsorship_orders
            WHERE sponsor_account_id = :sponsor_id
              AND (
                  LOWER(COALESCE(payment_status, '')) IN ('paid', 'verified')
                  OR LOWER(COALESCE(order_status, '')) IN ('paid', 'allocated', 'completed')
              )
        """),
        {"sponsor_id": sponsor_id}
    ).scalar() or 0
    
    total_referred_users = db.execute(
        text("""
            SELECT COUNT(*)
            FROM green_sponsor_accounts
            WHERE referred_by_id = :sponsor_id
        """),
        {"sponsor_id": sponsor_id}
    ).scalar() or 0
    
    converted_referred_users = db.execute(
        text("""
            SELECT COUNT(DISTINCT sa.id)
            FROM green_sponsor_accounts sa
            JOIN green_sponsorship_orders o ON o.sponsor_account_id = sa.id
            WHERE sa.referred_by_id = :sponsor_id
              AND (
                  LOWER(COALESCE(o.payment_status, '')) IN ('paid', 'verified')
                  OR LOWER(COALESCE(o.order_status, '')) IN ('paid', 'allocated', 'completed')
              )
        """),
        {"sponsor_id": sponsor_id}
    ).scalar() or 0

    personal_sponsor_met = personal_trees_sponsored >= 1
    conversion_rate_met = True
    if total_referred_users > 0:
        conversion_rate_met = (converted_referred_users / total_referred_users) >= 0.2
        
    referral_rules_met = personal_sponsor_met and conversion_rate_met
    
    return {
        "personal_trees_sponsored": int(personal_trees_sponsored),
        "total_referred_users": int(total_referred_users),
        "converted_referred_users": int(converted_referred_users),
        "personal_sponsor_met": bool(personal_sponsor_met),
        "conversion_rate_met": bool(conversion_rate_met),
        "referral_rules_met": bool(referral_rules_met)
    }


def _compute_sponsor_merch_points(db: Session, sponsor_id: int, current_points: int) -> dict:
    sponsor_tree_points_earned = db.execute(
        text(
            """
            SELECT COALESCE(SUM(quantity * 25), 0)
            FROM green_sponsorship_orders
            WHERE sponsor_account_id = :sponsor_id
              AND (
                    LOWER(COALESCE(payment_status, '')) IN ('paid', 'verified')
                 OR LOWER(COALESCE(order_status, '')) IN ('paid', 'allocated', 'completed')
              )
            """
        ),
        {"sponsor_id": int(sponsor_id)},
    ).scalar() or 0

    merch_points_spent = db.execute(
        text(
            """
            SELECT COALESCE(SUM(points_spent), 0)
            FROM green_sponsor_point_redemptions
            WHERE sponsor_id = :sponsor_id
              AND reward_type LIKE 'merch_%'
              AND LOWER(COALESCE(status, 'pending')) <> 'rejected'
            """
        ),
        {"sponsor_id": int(sponsor_id)},
    ).scalar() or 0

    sponsor_tree_points_earned = int(sponsor_tree_points_earned or 0)
    merch_points_spent = int(merch_points_spent or 0)
    merch_source_balance = max(sponsor_tree_points_earned - merch_points_spent, 0)
    merch_eligible_points = max(min(int(current_points or 0), merch_source_balance), 0)

    return {
        "sponsor_tree_points_earned": sponsor_tree_points_earned,
        "merch_points_spent": merch_points_spent,
        "merch_eligible_points": merch_eligible_points,
    }


@router.get("/sponsor/points")
def get_sponsor_points(sponsor_id: int = Query(...), db: Session = Depends(get_db)):
    import uuid
    import json
    row = db.execute(
        text("""
            SELECT id, green_points, lifetime_points, referral_code, referred_by_id,
                   point_booster_multiplier, point_booster_remaining_uses, profile_photo_url,
                   unlocked_species, unlocked_avatars, unlocked_map_icons,
                   current_avatar_border, current_map_icon
            FROM green_sponsor_accounts
            WHERE id = :sponsor_id AND COALESCE(is_active, TRUE) = TRUE
        """),
        {"sponsor_id": int(sponsor_id)}
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
    
    item = dict(row)
    
    # Generate referral code if not exists
    if not item.get("referral_code"):
        ref = f"LC-REF-{sponsor_id}-{uuid.uuid4().hex[:4].upper()}"
        db.execute(text("UPDATE green_sponsor_accounts SET referral_code = :ref WHERE id = :sponsor_id"), {"ref": ref, "sponsor_id": sponsor_id})
        db.commit()
        item["referral_code"] = ref

    # Normalize JSON arrays
    for key in ["unlocked_species", "unlocked_avatars", "unlocked_map_icons"]:
        val = item.get(key)
        if val is None:
            item[key] = []
        elif isinstance(val, str):
            try:
                item[key] = json.loads(val)
            except Exception:
                item[key] = []
        elif not isinstance(val, list):
            item[key] = []
            
    # Cast point booster multiplier to float for frontend compatibility
    if item.get("point_booster_multiplier") is not None:
        item["point_booster_multiplier"] = float(item["point_booster_multiplier"])
        
    # Inject referral rules metrics
    rules = _compute_active_referrer_rules(db, int(sponsor_id))
    item.update(rules)
    item.update(_compute_sponsor_merch_points(db, int(sponsor_id), int(item.get("green_points") or 0)))
            
    return item


@router.post("/sponsor/redeem")
def redeem_sponsor_reward(payload: SponsorRedeemPayload, db: Session = Depends(get_db)):
    import json
    sponsor_id = payload.sponsor_id
    reward_type = payload.reward_type.strip()
    
    row = db.execute(
        text("""
            SELECT id, green_points, unlocked_species, unlocked_avatars, unlocked_map_icons
            FROM green_sponsor_accounts
            WHERE id = :sponsor_id AND COALESCE(is_active, TRUE) = TRUE
        """),
        {"sponsor_id": sponsor_id}
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
        
    rules = _compute_active_referrer_rules(db, sponsor_id)
    if not rules["referral_rules_met"]:
        raise HTTPException(
            status_code=400,
            detail="Referral rules not met. You must sponsor at least 1 tree yourself and maintain at least 20% conversion rate on referred signups to spend points."
        )
        
    current_points = int(row.get("green_points") or 0)
    
    # Determine cost and apply changes
    cost = 0
    if reward_type == "multiplier":  # Sunshine Elixir point booster
        cost = 50
    elif reward_type.startswith("avatar_"):
        cost = 200
    elif reward_type.startswith("map_icon_"):
        cost = 150
    elif reward_type.startswith("unlock_species_"):
        cost = 500
    elif reward_type.startswith("merch_"):
        cost = 800 if reward_type == "merch_tote" else (1000 if reward_type == "merch_cap" else 1500)
    else:
        raise HTTPException(status_code=400, detail="Invalid reward type")
        
    if reward_type.startswith("merch_"):
        merch_points = _compute_sponsor_merch_points(db, sponsor_id, current_points)
        if int(merch_points.get("merch_eligible_points") or 0) < cost:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"This merchandise item requires {cost} sponsor tree GP. "
                    f"Only GP earned from paid tree sponsorship qualifies for merch redemption. "
                    f"Current merch-eligible balance: {int(merch_points.get('merch_eligible_points') or 0)} GP."
                ),
            )

    if current_points < cost:
        raise HTTPException(status_code=400, detail="Insufficient points balance")
        
    # Process redemption
    db.execute(
        text("UPDATE green_sponsor_accounts SET green_points = green_points - :cost, updated_at = NOW() WHERE id = :sponsor_id"),
        {"cost": cost, "sponsor_id": sponsor_id}
    )
    
    # Log redemption
    db.execute(
        text("""
            INSERT INTO green_sponsor_point_redemptions (sponsor_id, reward_type, points_spent, shipping_details)
            VALUES (:sponsor_id, :reward_type, :cost, CAST(:shipping_details AS JSONB))
        """),
        {
            "sponsor_id": sponsor_id,
            "reward_type": reward_type,
            "cost": cost,
            "shipping_details": json.dumps(payload.shipping_details) if payload.shipping_details else None
        }
    )
    _log_activity(
        db,
        "sponsor_app",
        "sponsor_redeem",
        f"Sponsor with ID {sponsor_id} redeemed reward '{reward_type}' for {cost} GP",
        str(sponsor_id),
        {"sponsor_id": sponsor_id, "reward_type": reward_type, "points_spent": cost}
    )
    
    # Unlock digital assets/boosters
    if reward_type == "multiplier":
        db.execute(
            text("""
                UPDATE green_sponsor_accounts
                SET point_booster_multiplier = 2.0,
                    point_booster_remaining_uses = point_booster_remaining_uses + 1,
                    updated_at = NOW()
                WHERE id = :sponsor_id
            """),
            {"sponsor_id": sponsor_id}
        )
    elif reward_type.startswith("avatar_"):
        avatar_name = reward_type.replace("avatar_", "")
        unlocked = row.get("unlocked_avatars") or []
        if isinstance(unlocked, str):
            try: unlocked = json.loads(unlocked)
            except Exception: unlocked = []
        if avatar_name not in unlocked:
            unlocked.append(avatar_name)
        db.execute(
            text("UPDATE green_sponsor_accounts SET unlocked_avatars = CAST(:val AS JSONB), updated_at = NOW() WHERE id = :sponsor_id"),
            {"val": json.dumps(unlocked), "sponsor_id": sponsor_id}
        )
    elif reward_type.startswith("map_icon_"):
        icon_name = reward_type.replace("map_icon_", "")
        unlocked = row.get("unlocked_map_icons") or []
        if isinstance(unlocked, str):
            try: unlocked = json.loads(unlocked)
            except Exception: unlocked = []
        if icon_name not in unlocked:
            unlocked.append(icon_name)
        db.execute(
            text("UPDATE green_sponsor_accounts SET unlocked_map_icons = CAST(:val AS JSONB), updated_at = NOW() WHERE id = :sponsor_id"),
            {"val": json.dumps(unlocked), "sponsor_id": sponsor_id}
        )
    elif reward_type.startswith("unlock_species_"):
        species_name = reward_type.replace("unlock_species_", "")
        unlocked = row.get("unlocked_species") or []
        if isinstance(unlocked, str):
            try: unlocked = json.loads(unlocked)
            except Exception: unlocked = []
        if species_name not in unlocked:
            unlocked.append(species_name)
        db.execute(
            text("UPDATE green_sponsor_accounts SET unlocked_species = CAST(:val AS JSONB), updated_at = NOW() WHERE id = :sponsor_id"),
            {"val": json.dumps(unlocked), "sponsor_id": sponsor_id}
        )
        
    db.commit()
    return {"ok": True, "spent": cost, "reward_type": reward_type}


