@router.post("/sponsor/update-appearance")
def update_sponsor_appearance(payload: SponsorUpdateAppearancePayload, db: Session = Depends(get_db)):
    import json
    sponsor_id = payload.sponsor_id
    avatar_border = payload.avatar_border
    map_icon = payload.map_icon
    
    row = db.execute(
        text("SELECT unlocked_avatars, unlocked_map_icons FROM green_sponsor_accounts WHERE id = :sponsor_id"),
        {"sponsor_id": sponsor_id}
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
        
    # Check if border is unlocked
    if avatar_border and avatar_border != "none":
        unlocked = row.get("unlocked_avatars") or []
        if isinstance(unlocked, str): unlocked = json.loads(unlocked)
        if avatar_border not in unlocked:
            raise HTTPException(status_code=400, detail="Avatar border not unlocked")
            
    # Check if map icon is unlocked
    if map_icon and map_icon != "default":
        unlocked = row.get("unlocked_map_icons") or []
        if isinstance(unlocked, str): unlocked = json.loads(unlocked)
        if map_icon not in unlocked:
            raise HTTPException(status_code=400, detail="Map icon not unlocked")
            
    db.execute(
        text("""
            UPDATE green_sponsor_accounts
            SET current_avatar_border = :avatar_border,
                current_map_icon = :map_icon,
                updated_at = NOW()
            WHERE id = :sponsor_id
        """),
        {"avatar_border": avatar_border, "map_icon": map_icon, "sponsor_id": sponsor_id}
    )
    db.commit()
    return {"ok": True}


@router.post("/sponsor/apply-referral")
def apply_referral_code(payload: SponsorApplyReferralPayload, db: Session = Depends(get_db)):
    sponsor_id = payload.sponsor_id
    ref_code = payload.referral_code.strip()
    
    sponsor = db.execute(
        text("SELECT referred_by_id, referral_code FROM green_sponsor_accounts WHERE id = :sponsor_id"),
        {"sponsor_id": sponsor_id}
    ).mappings().first()
    if not sponsor:
        raise HTTPException(status_code=404, detail="Sponsor account not found")
        
    if sponsor.get("referred_by_id"):
        raise HTTPException(status_code=400, detail="Referral already applied to this account")
        
    if ref_code == sponsor.get("referral_code"):
        raise HTTPException(status_code=400, detail="Cannot refer yourself")
        
    referrer = db.execute(
        text("SELECT id FROM green_sponsor_accounts WHERE UPPER(referral_code) = UPPER(:ref_code)"),
        {"ref_code": ref_code}
    ).mappings().first()
    if not referrer:
        raise HTTPException(status_code=404, detail="Invalid referral code")
        
    db.execute(
        text("UPDATE green_sponsor_accounts SET referred_by_id = :referrer_id, updated_at = NOW() WHERE id = :sponsor_id"),
        {"referrer_id": referrer.get("id"), "sponsor_id": sponsor_id}
    )
    db.commit()
    return {"ok": True, "message": "Referral code applied!"}


def _build_public_asset_url(raw_value: object, request: Request | None = None) -> str | None:
    raw = str(raw_value or "").strip()
    if not raw:
        return None
    if raw.startswith("//"):
        raw = f"https:{raw}"
    if raw.lower().startswith(("http://", "https://", "data:")):
        return raw
    normalized = _normalize_logo_asset_path(raw) or raw
    if normalized.startswith("//"):
        normalized = f"https:{normalized}"
    if normalized.lower().startswith(("http://", "https://", "data:")):
        return normalized
    base_url = _build_public_api_base_url(request)
    path = f"/{normalized.lstrip('/')}"
    return f"{base_url}{path}" if base_url else path


def _build_sponsor_public_story_url(unit_uid: object, request: Request | None = None) -> str | None:
    uid = str(unit_uid or "").strip()
    if not uid:
        return None
    base_url = _build_public_api_base_url(request)
    if not base_url:
        return None
    return f"{base_url}/green/sponsor/public/trees/{quote(uid)}"


def _build_sponsor_public_certificate_url(unit_uid: object, request: Request | None = None) -> str | None:
    uid = str(unit_uid or "").strip()
    if not uid:
        return None
    base_url = _build_public_api_base_url(request)
    if not base_url:
        return None
    return f"{base_url}/green/sponsor/public/trees/{quote(uid)}/certificate.pdf"


def _build_google_maps_direction_url(lat_value: object, lng_value: object) -> str | None:
    try:
        lat = float(lat_value)
        lng = float(lng_value)
    except Exception:
        return None
    return f"https://www.google.com/maps/dir/?api=1&destination={lat},{lng}"


def _load_sponsor_tree_story_timeline(db: Session, tree_id: int, request: Request | None = None) -> list[dict]:
    task_rows = db.execute(
        text(
            """
            SELECT
                id, task_type, status, review_state, notes, photo_url, photo_urls,
                completed_at, submitted_at, reviewed_at, reviewed_by, review_notes,
                reported_tree_status, activity_lng, activity_lat, activity_recorded_at
            FROM tree_tasks
            WHERE tree_id = :tree_id
              AND LOWER(COALESCE(review_state, 'none')) IN ('approved', 'none')
              AND LOWER(COALESCE(status, 'pending')) = 'done'
            ORDER BY COALESCE(reviewed_at, completed_at, submitted_at, created_at) DESC, id DESC
            """
        ),
        {"tree_id": int(tree_id)},
    ).mappings().all()
    timeline: list[dict] = []
    for task in task_rows:
        task_item = dict(task)
        task_urls = _normalize_photo_urls(task_item.get("photo_urls"))
        primary_photo = str(task_item.get("photo_url") or "").strip()
        if primary_photo and primary_photo not in task_urls:
            task_urls.insert(0, primary_photo)
        task_item["photo_urls"] = [
            candidate
            for candidate in (_build_public_asset_url(url, request=request) for url in task_urls)
            if candidate
        ]
        task_item["photo_url"] = task_item["photo_urls"][0] if task_item["photo_urls"] else _build_public_asset_url(primary_photo, request=request)
        timeline.append(task_item)
    return timeline


def _hydrate_sponsor_tree_story_item(item: dict, db: Session, request: Request | None = None) -> dict:
    item["sponsorship_status"] = _normalize_sponsor_unit_status(item.get("sponsorship_status"))
    item["payment_status"] = _normalize_sponsor_payment_status(item.get("payment_status"))
    item["order_status"] = _normalize_sponsor_order_status(item.get("order_status"))
    item["carbon"] = _build_tree_carbon_summary(item) if item.get("tree_id") else {"current_co2_kg": 0.0, "annual_co2_kg": 0.0, "lifetime_co2_kg": 0.0}

    root_photo_urls = _normalize_photo_urls(item.get("photo_urls"))
    primary_root_photo = str(item.get("photo_url") or "").strip()
    if primary_root_photo and primary_root_photo not in root_photo_urls:
        root_photo_urls.insert(0, primary_root_photo)

    timeline = _load_sponsor_tree_story_timeline(db, int(item["tree_id"]), request=request) if item.get("tree_id") else []
    gallery_urls: list[str] = []
    seen: set[str] = set()
    tree_photo_proxy_url = _build_tree_best_photo_url(item.get("tree_id"), request=request)
    if tree_photo_proxy_url:
        seen.add(tree_photo_proxy_url)
        gallery_urls.append(tree_photo_proxy_url)
    for candidate in root_photo_urls:
        public_url = _build_public_asset_url(candidate, request=request)
        if public_url and public_url not in seen:
            seen.add(public_url)
            gallery_urls.append(public_url)
    for event in timeline:
        for candidate in event.get("photo_urls") or []:
            public_url = _build_public_asset_url(candidate, request=request)
            if public_url and public_url not in seen:
                seen.add(public_url)
                gallery_urls.append(public_url)

    item["photo_urls"] = gallery_urls
    item["photo_url"] = tree_photo_proxy_url or (gallery_urls[0] if gallery_urls else _build_public_asset_url(primary_root_photo, request=request))
    item["timeline"] = timeline
    item["maps_url"] = _build_google_maps_direction_url(item.get("lat"), item.get("lng"))
    item["public_story_url"] = _build_sponsor_public_story_url(item.get("unit_uid"), request=request)
    item["public_certificate_url"] = _build_sponsor_public_certificate_url(item.get("unit_uid"), request=request)
    return item


def _render_public_sponsor_tree_story_html(item: dict) -> str:
    sponsor_name_raw = str(item.get("sponsor_name") or "").strip()
    sponsor_org = html.escape(str(item.get("sponsor_organization_name") or "").strip())
    
    is_sponsored = bool(sponsor_name_raw)
    if is_sponsored:
        sponsor_name = html.escape(sponsor_name_raw)
        sponsor_desc = f"This page shows the real map location, approved field photos, care history, and certificate for the sponsored tree linked to {sponsor_name}."
        sponsor_box_html = f"""
            <article class="detail-card"><label>Sponsor</label><strong>{sponsor_name}</strong></article>
            <article class="detail-card"><label>Organization</label><strong>{sponsor_org or 'Individual sponsor'}</strong></article>
        """
    else:
        sponsor_name = "Climate Sponsor"
        sponsor_desc = "This page shows the real map location, approved field photos, and care history for this tree. This tree is currently available for sponsorship!"
        sponsor_box_html = """
            <article class="detail-card" style="grid-column: span 2; background: #fffcf4; border: 1px dashed #c5a059;">
                <label style="color: #b8860b;">Sponsorship Available</label>
                <strong style="color: #083e20; font-size: 1.1rem; margin-top: 4px;">Sponsor this tree & receive live updates!</strong>
                <p style="margin: 6px 0 0; font-size: 0.8rem; color: #53705f;">Use the LandCheck Green mobile app to sponsor this tree, link your name, and receive a digital certificate.</p>
            </article>
        """
    project_name = html.escape(str(item.get("project_name") or "LandCheck Green project").strip() or "LandCheck Green project")
    species = html.escape(str(item.get("species") or "Verified tree").strip() or "Verified tree")
    tree_label = html.escape(
        f"Tree #{int(item.get('project_tree_no') or 0)}" if item.get("project_tree_no") else str(item.get("unit_uid") or "Sponsored tree")
    )
    location_text = html.escape(str(item.get("location_text") or "Verified LandCheck Green project area").strip() or "Verified LandCheck Green project area")
    reference = html.escape(str(item.get("unit_uid") or item.get("tree_id") or "-"))
    status_label = html.escape(str(item.get("tree_status") or item.get("sponsorship_status") or "active").replace("_", " ").title())
    planting_date = html.escape(str(item.get("planting_date") or "-"))
    photo_url = str(item.get("photo_url") or "").strip()
    safe_photo_url = html.escape(photo_url, quote=True)
    public_certificate_url = html.escape(str(item.get("public_certificate_url") or "").strip())
    public_story_url = html.escape(str(item.get("public_story_url") or "").strip())
    maps_url = html.escape(str(item.get("maps_url") or "").strip())
    maps_action_html = (
        f'<a class="ghost-button" href="{maps_url}" target="_blank" rel="noopener noreferrer">Find this tree in Google Maps</a>'
        if maps_url
        else '<span class="ghost-button" style="opacity:0.58;">Map direction pending</span>'
    )
    current_co2 = float((item.get("carbon") or {}).get("current_co2_kg") or 0)
    annual_co2 = float((item.get("carbon") or {}).get("annual_co2_kg") or 0)
    lifetime_co2 = float((item.get("carbon") or {}).get("lifetime_co2_kg") or 0)
    timeline = item.get("timeline") or []
    photo_cards = []
    for index, url in enumerate((item.get("photo_urls") or [])[:8], start=1):
        safe_url = html.escape(str(url))
        photo_cards.append(
            f"""
            <figure class="gallery-card">
              <img src="{safe_url}" alt="Verified tree evidence {index}" loading="lazy" />
              <figcaption>Verified field evidence {index}</figcaption>
            </figure>
            """
        )
    if not photo_cards:
        photo_cards.append('<div class="empty-card">Approved field photos will appear here as the field team uploads verified evidence.</div>')

    timeline_cards = []
    for event in timeline[:8]:
        event_title = html.escape(str(event.get("task_type") or "Field update").replace("_", " ").title())
        event_status = html.escape(str(event.get("reported_tree_status") or event.get("status") or "done").replace("_", " ").title())
        event_date = html.escape(str(event.get("reviewed_at") or event.get("completed_at") or event.get("submitted_at") or "-"))
        event_notes = html.escape(str(event.get("notes") or "").strip())
        timeline_cards.append(
            f"""
            <article class="timeline-card">
              <div class="timeline-head">
                <strong>{event_title}</strong>
                <span>{event_status}</span>
              </div>
              <p class="timeline-date">{event_date}</p>
              {f"<p>{event_notes}</p>" if event_notes else ""}
            </article>
            """
        )
    if not timeline_cards:
        timeline_cards.append('<div class="empty-card">No reviewed maintenance records are published yet.</div>')

    dedication_parts = []
    if str(item.get("dedication_type") or "").strip():
        dedication_parts.append(str(item.get("dedication_type") or "").replace("_", " ").title())
    if str(item.get("dedication_name") or "").strip():
        dedication_parts.append(str(item.get("dedication_name") or "").strip())
    dedication_line = html.escape(" | ".join(dedication_parts))
    dedication_message = html.escape(str(item.get("dedication_message") or "").strip())
    map_block = ""
    try:
        lat = float(item.get("lat"))
        lng = float(item.get("lng"))
        map_block = f"""
        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow">Verified map</p>
              <h2>Find this tree on the ground</h2>
            </div>
            <a class="ghost-button" href="{maps_url}" target="_blank" rel="noopener noreferrer">Find this tree in Google Maps</a>
          </div>
          <div id="story-map" class="map-box"></div>
          <p class="coords">Latitude {lat:.6f} &middot; Longitude {lng:.6f}</p>
        </section>
        <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
        <script>
          (function () {{
            const map = L.map('story-map', {{ scrollWheelZoom: false }}).setView([{lat}, {lng}], 15);
            L.tileLayer('https://{{s}}.tile.openstreetmap.org/{{z}}/{{x}}/{{y}}.png', {{
              maxZoom: 19,
              attribution: '&copy; OpenStreetMap contributors'
            }}).addTo(map);
            L.circleMarker([{lat}, {lng}], {{
              radius: 11,
              color: '#0f6f39',
              weight: 3,
              fillColor: '#7ee08e',
              fillOpacity: 0.95
            }}).addTo(map).bindPopup('{species}');
          }})();
        </script>
        """
    except Exception:
        map_block = """
        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow">Verified map</p>
              <h2>Location will appear once coordinates are available</h2>
            </div>
          </div>
          <div class="empty-card">This sponsored tree is linked to a verified project, but GPS coordinates are not attached yet.</div>
        </section>
        """

    og_image = f'<meta property="og:image" content="{safe_photo_url}" /><meta name="twitter:image" content="{safe_photo_url}" />' if photo_url else ""
    hero_style = f' style="background-image:url(\'{safe_photo_url}\')"' if photo_url else ""
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>LandCheck Green | {tree_label}</title>
    <meta name="description" content="Verified LandCheck Green sponsor tree record with map, field photos, care history, and certificate." />
    <meta property="og:title" content="LandCheck Green | {tree_label}" />
    <meta property="og:description" content="See the verified map, field photos, care history, and digital certificate for this sponsored tree." />
    <meta property="og:type" content="website" />
    <meta property="og:url" content="{public_story_url}" />
    <meta name="twitter:card" content="summary_large_image" />
    {og_image}
    <meta name="theme-color" content="#0f6f39" />
    <link rel="preconnect" href="https://unpkg.com" />
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
    <style>
      :root {{
        --bg: #eef8ef;
        --panel: rgba(255,255,255,0.96);
        --panel-soft: rgba(245,250,246,0.94);
        --border: rgba(17, 84, 42, 0.12);
        --text: #163424;
        --muted: #53705f;
        --emerald: #0f6f39;
        --emerald-dark: #0a4f28;
        --emerald-soft: #dff6e5;
        --shadow: 0 24px 48px rgba(11, 54, 28, 0.12);
      }}
      * {{ box-sizing: border-box; }}
      body {{
        margin: 0;
        font-family: Inter, "Segoe UI", system-ui, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top right, rgba(126, 224, 142, 0.3), transparent 24rem),
          linear-gradient(180deg, #f7fcf7 0%, var(--bg) 100%);
      }}
      a {{ color: inherit; text-decoration: none; }}
      .shell {{
        max-width: 1080px;
        margin: 0 auto;
        padding: 24px 18px 60px;
      }}
      .hero {{
        position: relative;
        overflow: hidden;
        border-radius: 34px;
        min-height: 380px;
        background: linear-gradient(140deg, rgba(7,48,21,0.94), rgba(15,111,57,0.84));
        box-shadow: var(--shadow);
      }}
      .hero-media {{
        position: absolute;
        inset: 0;
        background-position: center;
        background-size: cover;
        opacity: 0.36;
        filter: saturate(1.05);
      }}
      .hero-overlay {{
        position: relative;
        z-index: 1;
        display: grid;
        gap: 18px;
        padding: 26px;
        color: #fff;
      }}
      .eyebrow {{
        margin: 0 0 8px;
        color: rgba(255,255,255,0.78);
        font-size: 12px;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }}
      .hero h1 {{
        margin: 0;
        max-width: 620px;
        font-size: clamp(2rem, 4vw, 3.5rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
      }}
      .hero p {{
        margin: 0;
        max-width: 620px;
        color: rgba(255,255,255,0.9);
        font-size: 1rem;
        line-height: 1.65;
      }}
      .chip-row, .action-row, .metric-grid, .detail-grid, .gallery-grid, .timeline-grid {{
        display: grid;
        gap: 14px;
      }}
      .chip-row {{
        grid-template-columns: repeat(auto-fit, minmax(160px, max-content));
      }}
      .chip {{
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 11px 14px;
        border-radius: 999px;
        background: rgba(255,255,255,0.12);
        border: 1px solid rgba(255,255,255,0.16);
        font-size: 0.92rem;
        font-weight: 700;
      }}
      .action-row {{
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      }}
      .action-button, .ghost-button {{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        min-height: 54px;
        padding: 0 18px;
        border-radius: 18px;
        font-weight: 800;
      }}
      .action-button {{
        background: #fff;
        color: var(--emerald-dark);
      }}
      .ghost-button {{
        border: 1px solid rgba(17,84,42,0.14);
        background: rgba(244,251,246,0.92);
        color: var(--emerald-dark);
      }}
      .metric-grid {{
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        margin-top: 6px;
      }}
      .metric-card, .panel, .detail-card, .gallery-card, .timeline-card, .empty-card {{
        border-radius: 26px;
        border: 1px solid var(--border);
        background: var(--panel);
        box-shadow: var(--shadow);
      }}
      .metric-card {{
        padding: 18px 18px 16px;
      }}
      .metric-card strong {{
        display: block;
        margin-bottom: 8px;
        font-size: 1.9rem;
        line-height: 1.1;
      }}
      .metric-card span {{
        color: var(--muted);
        font-weight: 600;
      }}
      .stack {{
        display: grid;
        gap: 18px;
        margin-top: 18px;
      }}
      .panel {{
        padding: 22px;
      }}
      .panel-head {{
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 14px;
        margin-bottom: 16px;
      }}
      .panel h2 {{
        margin: 0;
        font-size: 1.45rem;
        letter-spacing: -0.03em;
      }}
      .panel p {{
        margin: 6px 0 0;
        color: var(--muted);
        line-height: 1.7;
      }}
      .detail-grid {{
        grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
      }}
      .detail-card {{
        padding: 16px 18px;
        background: var(--panel-soft);
      }}
      .detail-card label {{
        display: block;
        color: var(--muted);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }}
      .detail-card strong {{
        display: block;
        margin-top: 8px;
        font-size: 1rem;
        line-height: 1.55;
      }}
      .gallery-grid {{
        grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
      }}
      .gallery-card {{
        overflow: hidden;
      }}
      .gallery-card img {{
        display: block;
        width: 100%;
        height: 220px;
        object-fit: cover;
        background: #edf5ef;
      }}
      .gallery-card figcaption {{
        padding: 12px 14px 15px;
        color: var(--muted);
        font-size: 0.92rem;
        font-weight: 700;
      }}
      .timeline-grid {{
        grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      }}
      .timeline-card {{
        padding: 18px;
      }}
      .timeline-head {{
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 10px;
      }}
      .timeline-head strong {{
        font-size: 1rem;
      }}
      .timeline-head span {{
        padding: 6px 10px;
        border-radius: 999px;
        background: var(--emerald-soft);
        color: var(--emerald-dark);
        font-size: 0.8rem;
        font-weight: 800;
      }}
      .timeline-date {{
        margin-top: 8px;
        color: var(--muted);
        font-size: 0.82rem;
      }}
      .empty-card {{
        padding: 22px;
        color: var(--muted);
        background: var(--panel-soft);
      }}
      .map-box {{
        width: 100%;
        height: 360px;
        border-radius: 24px;
        overflow: hidden;
        border: 1px solid var(--border);
      }}
      .coords {{
        margin-top: 12px !important;
        font-size: 0.9rem;
      }}
      @media (max-width: 720px) {{
        .shell {{ padding: 16px 14px 40px; }}
        .hero-overlay {{ padding: 20px; }}
        .panel-head {{ flex-direction: column; }}
      }}
    </style>
  </head>
  <body>
    <main class="shell">
      <section class="hero">
        <div class="hero-media"{hero_style}></div>
        <div class="hero-overlay">
          <div>
            <p class="eyebrow">LandCheck Green verified tree story</p>
            <h1>{tree_label} is a live, field-verified climate action record.</h1>
            <p>{sponsor_desc}</p>
          </div>
          <div class="chip-row">
            <div class="chip">Status &middot; {status_label}</div>
            <div class="chip">Species &middot; {species}</div>
            <div class="chip">Project &middot; {project_name}</div>
          </div>
          <div class="action-row">
            {maps_action_html}
          </div>
        </div>
      </section>

      <section class="metric-grid stack">
        <article class="metric-card">
          <label class="eyebrow" style="color: var(--muted);">Current stored CO2</label>
          <strong>{current_co2:,.2f} kg</strong>
          <span>Live carbon already attributed to this verified tree</span>
        </article>
        <article class="metric-card">
          <label class="eyebrow" style="color: var(--muted);">Annual sequestration</label>
          <strong>{annual_co2:,.2f} kg/yr</strong>
          <span>Expected yearly climate contribution from this tree</span>
        </article>
        <article class="metric-card">
          <label class="eyebrow" style="color: var(--muted);">40-year projection</label>
          <strong>{lifetime_co2:,.2f} kg</strong>
          <span>Long-range carbon value tied to the planting record</span>
        </article>
        <article class="metric-card">
          <label class="eyebrow" style="color: var(--muted);">Reviewed care updates</label>
          <strong>{len(timeline)}</strong>
          <span>Published maintenance and field verification records</span>
        </article>
      </section>

      <div class="stack">
        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow" style="color: var(--muted);">Sponsor record</p>
              <h2>Verified sponsorship details</h2>
            </div>
          </div>
          <div class="detail-grid">
            {sponsor_box_html}
            <article class="detail-card"><label>Project</label><strong>{project_name}</strong></article>
            <article class="detail-card"><label>Location</label><strong>{location_text}</strong></article>
            <article class="detail-card"><label>Planting date</label><strong>{planting_date}</strong></article>
            <article class="detail-card"><label>Reference</label><strong>{reference}</strong></article>
            {f'<article class="detail-card"><label>Dedication</label><strong>{dedication_line or "Supporter dedication"}</strong></article>' if dedication_line else ''}
            {f'<article class="detail-card"><label>Message</label><strong>{dedication_message}</strong></article>' if dedication_message else ''}
          </div>
        </section>

        {map_block}

        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow" style="color: var(--muted);">Field evidence</p>
              <h2>Approved photo evidence</h2>
            </div>
          </div>
          <div class="gallery-grid">
            {''.join(photo_cards)}
          </div>
        </section>

        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow" style="color: var(--muted);">Care history</p>
              <h2>Reviewed maintenance timeline</h2>
            </div>
          </div>
          <div class="timeline-grid">
            {''.join(timeline_cards)}
          </div>
        </section>

        <section class="panel" style="background: linear-gradient(135deg, var(--emerald) 0%, var(--emerald-dark) 100%); color: #ffffff; padding: 32px; display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; border: none;">
          <div style="flex: 1; min-width: 280px;">
            <p class="eyebrow" style="color: #a3f7ba; margin-bottom: 8px;">Sponsor a tree</p>
            <h2 style="color: #ffffff; margin: 0 0 8px 0; font-size: 1.8rem; font-weight: 800; line-height: 1.2;">You also can sponsor a tree!</h2>
            <p style="color: #d1f7dc; margin: 0; font-size: 1rem; line-height: 1.5;">Download the LC Green app in Play Store to contribute to climate action and track your own trees.</p>
          </div>
          <div>
            <a href="https://play.google.com/store/apps/details?id=online.landcheck.mobile" target="_blank" rel="noopener noreferrer" style="display: inline-flex; align-items: center; gap: 10px; background: #ffffff; color: var(--emerald-dark); padding: 14px 28px; border-radius: 999px; font-weight: 800; font-size: 1rem; box-shadow: 0 8px 20px rgba(0,0,0,0.15); text-decoration: none;">
              Download LC Green App in Play Store
            </a>
          </div>
        </section>
      </div>
    </main>
  </body>
</html>"""


def _render_sponsor_public_terms_html(request: Request | None = None) -> str:
    privacy_url = html.escape(_build_public_privacy_policy_url(), quote=True)
    support_email = html.escape(str(os.getenv("LANDCHECK_SUPPORT_EMAIL") or os.getenv("SMTP_FROM_EMAIL") or "support@landcheck.online").strip())
    terms_version = html.escape(SPONSOR_TERMS_VERSION)
    effective_date = html.escape(SPONSOR_TERMS_EFFECTIVE_DATE)
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>LandCheck Green Sponsor Terms</title>
    <meta name="description" content="LandCheck Green public sponsor terms, checkout conditions, privacy references, and supporter responsibilities." />
    <style>
      :root {{
        --bg: #edf8ee;
        --panel: rgba(255,255,255,0.96);
        --border: rgba(13, 78, 35, 0.10);
        --text: #163424;
        --muted: #53705f;
        --emerald: #0f6f39;
        --emerald-dark: #0b4f28;
        --shadow: 0 22px 48px rgba(12, 61, 31, 0.10);
      }}
      * {{ box-sizing: border-box; }}
      body {{
        margin: 0;
        font-family: Inter, "Segoe UI", system-ui, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top right, rgba(126,224,142,0.24), transparent 24rem),
          linear-gradient(180deg, #f9fdf9 0%, var(--bg) 100%);
      }}
      .shell {{ max-width: 980px; margin: 0 auto; padding: 26px 18px 54px; }}
      .hero {{
        border-radius: 30px;
        overflow: hidden;
        background: linear-gradient(140deg, rgba(7,48,21,0.95), rgba(15,111,57,0.88));
        box-shadow: var(--shadow);
        color: #fff;
        padding: 30px 26px;
      }}
      .hero p, .hero h1 {{ margin: 0; }}
      .eyebrow {{
        color: rgba(255,255,255,0.74);
        font-size: 12px;
        font-weight: 800;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }}
      .hero h1 {{
        margin-top: 10px;
        font-size: clamp(2rem, 4vw, 3.2rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }}
      .hero .meta {{
        margin-top: 12px;
        color: rgba(255,255,255,0.88);
        font-size: 0.98rem;
        line-height: 1.7;
      }}
      .stack {{ display: grid; gap: 18px; margin-top: 18px; }}
      .panel {{
        background: var(--panel);
        border: 1px solid var(--border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        padding: 22px;
      }}
      .panel h2 {{
        margin: 0 0 8px;
        font-size: 1.3rem;
        letter-spacing: -0.03em;
      }}
      .panel p {{
        margin: 0;
        color: var(--muted);
        line-height: 1.75;
      }}
      .panel ul {{
        margin: 12px 0 0;
        padding-left: 18px;
        color: var(--muted);
        line-height: 1.75;
      }}
      .meta-grid {{
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 14px;
      }}
      .meta-card {{
        border-radius: 18px;
        border: 1px solid var(--border);
        background: rgba(246,251,247,0.96);
        padding: 16px 18px;
      }}
      .meta-card strong {{
        display: block;
        margin-top: 8px;
        font-size: 1rem;
        color: var(--emerald-dark);
      }}
      a {{ color: var(--emerald); font-weight: 700; text-decoration: none; }}
      @media (max-width: 720px) {{
        .shell {{ padding: 16px 14px 40px; }}
        .hero {{ padding: 24px 20px; }}
      }}
    </style>
  </head>
  <body>
    <main class="shell">
      <section class="hero">
        <p class="eyebrow">LandCheck Green public sponsor route</p>
        <h1>Public Sponsor Terms and Checkout Conditions</h1>
        <p class="meta">Version {terms_version} &middot; Effective {effective_date}. These terms apply when a sponsor account uses the public LandCheck Green route to reserve trees, pay online, and receive verified map, photo, certificate, and maintenance updates.</p>
      </section>
      <div class="stack">
        <section class="panel">
          <h2>1. What this service covers</h2>
          <p>LandCheck Green provides a public sponsorship route where individuals and organizations can support approved tree projects, complete secure checkout, and later view verified field evidence linked to the sponsored trees. Tree allocation happens only inside projects that an administrator has opened for public sponsorship.</p>
        </section>
        <section class="panel">
          <h2>2. Checkout, pricing, and tree allocation</h2>
          <ul>
            <li>Prices shown at checkout are project-specific and charged per tree or per reserved sponsorship unit.</li>
            <li>A sponsorship becomes active only after payment is confirmed by the payment provider or by LandCheck review where manual verification is used.</li>
            <li>Tree assignment may happen after payment confirmation. Until a verified tree is linked, the order remains a reserved sponsorship commitment for that project.</li>
            <li>Public sponsor projects may have limited capacity. LandCheck may stop or limit checkout when a project reaches its published capacity.</li>
          </ul>
        </section>
        <section class="panel">
          <h2>3. Evidence, certificates, and impact records</h2>
          <ul>
            <li>Map points, photos, maintenance history, and certificates depend on reviewed field submissions and may update over time as teams work on the project.</li>
            <li>Photos and coordinates are operational evidence. They are not a land title document, environmental credit instrument, or guarantee of future survival beyond the evidence shown.</li>
            <li>Carbon and environmental impact values are indicative project-support metrics generated from LandCheck models and verified field records. They should not be treated as regulated carbon credits unless separately stated in writing.</li>
          </ul>
        </section>
        <section class="panel">
          <h2>4. Refunds, substitutions, and project changes</h2>
          <ul>
            <li>If a project cannot allocate all paid sponsorship units, LandCheck may re-link the units to eligible replacement trees within the same approved project context or offer an administrative remedy consistent with the payment status and project record.</li>
            <li>Refund handling depends on whether payment has cleared, whether trees have already been allocated, and whether verified field work has started. The team may review each case before a final decision is issued.</li>
            <li>LandCheck may correct obvious pricing, allocation, duplicate-order, or payment reconciliation errors where necessary for accounting accuracy.</li>
          </ul>
        </section>
        <section class="panel">
          <h2>5. Privacy, payments, and Nigerian compliance</h2>
          <ul>
            <li>LandCheck processes sponsor account and checkout information in line with its privacy policy and operational privacy controls. Review the privacy policy here: <a href="{privacy_url}" target="_blank" rel="noopener noreferrer">{privacy_url}</a>.</li>
            <li>Public sponsor checkout records may include account details, project choices, payment status, IP address, and field evidence linked to funded trees for service delivery, audit, fraud prevention, and support handling.</li>
            <li>These terms are designed to align with LandCheck operational data handling under the Nigeria Data Protection Act 2023 and fair information handling expectations for platform users.</li>
            <li>Consumer-facing disclosures, price display, and complaint handling are intended to remain consistent with basic transparency and redress expectations under Nigeria’s consumer protection framework.</li>
            <li>Online payments are processed through integrated third-party payment providers. LandCheck does not ask sponsors to bypass the secure payment flow for card payments inside the public route.</li>
          </ul>
        </section>
        <section class="panel">
          <h2>6. Sponsor responsibilities</h2>
          <ul>
            <li>Use accurate identity and contact details when creating a sponsor account or placing an order.</li>
            <li>Do not upload unlawful, abusive, fraudulent, or misleading dedication text or payment information.</li>
            <li>Keep your password private and notify LandCheck promptly if you suspect unauthorized use of your sponsor account.</li>
          </ul>
        </section>
        <section class="panel">
          <h2>7. Governing law and support</h2>
          <p>These sponsor-route terms are governed by the laws of the Federal Republic of Nigeria. Questions, complaints, or support requests can be sent to <a href="mailto:{support_email}">{support_email}</a>. LandCheck may update these terms from time to time, and the version accepted at checkout is recorded with the order.</p>
        </section>
        <section class="panel">
          <h2>Quick reference</h2>
          <div class="meta-grid">
            <article class="meta-card">
              <span class="eyebrow" style="color:#53705f;">Terms version</span>
              <strong>{terms_version}</strong>
            </article>
            <article class="meta-card">
              <span class="eyebrow" style="color:#53705f;">Effective date</span>
              <strong>{effective_date}</strong>
            </article>
            <article class="meta-card">
              <span class="eyebrow" style="color:#53705f;">Privacy policy</span>
              <strong><a href="{privacy_url}" target="_blank" rel="noopener noreferrer">Open privacy policy</a></strong>
            </article>
          </div>
        </section>
      </div>
    </main>
  </body>
</html>"""


def _render_sponsor_public_reset_password_html(token: str) -> str:
    safe_token = html.escape(str(token or "").strip(), quote=True)
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Reset Sponsor Password</title>
    <style>
      body {{
        margin: 0;
        font-family: Inter, "Segoe UI", system-ui, sans-serif;
        background: linear-gradient(180deg, #f8fcf8 0%, #e9f6eb 100%);
        color: #173624;
      }}
      .shell {{
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 22px;
      }}
      .card {{
        width: min(100%, 440px);
        background: rgba(255,255,255,0.97);
        border: 1px solid rgba(15,111,57,0.10);
        border-radius: 24px;
        box-shadow: 0 20px 48px rgba(10, 52, 28, 0.12);
        overflow: hidden;
      }}
      .hero {{
        padding: 24px 24px 20px;
        background: linear-gradient(145deg,#0c5f2e 0%,#1b8245 100%);
        color: #fff;
      }}
      .hero h1, .hero p {{ margin: 0; }}
      .hero h1 {{
        margin-top: 10px;
        font-size: 1.9rem;
        line-height: 1.1;
      }}
      .hero p {{
        margin-top: 8px;
        color: rgba(255,255,255,0.86);
        line-height: 1.65;
      }}
      .body {{ padding: 22px 24px 26px; }}
      label {{
        display: block;
        margin-bottom: 8px;
        font-size: 0.92rem;
        font-weight: 700;
        color: #1a3d28;
      }}
      input {{
        width: 100%;
        min-height: 54px;
        padding: 0 16px;
        border-radius: 16px;
        border: 1px solid rgba(15,111,57,0.16);
        background: #fbfefb;
        font: inherit;
        color: #173624;
        margin-bottom: 14px;
      }}
      button {{
        width: 100%;
        min-height: 54px;
        border: 0;
        border-radius: 16px;
        background: #0f6f39;
        color: #fff;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }}
      button:disabled {{ opacity: 0.6; cursor: wait; }}
      .status {{
        margin-top: 14px;
        padding: 14px 16px;
        border-radius: 14px;
        background: #f4faf5;
        border: 1px solid rgba(15,111,57,0.10);
        color: #486652;
        line-height: 1.65;
        display: none;
      }}
      .status.error {{
        background: #fff5f5;
        border-color: rgba(185, 28, 28, 0.12);
        color: #9f1d1d;
      }}
    </style>
  </head>
  <body>
    <main class="shell">
      <section class="card">
        <div class="hero">
          <div style="font-size:12px;font-weight:800;letter-spacing:0.14em;text-transform:uppercase;color:#d8f7df;">LandCheck Green sponsor route</div>
          <h1>Reset your password</h1>
          <p>Choose a new password for your sponsor account. After saving it, you can sign back in from the app.</p>
        </div>
        <div class="body">
          <form id="reset-form">
            <input id="token" type="hidden" value="{safe_token}" />
            <label for="password">New password</label>
            <input id="password" type="password" autocomplete="new-password" minlength="8" placeholder="Enter new password" required />
            <label for="confirm-password">Confirm new password</label>
            <input id="confirm-password" type="password" autocomplete="new-password" minlength="8" placeholder="Repeat new password" required />
            <button id="submit-btn" type="submit">Save new password</button>
            <div id="status" class="status"></div>
          </form>
        </div>
      </section>
    </main>
    <script>
      const form = document.getElementById('reset-form');
      const statusEl = document.getElementById('status');
      const submitBtn = document.getElementById('submit-btn');
      form.addEventListener('submit', async (event) => {{
        event.preventDefault();
        const token = document.getElementById('token').value.trim();
        const password = document.getElementById('password').value;
        const confirmPassword = document.getElementById('confirm-password').value;
        statusEl.style.display = 'none';
        statusEl.className = 'status';
        if (!token) {{
          statusEl.textContent = 'This reset link is invalid or missing a token.';
          statusEl.classList.add('error');
          statusEl.style.display = 'block';
          return;
        }}
        if (password.length < 8) {{
          statusEl.textContent = 'Password must be at least 8 characters.';
          statusEl.classList.add('error');
          statusEl.style.display = 'block';
          return;
        }}
        if (password !== confirmPassword) {{
          statusEl.textContent = 'The two password entries do not match.';
          statusEl.classList.add('error');
          statusEl.style.display = 'block';
          return;
        }}
        submitBtn.disabled = true;
        submitBtn.textContent = 'Saving...';
        try {{
          const response = await fetch('/green/sponsor-auth/reset-password', {{
            method: 'POST',
            headers: {{ 'Content-Type': 'application/json' }},
            body: JSON.stringify({{ token, new_password: password }}),
          }});
          const payload = await response.json().catch(() => ({{}}));
          if (!response.ok) {{
            throw new Error(payload.detail || 'Could not reset the password.');
          }}
          statusEl.textContent = payload.message || 'Password updated successfully. You can return to the app and sign in now.';
          statusEl.style.display = 'block';
          form.reset();
        }} catch (error) {{
          statusEl.textContent = error.message || 'Could not reset the password.';
          statusEl.classList.add('error');
          statusEl.style.display = 'block';
        }} finally {{
          submitBtn.disabled = false;
          submitBtn.textContent = 'Save new password';
        }}
      }});
    </script>
  </body>
</html>"""


@router.get("/sponsor/trees/{unit_id}")
def get_sponsor_tree_detail(unit_id: int, request: Request, sponsor_id: int = Query(...), db: Session = Depends(get_db)):
    row = db.execute(
        text(
            """
            SELECT
                u.id AS unit_id, u.unit_uid, u.sponsorship_status, u.linked_at,
                u.dedication_type, u.dedication_name, u.dedication_message,
                o.id AS order_id, o.order_uid, o.payment_status, o.order_status, o.created_at AS order_created_at,
                p.id AS project_id, p.name AS project_name, p.location_text, p.organization_id,
                t.id AS tree_id, t.project_tree_no, t.species, t.status AS tree_status, t.notes AS tree_notes,
                t.planting_date, t.photo_url, t.photo_urls, t.tree_height_m, t.tree_age_months, t.inventory_tree_count,
                t.count_in_carbon_scope, t.created_by, t.created_at AS tree_created_at,
                ST_X(t.geom) AS lng, ST_Y(t.geom) AS lat
            FROM green_sponsorship_units u
            JOIN green_sponsorship_orders o ON o.id = u.order_id
            JOIN tree_projects p ON p.id = u.project_id
            LEFT JOIN trees t ON t.id = u.tree_id
            WHERE u.id = :unit_id
              AND u.sponsor_account_id = :sponsor_id
            LIMIT 1
            """
        ),
        {"unit_id": int(unit_id), "sponsor_id": int(sponsor_id)},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsored tree not found")
    return _hydrate_sponsor_tree_story_item(dict(row), db, request=request)


@router.get("/sponsor/trees/{unit_id}/certificate/pdf")
def export_sponsor_tree_certificate(
    unit_id: int,
    request: Request,
    sponsor_id: int = Query(...),
    db: Session = Depends(get_db),
):
    
    row = db.execute(
        text(
            """
            SELECT
                sa.full_name AS sponsor_name,
                sa.organization_name AS sponsor_organization_name,
                u.id AS unit_id, u.unit_uid, u.dedication_type, u.dedication_name, u.dedication_message,
                p.id AS project_id, p.name AS project_name, p.location_text,
                t.id AS tree_id, t.project_tree_no, t.species, t.status, t.planting_date,
                t.photo_url, t.photo_urls, t.tree_height_m, t.tree_age_months, t.inventory_tree_count,
                t.count_in_carbon_scope, t.created_at AS tree_created_at
            FROM green_sponsorship_units u
            JOIN green_sponsor_accounts sa ON sa.id = u.sponsor_account_id
            JOIN tree_projects p ON p.id = u.project_id
            JOIN trees t ON t.id = u.tree_id
            WHERE u.id = :unit_id
              AND u.sponsor_account_id = :sponsor_id
            LIMIT 1
            """
        ),
        {"unit_id": int(unit_id), "sponsor_id": int(sponsor_id)},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Sponsored tree certificate not found")
    item = _hydrate_sponsor_tree_story_item(dict(row), db, request=request)
    carbon = _build_tree_carbon_summary(item)
    achievements = _calculate_sponsor_achievement(db, int(sponsor_id))
    pdf_bytes = render_green_sponsor_certificate_pdf(
        item,
        carbon,
        verification_url=item.get("public_story_url"),
        level_name=achievements.get("level")
    )
    db.execute(
        text("UPDATE green_sponsorship_units SET last_certificate_at = NOW(), updated_at = NOW() WHERE id = :unit_id"),
        {"unit_id": int(unit_id)},
    )
    db.commit()
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename=\"sponsor_tree_certificate_{int(unit_id)}.pdf\"',
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
            "Expires": "0",
        },
    )


@router.get("/sponsorship-units/{unit_id}/qr-tag/pdf")
def export_sponsorship_unit_qr_tag_pdf(
    unit_id: int,
    request: Request,
    user_id: int = Query(...),
    organization_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
):
    _ensure_sponsor_qr_unit_columns(db)
    unit_project = db.execute(
        text(
            """
            SELECT id, project_id
            FROM green_sponsorship_units
            WHERE id = :unit_id
            LIMIT 1
            """
        ),
        {"unit_id": int(unit_id)},
    ).mappings().first()
    if not unit_project:
        raise HTTPException(status_code=404, detail="Sponsor QR tag not found")

    project_row, user_row, _selected_agent_ids = _ensure_public_sponsor_agent_project_access(
        db,
        project_id=int(unit_project["project_id"]),
        user_id=int(user_id),
        organization_id=int(organization_id) if organization_id is not None else None,
    )
    _try_assign_available_sponsor_units_for_project(
        db,
        project_id=int(project_row["id"]),
        context="export_sponsorship_unit_qr_tag_pdf",
    )
    _try_assign_available_sponsor_units_for_agent(
        db,
        project_id=int(project_row["id"]),
        user_id=int(user_id),
        organization_id=int(organization_id) if organization_id is not None else None,
        context="export_sponsorship_unit_qr_tag_pdf",
    )

    aliases = _build_sponsor_agent_aliases(user_row)
    row = db.execute(
        text(
            """
            SELECT
                u.id AS unit_id,
                u.unit_uid,
                u.project_id,
                u.tree_id,
                u.tree_project_no,
                u.sponsorship_status,
                u.dedication_type,
                u.dedication_name,
                u.dedication_message,
                u.qr_download_count,
                sa.full_name AS sponsor_name,
                sa.organization_name AS sponsor_organization_name,
                p.name AS project_name,
                p.location_text,
                t.id AS linked_tree_id,
                t.species,
                t.status AS tree_status,
                t.planting_date,
                t.photo_url,
                t.photo_urls,
                t.tree_height_m,
                t.tree_age_months,
                t.inventory_tree_count,
                t.count_in_carbon_scope,
                t.created_at AS tree_created_at
            FROM green_sponsorship_units u
            JOIN green_sponsor_accounts sa ON sa.id = u.sponsor_account_id
            JOIN tree_projects p ON p.id = u.project_id
            LEFT JOIN trees t ON t.id = u.tree_id
            WHERE u.id = :unit_id
              AND u.project_id = :project_id
              AND LOWER(COALESCE(u.sponsorship_status, '')) IN ('awaiting_tree', 'linked', 'active', 'replaced')
              AND (
                    u.assigned_user_id = :user_id
                 OR LOWER(REGEXP_REPLACE(TRIM(COALESCE(u.assigned_assignee_name, '')), '\\s+', ' ', 'g')) IN :aliases
              )
            LIMIT 1
            """
        ).bindparams(bindparam("aliases", expanding=True)),
        {
            "unit_id": int(unit_id),
            "project_id": int(project_row["id"]),
            "user_id": int(user_id),
            "aliases": aliases or [""],
        },
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="No sponsor QR tag is currently reserved for this agent")

    item = dict(row)
    if item.get("linked_tree_id") and not item.get("tree_id"):
        item["tree_id"] = item.get("linked_tree_id")
    if item.get("tree_id"):
        carbon = _build_tree_carbon_summary(item)
        item["annual_co2_kg"] = carbon.get("annual_co2_kg", 21.0)
    else:
        item["annual_co2_kg"] = 21.0
    verification_url = _build_sponsor_public_story_url(item.get("unit_uid"), request)
    if not verification_url:
        base_url = _build_public_api_base_url(request)
        verification_url = f"{base_url}/green/sponsor/public/trees/{quote(str(item.get('unit_uid') or unit_id))}"

    try:
        pdf_bytes = render_green_tree_qr_tag_pdf(item, verification_url)
    except Exception:
        logger.exception("QR tag PDF render failed for unit_id=%s", int(unit_id))
        raise HTTPException(status_code=500, detail="Failed to generate QR tag PDF — please retry or contact support.")
    downloader_name = str(user_row.get("full_name") or user_row.get("work_username") or "").strip() or None
    _mark_sponsor_unit_qr_download(
        db,
        unit_id=int(item["unit_id"]),
        downloader_name=downloader_name,
    )
    db.commit()
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename=\"sponsor_qr_tag_{str(item.get("unit_uid") or unit_id)}.pdf\"',
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
            "Expires": "0",
        },
    )


@router.get("/trees/{tree_id}/qr-tag/pdf")
def export_tree_qr_tag_pdf(
    tree_id: int,
    request: Request,
    user_id: int | None = Query(default=None),
    organization_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
):
    from app.utils.green_pdf import render_green_tree_qr_tag_pdf
    _ensure_sponsor_qr_unit_columns(db)
    
    # Load tree and project info, and optional sponsor info via LEFT JOINs
    tree = db.execute(
        text(
            """
            SELECT
                t.id AS tree_id, t.project_tree_no, t.species, t.status, t.planting_date,
                t.photo_url, t.photo_urls, t.tree_height_m, t.tree_age_months, t.inventory_tree_count,
                t.count_in_carbon_scope, t.created_by, t.created_at AS tree_created_at,
                p.id AS project_id, p.name AS project_name, p.location_text,
                sa.full_name AS sponsor_name, sa.organization_name AS sponsor_organization_name,
                u.id AS unit_id, u.unit_uid, u.assigned_user_id, u.assigned_assignee_name
            FROM trees t
            JOIN tree_projects p ON p.id = t.project_id
            LEFT JOIN green_sponsorship_units u ON u.tree_id = t.id AND LOWER(COALESCE(u.sponsorship_status, '')) IN ('linked', 'active', 'replaced')
            LEFT JOIN green_sponsor_accounts sa ON sa.id = u.sponsor_account_id
            WHERE t.id = :tree_id
            LIMIT 1
            """
        ),
        {"tree_id": int(tree_id)},
    ).mappings().first()
    
    if not tree:
        raise HTTPException(status_code=404, detail="Tree not found")
        
    tree_dict = dict(tree)
    downloader_user = None
    if tree_dict.get("unit_id") and user_id is not None and int(user_id) > 0:
        _project_row, downloader_user, _selected_agent_ids = _ensure_public_sponsor_agent_project_access(
            db,
            project_id=int(tree_dict.get("project_id") or 0),
            user_id=int(user_id),
            organization_id=int(organization_id) if organization_id is not None else None,
        )
        agent_aliases = set(_build_sponsor_agent_aliases(downloader_user))
        assigned_user_id = int(tree_dict.get("assigned_user_id") or 0)
        assigned_assignee_name = str(tree_dict.get("assigned_assignee_name") or "").strip().lower()
        tree_creator_name = str(tree_dict.get("created_by") or "").strip().lower()
        assignment_confirmed = (
            (assigned_user_id > 0 and assigned_user_id == int(user_id))
            or (assigned_assignee_name and assigned_assignee_name in agent_aliases)
            or (
                assigned_user_id <= 0
                and not assigned_assignee_name
                and tree_creator_name
                and tree_creator_name in agent_aliases
            )
        )
        if not assignment_confirmed:
            raise HTTPException(status_code=403, detail="This sponsor QR tag is not assigned to this agent")
    
    # Calculate carbon impact
    carbon = _build_tree_carbon_summary(tree_dict)
    tree_dict["annual_co2_kg"] = carbon.get("annual_co2_kg", 21.0)
    
    # Determine the public story URL for the QR code
    unit_uid = tree_dict.get("unit_uid")
    if unit_uid:
        verification_url = _build_sponsor_public_story_url(unit_uid, request)
    else:
        # If not sponsored, QR links to the public tree story using tree_id!
        base_url = _build_public_api_base_url(request)
        verification_url = f"{base_url}/green/sponsor/public/trees/{tree_id}"
        
    pdf_bytes = render_green_tree_qr_tag_pdf(tree_dict, verification_url)
    downloader_name = None
    if user_id is not None and int(user_id) > 0:
        if downloader_user is None:
            try:
                downloader_user = _get_green_user_for_sponsor_agent(
                    db,
                    user_id=int(user_id),
                    organization_id=int(organization_id) if organization_id is not None else None,
                )
            except Exception:
                downloader_user = None
        downloader_name = (
            str((downloader_user or {}).get("full_name") or (downloader_user or {}).get("work_username") or "").strip() or None
        )
    if tree_dict.get("unit_id"):
        _mark_sponsor_unit_qr_download(
            db,
            unit_id=int(tree_dict["unit_id"]),
            downloader_name=downloader_name,
        )
    
    db.execute(
        text("INSERT INTO green_tree_qr_prints (tree_id, printed_at) VALUES (:tree_id, NOW())"),
        {"tree_id": int(tree_id)},
    )
    db.commit()
    
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename=\"tree_qr_tag_{int(tree_id)}.pdf\"',
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
            "Expires": "0",
        },
    )


