@router.post("/agent-payouts/requests")
def create_sponsor_agent_payout_request(payload: SponsorAgentPayoutRequestPayload, db: Session = Depends(get_db)):
    dashboard = _build_sponsor_agent_dashboard(
        db,
        user_id=int(payload.user_id),
        organization_id=int(payload.organization_id) if payload.organization_id is not None else None,
        project_id=int(payload.project_id) if payload.project_id is not None else None,
    )
    if not dashboard.get("eligible"):
        raise HTTPException(status_code=403, detail="This user is not selected as a public sponsor agent")
    bank_account_row = _load_sponsor_agent_bank_account(db, user_id=int(dashboard["user"]["id"]))
    bank_account = _serialize_sponsor_agent_bank_account(bank_account_row)
    if not bank_account or not bank_account.get("verified"):
        raise HTTPException(status_code=409, detail="Verify and save your bank account before requesting payout")
    available_rows = [
        row for row in dashboard.get("earnings") or [] if row.get("payout_status") == "available" and float(row.get("amount") or 0) > 0
    ]
    available_amount = round(sum(float(row.get("amount") or 0) for row in available_rows), 2)
    if available_amount < float(SPONSOR_AGENT_MIN_PAYOUT_NAIRA):
        raise HTTPException(
            status_code=409,
            detail=f"Minimum payout request is {SPONSOR_AGENT_MIN_PAYOUT_NAIRA} {SPONSOR_AGENT_ACCOUNT_CURRENCY}",
        )
    if not available_rows:
        raise HTTPException(status_code=409, detail="No sponsor-funded earnings are currently available for payout")
    request_uid = _generate_prefixed_uid("PAY")
    project_ids = sorted({int(row.get("project_id") or 0) for row in available_rows if int(row.get("project_id") or 0) > 0})
    row = db.execute(
        text(
            """
            INSERT INTO green_sponsor_agent_payout_requests (
                request_uid, user_id, organization_id, currency, amount_total, payout_minimum, status,
                bank_code, bank_name, account_number, account_name,
                earning_keys, earning_rows, project_ids
            )
            VALUES (
                :request_uid, :user_id, :organization_id, :currency, :amount_total, :payout_minimum, 'requested',
                :bank_code, :bank_name, :account_number, :account_name,
                CAST(:earning_keys AS JSONB), CAST(:earning_rows AS JSONB), CAST(:project_ids AS JSONB)
            )
            RETURNING *
            """
        ),
        {
            "request_uid": request_uid,
            "user_id": int(dashboard["user"]["id"]),
            "organization_id": int(dashboard["user"]["organization_id"] or 0) or None,
            "currency": SPONSOR_AGENT_ACCOUNT_CURRENCY,
            "amount_total": available_amount,
            "payout_minimum": SPONSOR_AGENT_MIN_PAYOUT_NAIRA,
            "bank_code": bank_account_row.get("bank_code") if bank_account_row else None,
            "bank_name": bank_account_row.get("bank_name") if bank_account_row else None,
            "account_number": _normalize_account_number((bank_account_row or {}).get("account_number")),
            "account_name": (bank_account_row or {}).get("account_name"),
            "earning_keys": _safe_json(
                [str(item.get("earning_key") or "").strip() for item in available_rows if str(item.get("earning_key") or "").strip()]
            ),
            "earning_rows": _safe_json(available_rows),
            "project_ids": _safe_json(project_ids),
        },
    ).mappings().first()
    db.commit()
    return {"ok": True, "request": _serialize_sponsor_agent_payout_request(dict(row) if row else None)}


@router.get("/agent/sponsor-qr-tags")
def list_agent_sponsor_qr_tags(
    project_id: int = Query(...),
    user_id: int = Query(...),
    organization_id: int | None = Query(default=None),
    sync: bool = Query(default=True),
    db: Session = Depends(get_db),
):
    _ensure_sponsor_qr_unit_columns(db)
    project_row, user_row, _selected_agent_ids = _ensure_public_sponsor_agent_project_access(
        db,
        project_id=int(project_id),
        user_id=int(user_id),
        organization_id=int(organization_id) if organization_id is not None else None,
    )
    _promote_project_paid_units_to_awaiting_tree(db, int(project_row["id"]))
    if sync:
        _try_assign_available_sponsor_units_for_project(
            db,
            project_id=int(project_row["id"]),
            context="list_agent_sponsor_qr_tags",
        )
        _try_assign_available_sponsor_units_for_agent(
            db,
            project_id=int(project_row["id"]),
            user_id=int(user_id),
            organization_id=int(organization_id) if organization_id is not None else None,
            context="list_agent_sponsor_qr_tags",
        )
    aliases = _build_sponsor_agent_aliases(user_row)
    rows = db.execute(
        text(
            """
            SELECT
                u.id AS unit_id,
                u.unit_uid,
                u.project_id,
                u.tree_id,
                u.tree_project_no,
                u.sponsorship_status,
                u.dedication_type,
                u.dedication_name,
                u.dedication_message,
                u.assigned_at,
                u.qr_download_count,
                u.first_qr_downloaded_at,
                u.last_qr_downloaded_at,
                u.last_qr_downloaded_by,
                sa.id AS sponsor_account_id,
                sa.full_name AS sponsor_name,
                sa.organization_name AS sponsor_organization_name,
                p.name AS project_name,
                p.location_text,
                t.species,
                t.status AS tree_status
            FROM green_sponsorship_units u
            JOIN green_sponsor_accounts sa ON sa.id = u.sponsor_account_id
            JOIN tree_projects p ON p.id = u.project_id
            LEFT JOIN trees t ON t.id = u.tree_id
            WHERE u.project_id = :project_id
              AND u.tree_id IS NULL
              AND LOWER(COALESCE(u.sponsorship_status, '')) = 'awaiting_tree'
              AND (
                    u.assigned_user_id = :user_id
                 OR LOWER(REGEXP_REPLACE(TRIM(COALESCE(u.assigned_assignee_name, '')), '\\s+', ' ', 'g')) IN :aliases
              )
            ORDER BY COALESCE(u.assigned_at, u.created_at) ASC, u.id ASC
            """
        ).bindparams(bindparam("aliases", expanding=True)),
        {
            "project_id": int(project_id),
            "user_id": int(user_id),
            "aliases": aliases or [""],
        },
    ).mappings().all()
    payload: list[dict] = []
    for row in rows:
        item = dict(row)
        item["download_status"] = "downloaded" if int(item.get("qr_download_count") or 0) > 0 else "pending_download"
        payload.append(item)
    return payload


@router.get("/admin/sponsors")
def list_admin_sponsors(db: Session = Depends(get_db)):
    from datetime import datetime
    start_of_month = datetime.utcnow().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    rows = db.execute(
        text(
            """
            SELECT
                sa.id, sa.sponsor_uid, sa.account_type, sa.full_name, sa.organization_name, sa.email, sa.phone,
                sa.is_active, sa.created_at, sa.entity_category, sa.leaderboard_visibility,
                sa.green_points, sa.lifetime_points, sa.referral_code, sa.referred_by_id,
                COALESCE(order_stats.orders_count, 0) AS orders_count,
                COALESCE(order_stats.amount_total, 0) AS amount_total,
                COALESCE(order_stats.verified_orders_count, 0) AS verified_orders_count,
                COALESCE(order_stats.pending_orders_count, 0) AS pending_orders_count,
                COALESCE(order_stats.issue_orders_count, 0) AS issue_orders_count,
                COALESCE(order_stats.all_time_trees, 0) AS all_time_trees,
                COALESCE(order_stats.monthly_trees, 0) AS monthly_trees,
                COALESCE(unit_stats.linked_trees, 0) AS linked_trees,
                COALESCE(unit_stats.awaiting_tree_units, 0) AS awaiting_tree_units
            FROM green_sponsor_accounts sa
            LEFT JOIN (
                SELECT
                    sponsor_account_id,
                    COUNT(*) AS orders_count,
                    COALESCE(SUM(amount_total), 0) AS amount_total,
                    COUNT(*) FILTER (WHERE LOWER(COALESCE(payment_status, '')) = 'verified') AS verified_orders_count,
                    COUNT(*) FILTER (
                        WHERE LOWER(COALESCE(payment_status, '')) IN ('pending', 'proof_submitted')
                    ) AS pending_orders_count,
                    COUNT(*) FILTER (
                        WHERE LOWER(COALESCE(payment_status, '')) IN ('rejected', 'refunded')
                    ) AS issue_orders_count,
                    COALESCE(SUM(quantity) FILTER (
                        WHERE LOWER(payment_status) IN ('verified', 'paid')
                        OR LOWER(order_status) IN ('paid', 'allocated', 'completed')
                    ), 0) AS all_time_trees,
                    COALESCE(SUM(quantity) FILTER (
                        WHERE created_at >= :start_of_month AND (
                            LOWER(payment_status) IN ('verified', 'paid')
                            OR LOWER(order_status) IN ('paid', 'allocated', 'completed')
                        )
                    ), 0) AS monthly_trees
                FROM green_sponsorship_orders
                GROUP BY sponsor_account_id
            ) order_stats ON order_stats.sponsor_account_id = sa.id
            LEFT JOIN (
                SELECT
                    sponsor_account_id,
                    COUNT(*) FILTER (WHERE tree_id IS NOT NULL) AS linked_trees,
                    COUNT(*) FILTER (
                        WHERE LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_tree'
                    ) AS awaiting_tree_units
                FROM green_sponsorship_units
                GROUP BY sponsor_account_id
            ) unit_stats ON unit_stats.sponsor_account_id = sa.id
            ORDER BY sa.created_at DESC, sa.id DESC
            """
        ),
        {"start_of_month": start_of_month},
    ).mappings().all()
    
    payload = []
    for row in rows:
        all_time = int(row.get("all_time_trees") or 0)
        level = "Seed Supporter"
        if all_time >= 500:
            level = "Earth Guardian"
        elif all_time >= 100:
            level = "Climate Champion"
        elif all_time >= 50:
            level = "Forest Builder"
        elif all_time >= 10:
            level = "Green Supporter"
        elif all_time >= 1:
            level = "Seed Supporter"
        else:
            level = "Climate Contributor"
            
        rules = _compute_active_referrer_rules(db, int(row["id"]))
        item = _serialize_sponsor_account(dict(row)) | {
            "orders_count": int(row.get("orders_count") or 0),
            "amount_total": round(float(row.get("amount_total") or 0), 2),
            "linked_trees": int(row.get("linked_trees") or 0),
            "verified_orders_count": int(row.get("verified_orders_count") or 0),
            "pending_orders_count": int(row.get("pending_orders_count") or 0),
            "issue_orders_count": int(row.get("issue_orders_count") or 0),
            "awaiting_tree_units": int(row.get("awaiting_tree_units") or 0),
            "all_time_trees": all_time,
            "monthly_trees": int(row.get("monthly_trees") or 0),
            "achievement_level": level,
            "created_at": row.get("created_at"),
            "personal_trees_sponsored": rules.get("personal_trees_sponsored", 0),
            "total_referred_users": rules.get("total_referred_users", 0),
            "converted_referred_users": rules.get("converted_referred_users", 0),
            "referral_rules_met": rules.get("referral_rules_met", False),
            "conversion_rate_met": rules.get("conversion_rate_met", False),
            "referral_conversion_rate": rules.get("referral_conversion_rate", 0),
        }
        payload.append(item)
    return payload


