@router.get("/trees/{tree_id}/timeline")
def tree_timeline(tree_id: int, db: Session = Depends(get_db)):
    tree = db.execute(text("""
        SELECT
            t.id,
            t.species,
            t.planting_date,
            t.status,
            t.notes,
            t.photo_url,
            t.photo_urls,
            t.created_by,
            t.created_at,
            t.tree_origin,
            t.custodian_id,
            c.name AS custodian_name,
            t.custody_started_at,
            t.attribution_scope,
              t.count_in_planting_kpis,
              t.count_in_carbon_scope,
              t.source_project_id,
              t.tree_height_m,
              t.tree_age_months,
              COALESCE(t.inventory_tree_count, 1) AS inventory_tree_count,
              t.existing_area_geojson,
              t.existing_area_sqm
          FROM trees t
        LEFT JOIN green_custodians c ON c.id = t.custodian_id
        WHERE t.id = :tree_id
    """), {"tree_id": tree_id}).mappings().first()
    task_rows = list_tree_tasks(tree_id, db)
    visits = db.execute(text("""
        SELECT visit_date, status, notes, photo_url, created_by, created_at
        FROM tree_visits
        WHERE tree_id = :tree_id
        ORDER BY visit_date DESC
    """), {"tree_id": tree_id}).mappings().all()

    tree_item = dict(tree) if tree else None
    if tree_item:
        tree_photo_urls = _normalize_photo_urls(tree_item.get("photo_urls"))
        tree_photo_url = str(tree_item.get("photo_url") or "").strip()
        if tree_photo_url and tree_photo_url not in tree_photo_urls:
            tree_photo_urls.append(tree_photo_url)
        tree_item["photo_urls"] = tree_photo_urls

    tasks: list[dict] = []
    for item in task_rows:
        row = dict(item)
        photo_urls = _normalize_photo_urls(row.get("photo_urls"))
        photo_url = str(row.get("photo_url") or "").strip()
        if photo_url and photo_url not in photo_urls:
            photo_urls.append(photo_url)
        row["photo_urls"] = photo_urls
        tasks.append(row)

    return {
        "tree": tree_item,
        "tasks": tasks,
        "visits": [dict(v) for v in visits],
    }


@router.get("/projects/{project_id}/task-stats")
def task_stats(project_id: int, db: Session = Depends(get_db)):
    rows = db.execute(text("""
        SELECT
            COUNT(*) AS total,
            SUM(
                CASE
                    WHEN LOWER(COALESCE(status, '')) IN ('done', 'completed', 'closed')
                         AND LOWER(COALESCE(review_state, 'none')) IN ('approved', 'none')
                    THEN 1 ELSE 0
                END
            ) AS done,
            SUM(
                CASE
                    WHEN NOT (
                        LOWER(COALESCE(status, '')) IN ('done', 'completed', 'closed')
                        AND LOWER(COALESCE(review_state, 'none')) IN ('approved', 'none')
                    ) AND LOWER(COALESCE(status, 'pending')) <> 'overdue'
                    THEN 1 ELSE 0
                END
            ) AS pending,
            SUM(
                CASE
                    WHEN LOWER(COALESCE(status, 'pending')) = 'overdue'
                    THEN 1 ELSE 0
                END
            ) AS overdue
        FROM tree_tasks
        WHERE tree_id IN (SELECT id FROM trees WHERE project_id = :project_id)
    """), {"project_id": project_id}).mappings().first()
    return dict(rows)


@router.post("/work-orders")
def create_work_order(
    db: Session = Depends(get_db),
    project_id: int = Body(...),
    assignee_name: str = Body(...),
    work_type: str = Body(...),
    target_trees: int = Body(default=0),
    species_allocations: list[dict] | None = Body(default=None),
    maintenance_schedule: str = Body(default=""),
    auto_assign_first_cycle_maintenance: bool = Body(default=False),
    due_date: str | None = Body(default=None),
    area_enabled: bool = Body(default=False),
    area_label: str | None = Body(default=None),
    area_geojson: dict | str | None = Body(default=None),
    allow_existing_tree_area_reuse: bool = Body(default=False),
):
    work_order_assignee_user_available = _ensure_work_order_assignee_columns(db)
    if work_type not in {"planting", "maintenance"}:
        raise HTTPException(status_code=400, detail="Invalid work_type")
    assignee_clean = (assignee_name or "").strip()
    if not assignee_clean:
        raise HTTPException(status_code=400, detail="Assignee name required")
    project_access_row = db.execute(
        text(
            """
            SELECT id, organization_id, access_model, public_sponsor_enabled, public_sponsor_agent_user_ids
            FROM tree_projects
            WHERE id = :project_id
            LIMIT 1
            """
        ),
        {"project_id": int(project_id)},
    ).mappings().first()
    if not project_access_row:
        raise HTTPException(status_code=404, detail="Project not found")
    sponsor_agent_user_id: int | None = None
    project_organization_id = int(project_access_row.get("organization_id") or 0) or None
    public_sponsor_project = _is_public_sponsorship_project(dict(project_access_row))
    if area_enabled and work_type != "planting":
        raise HTTPException(status_code=400, detail="Area assignment is only available for planting orders")
    normalized_species_allocations = _normalize_species_allocations(species_allocations)
    if work_type != "planting" and normalized_species_allocations:
        raise HTTPException(status_code=400, detail="Species-based allocation is only available for planting orders")
    if work_type == "planting" and normalized_species_allocations:
        target_trees = int(sum(int(item.get("count") or 0) for item in normalized_species_allocations))
    if work_type == "planting" and int(target_trees or 0) <= 0:
        raise HTTPException(status_code=400, detail="Target trees must be greater than 0 for planting orders")
    if work_type == "planting" and public_sponsor_project:
        _promote_project_paid_units_to_awaiting_tree(db, int(project_id))
        explicit_agent_ids = _normalize_positive_int_list(_json_value_or(project_access_row.get("public_sponsor_agent_user_ids"), []))
        try:
            selected_agent_ids = _collect_public_sponsor_agent_user_ids_for_project(
                db,
                project_id=int(project_id),
                organization_id=project_organization_id,
                explicit_user_ids=explicit_agent_ids,
            )
        except Exception:
            selected_agent_ids = explicit_agent_ids
        sponsor_agent_row = _match_selected_public_sponsor_user_for_assignee(
            db,
            assignee_name=assignee_clean,
            organization_id=project_organization_id,
            selected_user_ids=_normalize_positive_int_list(selected_agent_ids),
        )
        if not sponsor_agent_row:
            raise HTTPException(status_code=403, detail="Only saved public sponsor agents can receive sponsor-funded planting work")
        sponsor_agent_user_id = int(sponsor_agent_row.get("id") or 0) or None
        awaiting_tree_backlog = db.execute(
            text(
                """
                SELECT COUNT(*)
                FROM green_sponsorship_units
                WHERE project_id = :project_id
                  AND tree_id IS NULL
                  AND LOWER(COALESCE(sponsorship_status, '')) = 'awaiting_tree'
                """
            ),
            {"project_id": int(project_id)},
        ).scalar()
        awaiting_tree_backlog_value = int(awaiting_tree_backlog or 0)
        if awaiting_tree_backlog_value <= 0:
            raise HTTPException(
                status_code=409,
                detail="No paid sponsor trees are currently awaiting planting in this project. Capture payment-backed sponsor trees first, then assign planting work.",
            )
        if int(target_trees or 0) > awaiting_tree_backlog_value:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Only {awaiting_tree_backlog_value} paid sponsor tree"
                    f"{'' if awaiting_tree_backlog_value == 1 else 's'} are currently awaiting planting in this project."
                ),
            )
    auto_assign_first_cycle_maintenance = bool(auto_assign_first_cycle_maintenance) and work_type == "planting"

    normalized_area_geojson = _normalize_polygon_area_geojson(area_geojson)
    area_label_clean = (area_label or "").strip() or None
    if area_enabled and normalized_area_geojson is None:
        raise HTTPException(
            status_code=400,
            detail="Invalid planting area polygon. Draw a valid Polygon/MultiPolygon before assigning.",
        )
    if not area_enabled:
        area_label_clean = None
        normalized_area_geojson = None
        allow_existing_tree_area_reuse = False
    else:
        allow_existing_tree_area_reuse = bool(allow_existing_tree_area_reuse) and work_type == "planting"

    can_accumulate = (
        work_type == "planting"
        and not area_enabled
        and normalized_area_geojson is None
        and not normalized_species_allocations
    )
    existing_id = None
    if can_accumulate:
        if work_order_assignee_user_available:
            existing_id = db.execute(
                text(
                    """
                    SELECT id
                    FROM green_work_orders
                    WHERE project_id = :project_id
                      AND (
                            (:assignee_user_id IS NOT NULL AND COALESCE(assignee_user_id, 0) = :assignee_user_id)
                         OR (:assignee_user_id IS NULL AND LOWER(TRIM(assignee_name)) = LOWER(TRIM(:assignee_name)))
                      )
                      AND work_type = :work_type
                      AND COALESCE(area_enabled, FALSE) = FALSE
                      AND area_geojson IS NULL
                      AND COALESCE(species_allocations, '[]'::jsonb) = '[]'::jsonb
                      AND COALESCE(auto_assign_first_cycle_maintenance, FALSE) = :auto_assign_first_cycle_maintenance
                      AND LOWER(COALESCE(status, 'assigned')) NOT IN ('done', 'completed', 'closed', 'cancelled')
                    ORDER BY created_at DESC, id DESC
                    LIMIT 1
                    """
                ),
                {
                    "project_id": project_id,
                    "assignee_name": assignee_clean,
                    "assignee_user_id": int(sponsor_agent_user_id) if sponsor_agent_user_id is not None else None,
                    "work_type": work_type,
                    "auto_assign_first_cycle_maintenance": auto_assign_first_cycle_maintenance,
                },
            ).scalar()
        else:
            existing_id = db.execute(
                text(
                    """
                    SELECT id
                    FROM green_work_orders
                    WHERE project_id = :project_id
                      AND LOWER(TRIM(assignee_name)) = LOWER(TRIM(:assignee_name))
                      AND work_type = :work_type
                      AND COALESCE(area_enabled, FALSE) = FALSE
                      AND area_geojson IS NULL
                      AND COALESCE(species_allocations, '[]'::jsonb) = '[]'::jsonb
                      AND COALESCE(auto_assign_first_cycle_maintenance, FALSE) = :auto_assign_first_cycle_maintenance
                      AND LOWER(COALESCE(status, 'assigned')) NOT IN ('done', 'completed', 'closed', 'cancelled')
                    ORDER BY created_at DESC, id DESC
                    LIMIT 1
                    """
                ),
                {
                    "project_id": project_id,
                    "assignee_name": assignee_clean,
                    "work_type": work_type,
                    "auto_assign_first_cycle_maintenance": auto_assign_first_cycle_maintenance,
                },
            ).scalar()

    if existing_id and work_type == "planting":
        if work_order_assignee_user_available:
            row = db.execute(
                text(
                    """
                    UPDATE green_work_orders
                    SET target_trees = COALESCE(target_trees, 0) + :target_trees,
                        assignee_name = COALESCE(:assignee_name, assignee_name),
                        assignee_user_id = COALESCE(:assignee_user_id, assignee_user_id),
                        due_date = COALESCE(:due_date, due_date),
                        last_update = NOW()
                    WHERE id = :id
                    RETURNING id
                    """
                ),
                {
                    "id": int(existing_id),
                    "target_trees": int(target_trees or 0),
                    "assignee_name": assignee_clean,
                    "assignee_user_id": int(sponsor_agent_user_id) if sponsor_agent_user_id is not None else None,
                    "due_date": due_date,
                },
            ).scalar()
        else:
            row = db.execute(
                text(
                    """
                    UPDATE green_work_orders
                    SET target_trees = COALESCE(target_trees, 0) + :target_trees,
                        assignee_name = COALESCE(:assignee_name, assignee_name),
                        due_date = COALESCE(:due_date, due_date),
                        last_update = NOW()
                    WHERE id = :id
                    RETURNING id
                    """
                ),
                {
                    "id": int(existing_id),
                    "target_trees": int(target_trees or 0),
                    "assignee_name": assignee_clean,
                    "due_date": due_date,
                },
            ).scalar()
        action_name = "work_order_accumulated"
    else:
        if work_order_assignee_user_available:
            row = db.execute(text("""
                INSERT INTO green_work_orders (
                    project_id, assignee_name, assignee_user_id, work_type, target_trees, species_allocations, maintenance_schedule,
                    auto_assign_first_cycle_maintenance, due_date,
                    area_enabled, area_label, area_geojson, allow_existing_tree_area_reuse
                )
                VALUES (
                    :project_id, :assignee_name, :assignee_user_id, :work_type, :target_trees, CAST(:species_allocations AS JSONB), :maintenance_schedule,
                    :auto_assign_first_cycle_maintenance, :due_date,
                    :area_enabled, :area_label, CAST(:area_geojson AS JSONB), :allow_existing_tree_area_reuse
                )
                RETURNING id
            """), {
                "project_id": project_id,
                "assignee_name": assignee_clean,
                "assignee_user_id": int(sponsor_agent_user_id) if sponsor_agent_user_id is not None else None,
                "work_type": work_type,
                "target_trees": target_trees,
                "species_allocations": _safe_json(normalized_species_allocations) if normalized_species_allocations else None,
                "maintenance_schedule": maintenance_schedule or None,
                "auto_assign_first_cycle_maintenance": auto_assign_first_cycle_maintenance,
                "due_date": due_date,
                "area_enabled": bool(area_enabled),
                "area_label": area_label_clean,
                "area_geojson": _safe_json(normalized_area_geojson) if normalized_area_geojson else None,
                "allow_existing_tree_area_reuse": bool(allow_existing_tree_area_reuse),
            }).scalar()
        else:
            row = db.execute(text("""
                INSERT INTO green_work_orders (
                    project_id, assignee_name, work_type, target_trees, species_allocations, maintenance_schedule,
                    auto_assign_first_cycle_maintenance, due_date,
                    area_enabled, area_label, area_geojson, allow_existing_tree_area_reuse
                )
                VALUES (
                    :project_id, :assignee_name, :work_type, :target_trees, CAST(:species_allocations AS JSONB), :maintenance_schedule,
                    :auto_assign_first_cycle_maintenance, :due_date,
                    :area_enabled, :area_label, CAST(:area_geojson AS JSONB), :allow_existing_tree_area_reuse
                )
                RETURNING id
            """), {
                "project_id": project_id,
                "assignee_name": assignee_clean,
                "work_type": work_type,
                "target_trees": target_trees,
                "species_allocations": _safe_json(normalized_species_allocations) if normalized_species_allocations else None,
                "maintenance_schedule": maintenance_schedule or None,
                "auto_assign_first_cycle_maintenance": auto_assign_first_cycle_maintenance,
                "due_date": due_date,
                "area_enabled": bool(area_enabled),
                "area_label": area_label_clean,
                "area_geojson": _safe_json(normalized_area_geojson) if normalized_area_geojson else None,
                "allow_existing_tree_area_reuse": bool(allow_existing_tree_area_reuse),
            }).scalar()
        action_name = "work_order_created"
    _log_audit_event(
        db,
        project_id=project_id,
        entity_type="work_order",
        entity_id=int(row),
        action=action_name,
        actor=assignee_clean,
        details={
            "work_type": work_type,
            "target_trees": target_trees,
            "species_allocations": normalized_species_allocations,
            "maintenance_schedule": maintenance_schedule or None,
            "auto_assign_first_cycle_maintenance": auto_assign_first_cycle_maintenance,
            "due_date": due_date,
            "area_enabled": bool(area_enabled),
            "area_label": area_label_clean,
            "area_geojson": normalized_area_geojson,
            "allow_existing_tree_area_reuse": bool(allow_existing_tree_area_reuse),
        },
    )
    should_sync_public_sponsor_units = False
    if work_type == "planting":
        should_sync_public_sponsor_units = bool(public_sponsor_project)
    db.commit()
    work_order_id = int(row)
    if should_sync_public_sponsor_units:
        try:
            _try_assign_available_sponsor_units_for_project(
                db,
                project_id=int(project_id),
                context="create_work_order",
            )
        except Exception:
            logger.exception(
                "Sponsor QR project-level auto-assignment failed after work order commit for project_id=%s work_order_id=%s",
                int(project_id),
                work_order_id,
            )
        if sponsor_agent_user_id is not None:
            try:
                _try_assign_available_sponsor_units_for_agent(
                    db,
                    project_id=int(project_id),
                    user_id=int(sponsor_agent_user_id),
                    organization_id=project_organization_id,
                    context="create_work_order",
                )
            except Exception:
                logger.exception(
                    "Sponsor QR agent-level auto-assignment failed after work order commit for project_id=%s work_order_id=%s",
                    int(project_id),
                    work_order_id,
                )
    due_label = _safe_push_date_label(due_date)
    if work_type == "planting":
        if action_name == "work_order_accumulated":
            try:
                _queue_green_push_to_assignee(
                    db,
                    project_id=project_id,
                    assignee_name=assignee_clean,
                    title="Planting target increased",
                    body=(
                        f"Your planting target increased by {int(target_trees or 0)} tree{'s' if int(target_trees or 0) != 1 else ''}."
                        + (f" Due {due_label}." if due_label else "")
                    ),
                    data={
                        "type": "work_order_target_increase",
                        "project_id": int(project_id),
                        "work_order_id": int(row),
                        "work_type": work_type,
                        "target_trees_delta": int(target_trees or 0),
                    },
                )
            except Exception:
                logger.exception(
                    "Failed to queue planting target increase push for project_id=%s work_order_id=%s assignee=%s",
                    int(project_id),
                    int(row),
                    assignee_clean,
                )
        else:
            try:
                _queue_green_push_to_assignee(
                    db,
                    project_id=project_id,
                    assignee_name=assignee_clean,
                    title="New planting order assigned",
                    body=(
                        f"You have been assigned {int(target_trees or 0)} tree{'s' if int(target_trees or 0) != 1 else ''} for planting."
                        + (f" Due {due_label}." if due_label else "")
                    ),
                    data={
                        "type": "work_order_assigned",
                        "project_id": int(project_id),
                        "work_order_id": int(row),
                        "work_type": work_type,
                        "target_trees": int(target_trees or 0),
                    },
                )
            except Exception:
                logger.exception(
                    "Failed to queue planting assignment push for project_id=%s work_order_id=%s assignee=%s",
                    int(project_id),
                    int(row),
                    assignee_clean,
                )
            # Send first planting task assignment email notification
            past_count = db.execute(
                text(
                    """
                    SELECT COUNT(*)
                    FROM green_work_orders
                    WHERE project_id = :project_id
                    AND LOWER(TRIM(assignee_name)) = LOWER(TRIM(:assignee_name))
                    AND work_type = 'planting'
                    AND id <> :current_id
                    """
                ),
                {"project_id": project_id, "assignee_name": assignee_clean, "current_id": int(row)},
            ).scalar() or 0
            if past_count == 0:
                try:
                    _notify_agent_first_planting_assignment(db, project_id, assignee_clean, int(target_trees or 0))
                except Exception:
                    logger.exception(
                        "Failed to send first planting assignment email for project_id=%s work_order_id=%s assignee=%s",
                        int(project_id),
                        int(row),
                        assignee_clean,
                    )
    else:
        try:
            _queue_green_push_to_assignee(
                db,
                project_id=project_id,
                assignee_name=assignee_clean,
                title="New maintenance order assigned",
                body="A new maintenance order has been assigned to you." + (f" Due {due_label}." if due_label else ""),
                data={
                    "type": "work_order_assigned",
                    "project_id": int(project_id),
                    "work_order_id": int(row),
                    "work_type": work_type,
                },
            )
        except Exception:
            logger.exception(
                "Failed to queue maintenance assignment push for project_id=%s work_order_id=%s assignee=%s",
                int(project_id),
                int(row),
                assignee_clean,
            )
    return {"id": row}


@router.get("/work-orders")
def list_work_orders(
    project_id: int,
    assignee_name: str | None = None,
    db: Session = Depends(get_db),
):
    work_order_assignee_user_available = _ensure_work_order_assignee_columns(db)
    assignee_aliases = _list_assignee_aliases_for_lookup(db, assignee_name=assignee_name)
    if assignee_name and not assignee_aliases:
        assignee_aliases = _build_assignee_name_variants(assignee_name)
    matched_assignee_rows = _list_green_users_for_assignee_name(db, assignee_name=assignee_name, organization_id=None) if assignee_name else []
    assignee_user_ids = _normalize_positive_int_list([int(row.get("id") or 0) for row in matched_assignee_rows])
    if work_order_assignee_user_available:
        rows = db.execute(text("""
            WITH tree_counts AS (
                SELECT LOWER(TRIM(created_by)) AS assignee_key, COUNT(*) AS planted
                FROM trees
                WHERE project_id = :project_id
                  AND LOWER(COALESCE(tree_origin, 'new_planting')) = 'new_planting'
                  AND COALESCE(count_in_planting_kpis, TRUE) = TRUE
                  AND LOWER(REPLACE(REPLACE(COALESCE(status, ''), '-', '_'), ' ', '_')) <> 'pending_planting'
                GROUP BY created_by
            )
            SELECT o.id, o.project_id, o.assignee_name, o.work_type, o.target_trees,
                   o.species_allocations,
                   o.maintenance_schedule,
                   COALESCE(o.auto_assign_first_cycle_maintenance, FALSE) AS auto_assign_first_cycle_maintenance,
                   o.due_date, o.status,
                   COALESCE(o.area_enabled, FALSE) AS area_enabled,
                   o.area_label, o.area_geojson,
                   COALESCE(o.allow_existing_tree_area_reuse, FALSE) AS allow_existing_tree_area_reuse,
                   CASE
                       WHEN o.work_type = 'planting' THEN COALESCE(t.planted, 0)
                       ELSE o.planted_count
                   END AS planted_count,
                   o.last_update, o.created_at
            FROM green_work_orders o
            LEFT JOIN tree_counts t ON t.assignee_key = LOWER(TRIM(o.assignee_name))
            WHERE o.project_id = :project_id
              AND (
                    :assignee_filter_off = TRUE
                 OR LOWER(REGEXP_REPLACE(TRIM(COALESCE(o.assignee_name, '')), '\\s+', ' ', 'g')) IN :assignee_aliases
                 OR (:assignee_user_filter_off = FALSE AND COALESCE(o.assignee_user_id, 0) IN :assignee_user_ids)
              )
            ORDER BY o.created_at DESC
        """).bindparams(
            bindparam("assignee_aliases", expanding=True),
            bindparam("assignee_user_ids", expanding=True),
        ), {
            "project_id": int(project_id),
            "assignee_filter_off": not bool(str(assignee_name or "").strip()),
            "assignee_aliases": assignee_aliases or [""],
            "assignee_user_filter_off": not bool(assignee_user_ids),
            "assignee_user_ids": assignee_user_ids or [0],
        }).mappings().all()
    else:
        rows = db.execute(text("""
            WITH tree_counts AS (
                SELECT LOWER(TRIM(created_by)) AS assignee_key, COUNT(*) AS planted
                FROM trees
                WHERE project_id = :project_id
                  AND LOWER(COALESCE(tree_origin, 'new_planting')) = 'new_planting'
                  AND COALESCE(count_in_planting_kpis, TRUE) = TRUE
                  AND LOWER(REPLACE(REPLACE(COALESCE(status, ''), '-', '_'), ' ', '_')) <> 'pending_planting'
                GROUP BY created_by
            )
            SELECT o.id, o.project_id, o.assignee_name, o.work_type, o.target_trees,
                   o.species_allocations,
                   o.maintenance_schedule,
                   COALESCE(o.auto_assign_first_cycle_maintenance, FALSE) AS auto_assign_first_cycle_maintenance,
                   o.due_date, o.status,
                   COALESCE(o.area_enabled, FALSE) AS area_enabled,
                   o.area_label, o.area_geojson,
                   COALESCE(o.allow_existing_tree_area_reuse, FALSE) AS allow_existing_tree_area_reuse,
                   CASE
                       WHEN o.work_type = 'planting' THEN COALESCE(t.planted, 0)
                       ELSE o.planted_count
                   END AS planted_count,
                   o.last_update, o.created_at
            FROM green_work_orders o
            LEFT JOIN tree_counts t ON t.assignee_key = LOWER(TRIM(o.assignee_name))
            WHERE o.project_id = :project_id
              AND (
                    :assignee_filter_off = TRUE
                 OR LOWER(REGEXP_REPLACE(TRIM(COALESCE(o.assignee_name, '')), '\\s+', ' ', 'g')) IN :assignee_aliases
              )
            ORDER BY o.created_at DESC
        """).bindparams(
            bindparam("assignee_aliases", expanding=True),
        ), {
            "project_id": int(project_id),
            "assignee_filter_off": not bool(str(assignee_name or "").strip()),
            "assignee_aliases": assignee_aliases or [""],
        }).mappings().all()
    payload: list[dict] = []
    for row in rows:
        item = dict(row)
        raw_geojson = item.get("area_geojson")
        if isinstance(raw_geojson, str):
            try:
                item["area_geojson"] = json.loads(raw_geojson)
            except Exception:
                item["area_geojson"] = None
        raw_species_allocations = item.get("species_allocations")
        if isinstance(raw_species_allocations, str):
            try:
                raw_species_allocations = json.loads(raw_species_allocations)
            except Exception:
                raw_species_allocations = []
        item["species_allocations"] = _normalize_species_allocations(raw_species_allocations)
        item["auto_assign_first_cycle_maintenance"] = bool(item.get("auto_assign_first_cycle_maintenance"))
        item["area_enabled"] = bool(item.get("area_enabled")) and item.get("work_type") == "planting"
        item["allow_existing_tree_area_reuse"] = bool(item.get("allow_existing_tree_area_reuse")) and item["area_enabled"]
        if not item["area_enabled"]:
            item["area_geojson"] = None
            item["area_label"] = None
            item["allow_existing_tree_area_reuse"] = False
        payload.append(item)
    return payload


def _get_remote_monitoring_area_row(db: Session, *, area_id: int, project_id: int | None = None) -> dict | None:
    conditions = ["id = :area_id"]
    params: dict[str, object] = {"area_id": int(area_id)}
    if project_id is not None:
        conditions.append("project_id = :project_id")
        params["project_id"] = int(project_id)
    query = f"""
        SELECT id, project_id, name, area_geojson, area_sqm, baseline_date, notes, created_by, created_at, updated_at
        FROM green_remote_monitoring_areas
        WHERE {' AND '.join(conditions)}
        LIMIT 1
    """
    return _run_remote_monitoring_query(db, query, params).mappings().first()


@router.get("/remote-monitoring/areas")
@router.get("/vegetation-areas")
def list_remote_monitoring_areas(
    project_id: int,
    db: Session = Depends(get_db),
):
    _get_project_settings(db, int(project_id))
    rows = _run_remote_monitoring_query(
        db,
        """
        SELECT id, project_id, name, area_geojson, area_sqm, baseline_date, notes, created_by, created_at, updated_at
        FROM green_remote_monitoring_areas
        WHERE project_id = :project_id
        ORDER BY created_at DESC, id DESC
        """,
        {"project_id": int(project_id)},
    ).mappings().all()
    return [_serialize_remote_monitoring_area(row) for row in rows]


@router.post("/remote-monitoring/analysis")
@router.post("/vegetation-analysis")
def analyze_remote_monitoring_area(
    payload: VegetationAnalysisPayload,
    series_months: int = Query(default=6, ge=1, le=12),
    summary_window_days: int = Query(default=90, ge=30, le=180),
    db: Session = Depends(get_db),
):
    project_id = int(payload.project_id)
    _get_project_settings(db, project_id)
    normalized_area_geojson = _normalize_polygon_area_geojson(payload.area_geojson)
    if normalized_area_geojson is None:
        raise HTTPException(status_code=400, detail="Draw a valid polygon area")

    area_sqm = _compute_geojson_area_sqm(db, area_geojson=normalized_area_geojson)
    tree_counts = _count_trees_in_geojson(db, project_id=project_id, area_geojson=normalized_area_geojson)
    tree_rows = _list_trees_in_geojson(db, project_id=project_id, area_geojson=normalized_area_geojson)
    try:
        report = compute_remote_monitoring_report(
            boundary_geojson=normalized_area_geojson,
            tree_count=tree_counts["tree_count"],
            tree_items=tree_rows,
            polygon_area_sqm=area_sqm,
            series_months=series_months,
            summary_window_days=summary_window_days,
        )
    except RuntimeError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Remote monitoring failed: {exc}") from exc

    return {
        "area": {
            "project_id": project_id,
            "area_geojson": normalized_area_geojson,
            "area_sqm": round(area_sqm, 2),
            **tree_counts,
        },
        **report,
    }


@router.post("/remote-monitoring/areas")
@router.post("/vegetation-areas")
def create_remote_monitoring_area(
    payload: RemoteMonitoringAreaPayload,
    db: Session = Depends(get_db),
):
    project_id = int(payload.project_id)
    _get_project_settings(db, project_id)
    name = str(payload.name or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Area name is required")
    normalized_area_geojson = _normalize_polygon_area_geojson(payload.area_geojson)
    if normalized_area_geojson is None:
        raise HTTPException(status_code=400, detail="Draw a valid polygon area")

    baseline_date = _parse_date_value(payload.baseline_date)
    created_by = str(payload.created_by or "").strip() or None
    notes = str(payload.notes or "").strip() or None
    area_sqm = _compute_geojson_area_sqm(db, area_geojson=normalized_area_geojson)

    row = _run_remote_monitoring_query(
        db,
        """
        INSERT INTO green_remote_monitoring_areas (
            project_id, name, area_geojson, area_sqm, baseline_date, notes, created_by
        )
        VALUES (
            :project_id, :name, CAST(:area_geojson AS JSONB), :area_sqm, :baseline_date, :notes, :created_by
        )
        RETURNING id
        """,
        {
            "project_id": project_id,
            "name": name,
            "area_geojson": _safe_json(normalized_area_geojson),
            "area_sqm": area_sqm,
            "baseline_date": baseline_date,
            "notes": notes,
            "created_by": created_by,
        },
    ).scalar()
    db.commit()
    return _serialize_remote_monitoring_area(
        _get_remote_monitoring_area_row(db, area_id=int(row), project_id=project_id)
    )


@router.delete("/remote-monitoring/areas/{area_id}")
@router.delete("/vegetation-areas/{area_id}")
def delete_remote_monitoring_area(
    area_id: int,
    project_id: int,
    db: Session = Depends(get_db),
):
    _get_project_settings(db, int(project_id))
    existing = _get_remote_monitoring_area_row(db, area_id=area_id, project_id=project_id)
    if not existing:
        raise HTTPException(status_code=404, detail="Monitoring area not found")
    _run_remote_monitoring_query(
        db,
        "DELETE FROM green_remote_monitoring_areas WHERE id = :area_id",
        {"area_id": int(area_id)},
    )
    db.commit()
    return {"status": "deleted", "id": int(area_id)}


@router.get("/remote-monitoring/areas/{area_id}/analysis")
@router.get("/vegetation-areas/{area_id}/analysis")
def remote_monitoring_area_analysis(
    area_id: int,
    series_months: int = Query(default=6, ge=1, le=12),
    summary_window_days: int = Query(default=90, ge=30, le=180),
    db: Session = Depends(get_db),
):
    area_row = _get_remote_monitoring_area_row(db, area_id=area_id)
    if not area_row:
        raise HTTPException(status_code=404, detail="Monitoring area not found")
    project_id = int(area_row.get("project_id") or 0)
    if project_id <= 0:
        raise HTTPException(status_code=400, detail="Monitoring area is missing a project link")
    _get_project_settings(db, project_id)

    area_payload = _serialize_remote_monitoring_area(area_row)
    area_geojson = area_payload.get("area_geojson")
    if not area_geojson:
        raise HTTPException(status_code=400, detail="Monitoring polygon is invalid")

    tree_counts = _count_trees_in_geojson(db, project_id=project_id, area_geojson=area_geojson)
    tree_rows = _list_trees_in_geojson(db, project_id=project_id, area_geojson=area_geojson)
    try:
        report = compute_remote_monitoring_report(
            boundary_geojson=area_geojson,
            tree_count=tree_counts["tree_count"],
            tree_items=tree_rows,
            polygon_area_sqm=area_payload.get("area_sqm"),
            baseline_date=area_payload.get("baseline_date"),
            series_months=series_months,
            summary_window_days=summary_window_days,
        )
    except RuntimeError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Remote monitoring failed: {exc}") from exc

    return {
        "area": {
            **area_payload,
            **tree_counts,
        },
        **report,
    }


@router.patch("/work-orders/{work_id}")
def update_work_order(
    work_id: int,
    db: Session = Depends(get_db),
    status: str | None = Body(default=None),
    planted_count: int | None = Body(default=None),
):
    # Auto-calc planted_count from trees created by assignee for planting orders.
    row = db.execute(text("""
        SELECT id, project_id, assignee_name, work_type, status
        FROM green_work_orders
        WHERE id = :work_id
    """), {"work_id": work_id}).mappings().first()

    planted_value = planted_count
    if row and row["work_type"] == "planting":
        planted_value = db.execute(text("""
            SELECT COUNT(*) FROM trees
            WHERE project_id = :project_id AND created_by = :assignee_name
              AND LOWER(COALESCE(tree_origin, 'new_planting')) = 'new_planting'
              AND COALESCE(count_in_planting_kpis, TRUE) = TRUE
              AND LOWER(REPLACE(REPLACE(COALESCE(status, ''), '-', '_'), ' ', '_')) <> 'pending_planting'
        """), {"project_id": row["project_id"], "assignee_name": row["assignee_name"]}).scalar()

    existing_status = row.get("status") if row else None
    db.execute(text("""
        UPDATE green_work_orders
        SET status = COALESCE(:status, status),
            planted_count = COALESCE(:planted_count, planted_count),
            last_update = NOW()
        WHERE id = :work_id
    """), {
        "status": status,
        "planted_count": planted_value,
        "work_id": work_id,
    })
    if row:
        _log_audit_event(
            db,
            project_id=int(row["project_id"]),
            entity_type="work_order",
            entity_id=work_id,
            action="work_order_updated",
            actor=row.get("assignee_name"),
            details={
                "status": status,
                "planted_count": planted_value,
                "work_type": row.get("work_type"),
                "existing_status": existing_status,
            },
        )
    db.commit()
    return {"status": "ok"}


@router.get("/work-stats")
def work_stats(project_id: int, db: Session = Depends(get_db)):
    orders = db.execute(text("""
        SELECT assignee_name,
               COUNT(*) AS orders,
               SUM(target_trees) AS target_trees
        FROM green_work_orders
        WHERE project_id = :project_id
        GROUP BY assignee_name
    """), {"project_id": project_id}).mappings().all()

    tree_counts = db.execute(text("""
        SELECT created_by AS assignee_name, COUNT(*) AS trees_logged
        FROM trees
        WHERE project_id = :project_id
          AND LOWER(COALESCE(tree_origin, 'new_planting')) = 'new_planting'
          AND COALESCE(count_in_planting_kpis, TRUE) = TRUE
        GROUP BY created_by
    """), {"project_id": project_id}).mappings().all()
    tree_map = {r["assignee_name"]: r["trees_logged"] for r in tree_counts}
    merged = []
    for r in orders:
        row = dict(r)
        row["planted_count"] = tree_map.get(row.get("assignee_name"), 0)
        merged.append(row)

    maintenance_by_assignee = db.execute(text("""
        SELECT t.assignee_name,
               COUNT(*) AS maintenance_total,
               SUM(
                   CASE
                       WHEN LOWER(COALESCE(t.status, '')) IN ('done', 'completed', 'closed')
                            AND LOWER(COALESCE(t.review_state, 'none')) IN ('approved', 'none')
                       THEN 1 ELSE 0
                   END
               ) AS maintenance_done,
               SUM(
                   CASE
                       WHEN NOT (
                           LOWER(COALESCE(t.status, '')) IN ('done', 'completed', 'closed')
                           AND LOWER(COALESCE(t.review_state, 'none')) IN ('approved', 'none')
                       ) AND LOWER(COALESCE(t.status, 'pending')) <> 'overdue'
                       THEN 1 ELSE 0
                   END
               ) AS maintenance_pending,
               SUM(CASE WHEN t.status = 'overdue' THEN 1 ELSE 0 END) AS maintenance_overdue,
               COALESCE(STRING_AGG(DISTINCT t.task_type, ', ' ORDER BY t.task_type), '') AS maintenance_types,
               MAX(COALESCE(t.completed_at::date, t.due_date, t.created_at::date)) AS last_maintenance_date
        FROM tree_tasks t
        JOIN trees tr ON tr.id = t.tree_id
        WHERE tr.project_id = :project_id
        GROUP BY t.assignee_name
        ORDER BY t.assignee_name
    """), {"project_id": project_id}).mappings().all()

    maintenance_by_type = db.execute(text("""
        SELECT t.assignee_name,
               t.task_type,
               COUNT(*) AS maintenance_times,
               MAX(COALESCE(t.completed_at::date, t.due_date, t.created_at::date)) AS last_maintenance_date
        FROM tree_tasks t
        JOIN trees tr ON tr.id = t.tree_id
        WHERE tr.project_id = :project_id
        GROUP BY t.assignee_name, t.task_type
        ORDER BY t.assignee_name, maintenance_times DESC, t.task_type
    """), {"project_id": project_id}).mappings().all()

    return {
        "orders": merged,
        "trees_by_user": [dict(r) for r in tree_counts],
        "maintenance_by_assignee": [dict(r) for r in maintenance_by_assignee],
        "maintenance_by_type": [dict(r) for r in maintenance_by_type],
    }


@router.get("/work-stats/export/csv")
def export_work_stats_csv(project_id: int, db: Session = Depends(get_db)):
    stats = work_stats(project_id, db)
    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_csv = tempfile.NamedTemporaryFile(suffix="_work_stats.csv", delete=False)
    csv_path = tmp_csv.name
    tmp_csv.close()

    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = _excel_csv_writer(f)
        writer.writerow(["assignee", "orders", "target_trees", "planted_count"])
        for r in stats["orders"]:
            writer.writerow([
                r.get("assignee_name", ""),
                r.get("orders", 0),
                r.get("target_trees", 0),
                r.get("planted_count", 0),
            ])

    filename = f"project_{project_id}_work_stats.csv"
    return FileResponse(csv_path, media_type="text/csv", filename=filename)


@router.get("/work-stats/export/pdf")
def export_work_stats_pdf(project_id: int, db: Session = Depends(get_db)):
    project = get_project(project_id, db)
    stats = work_stats(project_id, db)
    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_pdf = tempfile.NamedTemporaryFile(suffix="_work_report.pdf", delete=False)
