def _estimate_tree_co2_height_aware_kg(
    species: str | None,
    age_years: float,
    tree_height_m: float | None,
) -> tuple[float, bool]:
    """Estimate current tree CO2, preferring measured height where available."""
    if age_years <= 0:
        return 0.0, False

    try:
        measured_height = float(tree_height_m) if tree_height_m is not None else None
    except Exception:
        measured_height = None
    if measured_height is None or measured_height <= 0:
        return estimate_tree_co2_kg(species, age_years), False

    try:
        params = _get_species_params(species)
        dbh_cm = project_dbh(params, age_years)
        agb = calculate_agb_chave(params["wood_density"], dbh_cm, measured_height)
        if agb <= 0:
            return estimate_tree_co2_kg(species, age_years), False
        bgb = agb * float(params.get("root_shoot_ratio", 0.24))
        total_biomass = agb + bgb
        carbon_kg = total_biomass * float(params.get("carbon_fraction", 0.47))
        co2_kg = carbon_kg * (44.0 / 12.0)
        return round(max(co2_kg, 0.0), 2), True
    except Exception:
        return estimate_tree_co2_kg(species, age_years), False


def _coerce_tree_age_months(value: object) -> float | None:
    try:
        if value is None or value == "":
            return None
        months = float(value)
    except Exception:
        return None
    if months < 0:
        return None
    return months


def _infer_tree_age_days_for_maintenance(tree_row: dict, as_of_date: date | None = None) -> int | None:
    today = as_of_date or date.today()
    origin_key = _normalize_tree_origin(tree_row.get("tree_origin"))
    age_months = _coerce_tree_age_months(tree_row.get("tree_age_months"))
    if origin_key == "existing_inventory" and age_months is not None:
        capture_ref = (
            _parse_date_value(tree_row.get("created_at"))
            or _parse_date_value(tree_row.get("submitted_at"))
            or _parse_date_value(tree_row.get("reviewed_at"))
        )
        elapsed_days = max(_day_diff(today, capture_ref), 0) if capture_ref is not None else 0
        base_days = int(round(age_months * 30.4375))
        return max(base_days + elapsed_days, 0)

    planting_ref = _parse_date_value(tree_row.get("planting_date"))
    if planting_ref is not None:
        return max(_day_diff(today, planting_ref), 0)

    if age_months is None:
        return None

    capture_ref = (
        _parse_date_value(tree_row.get("created_at"))
        or _parse_date_value(tree_row.get("submitted_at"))
        or _parse_date_value(tree_row.get("reviewed_at"))
    )
    elapsed_days = max(_day_diff(today, capture_ref), 0) if capture_ref is not None else 0
    base_days = int(round(age_months * 30.4375))
    return max(base_days + elapsed_days, 0)


def _infer_tree_age_for_carbon(tree_row: dict) -> tuple[float, str]:
    """Infer tree age in years with existing-tree age-months priority."""
    tree = dict(tree_row)
    today = date.today()
    origin_key = _normalize_tree_origin(tree.get("tree_origin"))
    age_months = _coerce_tree_age_months(tree.get("tree_age_months"))

    # Existing Tree records often store a survey/reference date in planting_date.
    # When explicit age months is provided, prefer it to avoid zero-age CO2 from a recent reference date.
    if origin_key == "existing_inventory" and age_months is not None:
        elapsed_years = 0.0
        capture_ref = _parse_date_value(tree.get("created_at")) or _parse_date_value(tree.get("submitted_at")) or _parse_date_value(tree.get("reviewed_at"))
        if capture_ref is not None:
            elapsed_years = tree_age_years(capture_ref, today)
        age_years = max((age_months / 12.0) + elapsed_years, 0.0)
        return age_years, "tree_age_months"

    planting_ref = _parse_date_value(tree.get("planting_date"))
    if planting_ref is not None:
        return tree_age_years(planting_ref, today), "planting_date"

    if age_months is None:
        ref_date, ref_source = _infer_tree_reference_date(tree)
        if ref_date is None:
            return 0.0, "none"
        return tree_age_years(ref_date, today), ref_source

    elapsed_years = 0.0
    capture_ref = _parse_date_value(tree.get("created_at")) or _parse_date_value(tree.get("submitted_at")) or _parse_date_value(tree.get("reviewed_at"))
    if capture_ref is not None:
        elapsed_years = tree_age_years(capture_ref, today)
    age_years = max((age_months / 12.0) + elapsed_years, 0.0)
    return age_years, "tree_age_months"


def _build_tree_carbon_metrics(
    tree_row: dict,
    projection_years: int = 40,
    enforce_carbon_scope: bool = False,
) -> dict:
    """Per-tree CO2 metrics with measured-height preference for current stock."""
    tree = dict(tree_row)
    age_years, ref_source = _infer_tree_age_for_carbon(tree)
    species = tree.get("species")
    params = _get_species_params(species)
    status_key = _normalize_tree_status(tree.get("status"))
    is_alive = status_key not in DEAD_TREE_STATUSES
    raw_carbon_scope = tree.get("count_in_carbon_scope")
    in_carbon_scope = True if raw_carbon_scope is None else bool(raw_carbon_scope)
    scope_applies = in_carbon_scope or not enforce_carbon_scope
    try:
        inventory_tree_count = int(tree.get("inventory_tree_count") or 1)
    except Exception:
        inventory_tree_count = 1
    inventory_tree_count = max(inventory_tree_count, 1)

    current_co2_per_tree_kg = 0.0
    annual_co2_per_tree_kg = 0.0
    lifetime_co2_per_tree_kg = 0.0
    height_used = False

    if scope_applies and age_years > 0:
        current_co2_per_tree_kg, height_used = _estimate_tree_co2_height_aware_kg(
            species,
            age_years,
            tree.get("tree_height_m"),
        )
        if is_alive:
            if height_used and age_years > 1:
                previous_modeled = estimate_tree_co2_kg(species, max(age_years - 1.0, 0.0))
                annual_co2_per_tree_kg = round(max(current_co2_per_tree_kg - previous_modeled, 0.0), 2)
            else:
                annual_co2_per_tree_kg = estimate_annual_co2_kg(species, age_years)
            lifetime_co2_per_tree_kg = estimate_lifetime_co2_kg(species, projection_years)

    current_co2_kg = max(current_co2_per_tree_kg, 0.0) * inventory_tree_count
    annual_co2_kg = max(annual_co2_per_tree_kg, 0.0) * inventory_tree_count
    lifetime_co2_kg = max(lifetime_co2_per_tree_kg, 0.0) * inventory_tree_count

    return {
        "species_matched": params.get("label", "Unknown"),
        "growth_class": params.get("growth_class", "medium"),
        "age_years": round(age_years, 2),
        "age_source": ref_source,
        "inventory_tree_count": inventory_tree_count,
        "current_co2_per_tree_kg": round(max(current_co2_per_tree_kg, 0.0), 2),
        "annual_co2_per_tree_kg": round(max(annual_co2_per_tree_kg, 0.0), 2),
        "lifetime_co2_per_tree_kg": round(max(lifetime_co2_per_tree_kg, 0.0), 2),
        "current_co2_kg": round(current_co2_kg, 2),
        "annual_co2_kg": round(max(annual_co2_kg, 0.0), 2),
        "lifetime_co2_kg": round(max(lifetime_co2_kg, 0.0), 2),
        "lifetime_co2_tonnes": round(max(lifetime_co2_kg, 0.0) / 1000.0, 4),
        "height_used_for_co2": height_used,
        "co2_height_source": "measured_tree_height_m" if height_used else "modeled_height",
        "co2_in_scope": in_carbon_scope,
        "is_alive_for_co2": is_alive,
        "co2_methodology": (
            "IPCC Tier 1 + Chave et al. (2014); measured height used for current stock where available, "
            "otherwise modeled height from species curve"
        ),
    }


def _fetch_existing_tree_export_rows(project_id: int, db: Session) -> list[dict]:
    rows = db.execute(
        text(
            """
            SELECT
                t.id,
                t.project_id,
                t.project_tree_no,
                t.species,
                t.planting_date,
                t.status,
                t.notes,
                t.photo_url,
                t.photo_urls,
                t.created_by,
                t.created_at,
                t.tree_origin,
                t.attribution_scope,
                t.count_in_planting_kpis,
                t.count_in_carbon_scope,
                t.source_project_id,
                t.tree_age_months,
                t.custodian_id,
                c.name AS custodian_name,
                t.tree_height_m,
                COALESCE(t.inventory_tree_count, 1) AS inventory_tree_count,
                t.existing_area_geojson,
                t.existing_area_sqm,
                t.record_profile_data,
                c.profile_data AS custodian_profile_data,
                ST_X(t.geom) AS lng,
                ST_Y(t.geom) AS lat
            FROM trees t
            LEFT JOIN green_custodians c ON c.id = t.custodian_id
            WHERE t.project_id = :project_id
              AND (
                    (
                        LOWER(REPLACE(COALESCE(t.tree_origin, ''), ' ', '_')) <> ''
                        AND LOWER(REPLACE(COALESCE(t.tree_origin, ''), ' ', '_')) <> 'new_planting'
                    )
                    OR LOWER(REPLACE(COALESCE(t.attribution_scope, ''), ' ', '_')) = 'monitor_only'
                    OR COALESCE(t.count_in_planting_kpis, TRUE) = FALSE
                    OR COALESCE(t.source_project_id, 0) > 0
                  )
            ORDER BY t.created_at DESC, t.id DESC
            """
        ),
        {"project_id": project_id},
    ).mappings().all()

    merged_rows = _attach_maintenance_to_tree_rows(rows, _maintenance_summary_by_tree(project_id, db))
    review_summary = _review_summary_by_tree(project_id, db)

    enriched: list[dict] = []
    for row in merged_rows:
        item = dict(row)
        item["photo_urls"] = _normalize_photo_urls(item.get("photo_urls"))
        try:
            item["inventory_tree_count"] = max(int(item.get("inventory_tree_count") or 1), 1)
        except Exception:
            item["inventory_tree_count"] = 1
        try:
            item["existing_area_sqm"] = (
                round(float(item.get("existing_area_sqm")), 2) if item.get("existing_area_sqm") is not None else None
            )
        except Exception:
            item["existing_area_sqm"] = None
        item["existing_area_ha"] = (
            round(float(item.get("existing_area_sqm") or 0.0) / 10000.0, 4)
            if item.get("existing_area_sqm") is not None
            else None
        )
        item["record_profile_data"] = _normalize_tree_record_profile_data(
            item.get("record_profile_data"),
            existing_area_sqm=item.get("existing_area_sqm"),
        )
        item["custodian_profile_data"] = _normalize_custodian_profile_data(item.get("custodian_profile_data"))
        item.update(review_summary.get(int(item.get("id") or 0), {}))
        item.update(_build_tree_carbon_metrics(item, projection_years=40, enforce_carbon_scope=True))
        enriched.append(item)
    return enriched


def _summarize_existing_tree_export_rows(rows: list[dict]) -> dict:
    total_rows = len(rows)
    total_existing_trees = 0
    alive_rows = 0
    dead_rows = 0
    attention_rows = 0
    pending_rows = 0
    rows_with_height = 0
    rows_missing_height = 0
    trees_missing_age_data = 0
    trees_with_fallback_age = 0
    carbon_scope_rows = 0
    carbon_excluded_rows = 0
    current_co2_kg = 0.0
    annual_co2_kg = 0.0
    lifetime_co2_kg = 0.0
    total_existing_area_sqm = 0.0
    rows_with_existing_area = 0
    species_agg: dict[str, dict] = {}

    for row in rows:
        try:
            tree_units = max(int(row.get("inventory_tree_count") or 1), 1)
        except Exception:
            tree_units = 1
        total_existing_trees += tree_units

        status_key = _normalize_tree_status(row.get("status"))
        if status_key in HEALTHY_TREE_STATUSES:
            alive_rows += tree_units
        elif status_key in DEAD_TREE_STATUSES:
            dead_rows += tree_units
        elif status_key in ATTENTION_TREE_STATUSES:
            attention_rows += tree_units
        elif status_key == "pending_planting":
            pending_rows += tree_units

        try:
            height_val = float(row.get("tree_height_m")) if row.get("tree_height_m") is not None else None
        except Exception:
            height_val = None
        if height_val is not None and height_val > 0:
            rows_with_height += 1
        else:
            rows_missing_height += 1

        age_source = str(row.get("age_source") or "")
        if age_source == "none":
            trees_missing_age_data += 1
        elif age_source and age_source != "planting_date":
            trees_with_fallback_age += 1

        in_scope = bool(row.get("co2_in_scope", True))
        if in_scope:
            carbon_scope_rows += tree_units
            current_co2_kg += float(row.get("current_co2_kg") or 0.0)
            annual_co2_kg += float(row.get("annual_co2_kg") or 0.0)
            lifetime_co2_kg += float(row.get("lifetime_co2_kg") or 0.0)
        else:
            carbon_excluded_rows += tree_units

        try:
            area_sqm = float(row.get("existing_area_sqm")) if row.get("existing_area_sqm") is not None else None
        except Exception:
            area_sqm = None
        if area_sqm is not None and area_sqm > 0:
            total_existing_area_sqm += area_sqm
            rows_with_existing_area += 1

        species_label = str(row.get("species") or "").strip() or str(row.get("species_matched") or "Unknown")
        species_key = species_label.lower()
        if species_key not in species_agg:
            species_agg[species_key] = {"species": species_label, "count": 0, "co2_kg": 0.0}
        species_agg[species_key]["count"] += tree_units
        if in_scope:
            species_agg[species_key]["co2_kg"] += float(row.get("current_co2_kg") or 0.0)

    top_species = sorted(
        species_agg.values(),
        key=lambda item: (float(item.get("co2_kg") or 0.0), int(item.get("count") or 0)),
        reverse=True,
    )[:12]
    for item in top_species:
        item["co2_kg"] = round(float(item.get("co2_kg") or 0.0), 2)

    return {
        "total_existing_trees": total_existing_trees,
        "total_existing_rows": total_rows,
        "alive_trees": alive_rows,
        "dead_trees": dead_rows,
        "attention_trees": attention_rows,
        "pending_trees": pending_rows,
        "rows_with_height": rows_with_height,
        "rows_missing_height": rows_missing_height,
        "rows_with_existing_area": rows_with_existing_area,
        "total_existing_area_sqm": round(total_existing_area_sqm, 2),
        "total_existing_area_ha": round(total_existing_area_sqm / 10000.0, 4),
        "trees_missing_age_data": trees_missing_age_data,
        "trees_with_fallback_age": trees_with_fallback_age,
        "carbon_scope_rows": carbon_scope_rows,
        "carbon_excluded_rows": carbon_excluded_rows,
        "current_co2_kg": round(current_co2_kg, 2),
        "current_co2_tonnes": round(current_co2_kg / 1000.0, 3),
        "annual_co2_kg": round(annual_co2_kg, 2),
        "annual_co2_tonnes": round(annual_co2_kg / 1000.0, 3),
        "projected_lifetime_co2_kg": round(lifetime_co2_kg, 2),
        "projected_lifetime_co2_tonnes": round(lifetime_co2_kg / 1000.0, 3),
        "projection_years": 40,
        "methodology": (
            "IPCC Tier 1 + Chave et al. (2014); per-tree current CO2 uses measured height where available "
            "(tree_height_m), otherwise modeled height. Annual and 40-year values use species-age growth model."
        ),
        "top_species": top_species,
    }


def _is_export_task_complete(row: dict) -> bool:
    status_key = _normalize_name(row.get("status"))
    review_key = _normalize_name(row.get("review_state")) or "none"
    if review_key == "approved":
        return True
    return status_key in {"done", "completed", "closed"} and review_key in {"none", "approved"}


def _build_agric_programme_export_context(
    project_id: int,
    db: Session,
    *,
    include_map: bool = False,
) -> dict:
    project = get_project(project_id, db)
    project_copy = dict(project)
    project_copy["agric_config"] = _normalize_agric_config(project.get("agric_config")) or {}

    raw_plot_rows = _fetch_existing_tree_export_rows(project_id, db)
    plot_rows: list[dict] = []
    for source_row in raw_plot_rows:
        if _is_hidden_tree_record(source_row.get("record_profile_data")):
            continue
        row = dict(source_row)
        photo_urls = _normalize_photo_urls(row.get("photo_urls"))
        primary_photo_url = str(row.get("photo_url") or "").strip()
        if primary_photo_url:
            photo_urls = [primary_photo_url, *[item for item in photo_urls if item != primary_photo_url]]
        row["photo_urls"] = photo_urls
        row["primary_photo_url"] = photo_urls[0] if photo_urls else primary_photo_url
        row["record_profile_data"] = _normalize_tree_record_profile_data(
            row.get("record_profile_data"),
            existing_area_sqm=row.get("existing_area_sqm"),
        ) or {}
        row["custodian_profile_data"] = _normalize_custodian_profile_data(row.get("custodian_profile_data")) or {}
        plot_rows.append(row)

    farmer_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    c.id,
                    c.project_id,
                    c.custodian_type,
                    c.name,
                    c.contact_person,
                    c.phone,
                    c.alt_phone,
                    c.email,
                    c.address_text,
                    c.local_government,
                    c.community_name,
                    c.verification_status,
                    c.notes,
                    c.created_at,
                    c.profile_data
                FROM green_custodians c
                WHERE c.project_id = :project_id
                ORDER BY c.created_at DESC, c.id DESC
                """
            ),
            {"project_id": project_id},
        ).mappings().all()
    ]
    for row in farmer_rows:
        row["profile_data"] = _normalize_custodian_profile_data(row.get("profile_data")) or {}
    farmer_by_id = {int(row.get("id") or 0): row for row in farmer_rows if int(row.get("id") or 0) > 0}

    allocation_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    a.id,
                    a.custodian_id,
                    COALESCE(a.quantity_allocated, 0) AS quantity_allocated,
                    COALESCE(a.supervision_target, 0) AS supervision_target,
                    a.expected_planting_start,
                    a.expected_planting_end,
                    a.notes,
                    a.created_at,
                    e.event_date,
                    e.species AS support_item
                FROM green_distribution_allocations a
                LEFT JOIN green_distribution_events e ON e.id = a.event_id
                WHERE a.project_id = :project_id
                ORDER BY a.created_at DESC, a.id DESC
                """
            ),
            {"project_id": project_id},
        ).mappings().all()
    ]

    task_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    t.id,
                    t.tree_id,
                    t.custodian_id,
                    LOWER(COALESCE(t.task_type, '')) AS task_type,
                    LOWER(COALESCE(t.status, '')) AS status,
                    LOWER(COALESCE(t.review_state, 'none')) AS review_state,
                    t.assignee_name,
                    t.created_at,
                    t.completed_at,
                    t.due_date,
                    t.submitted_at,
                    t.reviewed_at
                FROM tree_tasks t
                JOIN trees tr ON tr.id = t.tree_id
                WHERE tr.project_id = :project_id
                  AND t.custodian_id IS NOT NULL
                  AND LOWER(COALESCE(t.task_type, '')) IN :task_types
                ORDER BY COALESCE(t.reviewed_at, t.submitted_at, t.created_at) DESC, t.id DESC
                """
            ).bindparams(bindparam("task_types", expanding=True)),
            {"project_id": project_id, "task_types": tuple(SUPPORT_ALLOCATION_TASK_TYPES)},
        ).mappings().all()
    ]

    plot_ids = {int(row.get("id") or 0) for row in plot_rows if int(row.get("id") or 0) > 0}
    farmer_ids = {int(row.get("id") or 0) for row in farmer_rows if int(row.get("id") or 0) > 0}

    allocation_summary_by_farmer: dict[int, dict] = {}
    for row in allocation_rows:
        custodian_id = int(row.get("custodian_id") or 0)
        if custodian_id <= 0:
            continue
        summary = allocation_summary_by_farmer.setdefault(
            custodian_id,
            {
                "allocation_count": 0,
                "allocated_units": 0.0,
                "support_target": 0,
                "latest_support_item": "",
                "latest_event_date": None,
            },
        )
        summary["allocation_count"] += 1
        summary["allocated_units"] += float(row.get("quantity_allocated") or 0.0)
        summary["support_target"] += int(row.get("supervision_target") or 0)
        if not summary["latest_support_item"] and str(row.get("support_item") or "").strip():
            summary["latest_support_item"] = str(row.get("support_item") or "").strip()
        if summary["latest_event_date"] is None and row.get("event_date") is not None:
            summary["latest_event_date"] = row.get("event_date")

    task_summary_by_farmer: dict[int, dict] = {}
    task_summary_by_plot: dict[int, dict] = {}
    for row in task_rows:
        custodian_id = int(row.get("custodian_id") or 0)
        plot_id = int(row.get("tree_id") or 0)
        task_type = _normalize_name(row.get("task_type"))
        is_complete = _is_export_task_complete(row)
        for target_map, target_id in ((task_summary_by_farmer, custodian_id), (task_summary_by_plot, plot_id)):
            if target_id <= 0:
                continue
            summary = target_map.setdefault(
                target_id,
                {
                    "field_capture_assigned": 0,
                    "field_capture_done": 0,
                    "support_visit_assigned": 0,
                    "support_visit_done": 0,
                    "last_task_date": None,
                },
            )
            date_candidate = row.get("reviewed_at") or row.get("submitted_at") or row.get("completed_at") or row.get("created_at")
            if date_candidate and summary["last_task_date"] is None:
                summary["last_task_date"] = date_candidate
            if task_type == FIELD_CAPTURE_TASK_TYPE:
                summary["field_capture_assigned"] += 1
                if is_complete:
                    summary["field_capture_done"] += 1
            elif task_type == SUPERVISION_TASK_TYPE:
                summary["support_visit_assigned"] += 1
                if is_complete:
                    summary["support_visit_done"] += 1

    plot_summary_by_farmer: dict[int, dict] = {}
    commodity_counts: dict[str, dict] = {}
    total_area_ha = 0.0
    total_estimated_yield_kg = 0.0
    polygon_plot_count = 0
    photo_plot_count = 0
    farmer_linked_plot_count = 0
    crop_profile_count = 0
    season_profile_count = 0
    reviewed_plot_count = 0
    for row in plot_rows:
        plot_id = int(row.get("id") or 0)
        custodian_id = int(row.get("custodian_id") or 0)
        record_profile = row.get("record_profile_data") or {}
        linked_farmer = farmer_by_id.get(custodian_id) or {}
        if linked_farmer:
            for key in (
                "phone",
                "alt_phone",
                "email",
                "address_text",
                "local_government",
                "community_name",
                "verification_status",
                "contact_person",
            ):
                row[key] = linked_farmer.get(key)
        area_ha = float(record_profile.get("area_hectares") or row.get("existing_area_ha") or 0.0)
        commodity = str(record_profile.get("commodity") or row.get("species") or "").strip()
        if area_ha > 0:
            total_area_ha += area_ha
        estimated_yield_kg = float(record_profile.get("estimated_yield_kg") or 0.0)
        if estimated_yield_kg > 0:
            total_estimated_yield_kg += estimated_yield_kg
        if _is_polygonal_work_area(row.get("existing_area_geojson")):
            polygon_plot_count += 1
        if str(row.get("primary_photo_url") or "").strip():
            photo_plot_count += 1
        if custodian_id > 0:
            farmer_linked_plot_count += 1
            farmer_plot_summary = plot_summary_by_farmer.setdefault(custodian_id, {"plot_count": 0, "area_ha": 0.0, "estimated_yield_kg": 0.0})
            farmer_plot_summary["plot_count"] += 1
            farmer_plot_summary["area_ha"] += area_ha
            farmer_plot_summary["estimated_yield_kg"] += estimated_yield_kg
        if commodity:
            crop_profile_count += 1
            key = commodity.lower()
            item = commodity_counts.setdefault(key, {"label": commodity, "plot_count": 0, "area_ha": 0.0})
            item["plot_count"] += 1
            item["area_ha"] += area_ha
        if record_profile.get("season_name") or record_profile.get("season_year") or row.get("planting_date"):
            season_profile_count += 1
        if _normalize_name(row.get("last_review_state")) in {"approved", "metadata_edit", "submitted"}:
            reviewed_plot_count += 1

        plot_task_summary = task_summary_by_plot.get(plot_id) or {}
        row["field_capture_assigned"] = int(plot_task_summary.get("field_capture_assigned") or 0)
        row["field_capture_done"] = int(plot_task_summary.get("field_capture_done") or 0)
        row["field_capture_live"] = max(row["field_capture_assigned"] - row["field_capture_done"], 0)
        row["support_visit_assigned"] = int(plot_task_summary.get("support_visit_assigned") or 0)
        row["support_visit_done"] = int(plot_task_summary.get("support_visit_done") or 0)
        row["support_visit_live"] = max(row["support_visit_assigned"] - row["support_visit_done"], 0)
        row["latest_task_date"] = plot_task_summary.get("last_task_date")

    top_commodities = sorted(
        commodity_counts.values(),
        key=lambda item: (float(item.get("area_ha") or 0.0), int(item.get("plot_count") or 0)),
        reverse=True,
    )[:8]
    for item in top_commodities:
        item["area_ha"] = round(float(item.get("area_ha") or 0.0), 4)

    for row in farmer_rows:
        farmer_id = int(row.get("id") or 0)
        profile = row.get("profile_data") or {}
        allocation_summary = allocation_summary_by_farmer.get(farmer_id) or {}
        task_summary = task_summary_by_farmer.get(farmer_id) or {}
        plot_summary = plot_summary_by_farmer.get(farmer_id) or {}
        row["allocation_count"] = int(allocation_summary.get("allocation_count") or 0)
        row["allocated_units"] = round(float(allocation_summary.get("allocated_units") or 0.0), 2)
        row["support_target"] = int(allocation_summary.get("support_target") or 0)
        row["plot_count"] = int(plot_summary.get("plot_count") or 0)
        row["mapped_area_ha"] = round(float(plot_summary.get("area_ha") or 0.0), 4)
        row["estimated_yield_kg"] = round(float(plot_summary.get("estimated_yield_kg") or 0.0), 2)
        row["field_capture_assigned"] = int(task_summary.get("field_capture_assigned") or 0)
        row["field_capture_done"] = int(task_summary.get("field_capture_done") or 0)
        row["field_capture_live"] = max(row["field_capture_assigned"] - row["field_capture_done"], 0)
        row["support_visit_assigned"] = int(task_summary.get("support_visit_assigned") or 0)
        row["support_visit_done"] = int(task_summary.get("support_visit_done") or 0)
        row["support_visit_live"] = max(row["support_visit_assigned"] - row["support_visit_done"], 0)
        row["latest_task_date"] = task_summary.get("last_task_date")
        row["farmer_code"] = str(profile.get("farmer_code") or "").strip()
        row["national_id"] = str(profile.get("national_id") or "").strip()
        row["farmer_group"] = str(profile.get("farmer_group") or "").strip()
        row["finance_access"] = bool(profile.get("finance_access")) if profile.get("finance_access") is not None else False
        row["insurance_access"] = bool(profile.get("insurance_access")) if profile.get("insurance_access") is not None else False

    verified_farmers = sum(1 for row in farmer_rows if _normalize_name(row.get("verification_status")) == "verified")
    finance_access_farmers = sum(1 for row in farmer_rows if bool(row.get("finance_access")))
    insurance_access_farmers = sum(1 for row in farmer_rows if bool(row.get("insurance_access")))
    grouped_farmers = sum(1 for row in farmer_rows if str(row.get("farmer_group") or "").strip())
    identity_ready_farmers = sum(1 for row in farmer_rows if str(row.get("farmer_code") or "").strip() or str(row.get("national_id") or "").strip())

    field_capture_assigned_total = sum(int(row.get("field_capture_assigned") or 0) for row in farmer_rows)
    field_capture_done_total = sum(int(row.get("field_capture_done") or 0) for row in farmer_rows)
    support_visit_assigned_total = sum(int(row.get("support_visit_assigned") or 0) for row in farmer_rows)
    support_visit_done_total = sum(int(row.get("support_visit_done") or 0) for row in farmer_rows)
    support_target_total = sum(int(row.get("support_target") or 0) for row in farmer_rows)
    allocated_units_total = round(sum(float(row.get("allocated_units") or 0.0) for row in farmer_rows), 2)

    def _pct(value: int, total: int) -> float:
        return round((float(value) / float(total)) * 100.0, 1) if total > 0 else 0.0

    summary = {
        "registered_farmers": len(farmer_rows),
        "verified_farmers": verified_farmers,
        "mapped_plots": len(plot_rows),
        "mapped_area_ha": round(total_area_ha, 4),
        "estimated_yield_kg": round(total_estimated_yield_kg, 2),
        "allocated_units": allocated_units_total,
        "field_capture_assigned": field_capture_assigned_total,
        "field_capture_done": field_capture_done_total,
        "field_capture_live": max(field_capture_assigned_total - field_capture_done_total, 0),
        "support_visit_assigned": support_visit_assigned_total,
        "support_visit_done": support_visit_done_total,
        "support_visit_live": max(support_visit_assigned_total - support_visit_done_total, 0),
        "support_target_total": support_target_total,
        "polygon_plots": polygon_plot_count,
        "photo_evidence_plots": photo_plot_count,
        "farmer_linked_plots": farmer_linked_plot_count,
        "crop_profile_plots": crop_profile_count,
        "season_profile_plots": season_profile_count,
        "reviewed_plots": reviewed_plot_count,
        "finance_access_farmers": finance_access_farmers,
        "insurance_access_farmers": insurance_access_farmers,
        "grouped_farmers": grouped_farmers,
        "identity_ready_farmers": identity_ready_farmers,
        "top_commodities": top_commodities,
        "geo_readiness_pct": _pct(polygon_plot_count, len(plot_rows)),
        "photo_readiness_pct": _pct(photo_plot_count, len(plot_rows)),
        "crop_readiness_pct": _pct(crop_profile_count, len(plot_rows)),
        "season_readiness_pct": _pct(season_profile_count, len(plot_rows)),
        "review_readiness_pct": _pct(reviewed_plot_count, len(plot_rows)),
        "identity_readiness_pct": _pct(identity_ready_farmers, len(farmer_rows)),
        "finance_segmentation_pct": _pct(finance_access_farmers, len(farmer_rows)),
        "insurance_segmentation_pct": _pct(insurance_access_farmers, len(farmer_rows)),
    }

    overview_map_view = None
    overview_map_png = None
    if include_map:
        overview_map_rows = []
        for row in plot_rows:
            overview_map_rows.append(
                {
                    "id": row.get("id"),
                    "status": row.get("status"),
                    "lng": row.get("lng"),
                    "lat": row.get("lat"),
                    "existing_area_geojson": row.get("existing_area_geojson"),
                }
            )
        try:
            overview_map_view = _estimate_report_map_view(overview_map_rows, width=800, height=500)
            overview_map_png = (
                _build_report_map_png(
                    overview_map_rows,
                    lng=overview_map_view.get("lng"),
                    lat=overview_map_view.get("lat"),
                    zoom=overview_map_view.get("zoom"),
                    bearing=overview_map_view.get("bearing"),
                    pitch=overview_map_view.get("pitch"),
                    include_markers=False,
                )
                if overview_map_view
                else None
            )
        except Exception:
            overview_map_view = None
            overview_map_png = None

    return {
        "project": project_copy,
        "summary": summary,
        "farmer_rows": farmer_rows,
        "plot_rows": plot_rows,
        "overview_map_png": overview_map_png,
        "overview_map_view": overview_map_view,
    }


def _build_relief_programme_export_context(
    project_id: int,
    db: Session,
    *,
    include_map: bool = False,
) -> dict:
    project = get_project(project_id, db)
    project_copy = dict(project)
    project_copy["relief_config"] = _normalize_relief_config(project.get("relief_config")) or {}

    raw_site_rows = _fetch_existing_tree_export_rows(project_id, db)
    site_rows: list[dict] = []
    for source_row in raw_site_rows:
        if _is_hidden_tree_record(source_row.get("record_profile_data")):
            continue
        row = dict(source_row)
        photo_urls = _normalize_photo_urls(row.get("photo_urls"))
        primary_photo_url = str(row.get("photo_url") or "").strip()
        if primary_photo_url:
            photo_urls = [primary_photo_url, *[item for item in photo_urls if item != primary_photo_url]]
        row["photo_urls"] = photo_urls
        row["primary_photo_url"] = photo_urls[0] if photo_urls else primary_photo_url
        row["record_profile_data"] = _normalize_tree_record_profile_data(
            row.get("record_profile_data"),
            existing_area_sqm=row.get("existing_area_sqm"),
        ) or {}
        row["custodian_profile_data"] = _normalize_custodian_profile_data(row.get("custodian_profile_data")) or {}
        site_rows.append(row)

    beneficiary_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    c.id,
                    c.project_id,
                    c.custodian_type,
                    c.name,
                    c.contact_person,
                    c.phone,
                    c.alt_phone,
                    c.email,
                    c.address_text,
                    c.local_government,
                    c.community_name,
                    c.verification_status,
                    c.notes,
                    c.created_at,
                    c.profile_data
                FROM green_custodians c
                WHERE c.project_id = :project_id
                ORDER BY c.created_at DESC, c.id DESC
                """
            ),
            {"project_id": project_id},
        ).mappings().all()
    ]
    for row in beneficiary_rows:
        row["profile_data"] = _normalize_custodian_profile_data(row.get("profile_data")) or {}
    beneficiary_by_id = {int(row.get("id") or 0): row for row in beneficiary_rows if int(row.get("id") or 0) > 0}

    allocation_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    a.id,
                    a.custodian_id,
                    COALESCE(a.quantity_allocated, 0) AS quantity_allocated,
                    COALESCE(a.supervision_target, 0) AS supervision_target,
                    a.expected_planting_start,
                    a.expected_planting_end,
                    a.notes,
                    a.created_at,
                    e.event_date,
                    e.species AS support_item
                FROM green_distribution_allocations a
                LEFT JOIN green_distribution_events e ON e.id = a.event_id
                WHERE a.project_id = :project_id
                ORDER BY a.created_at DESC, a.id DESC
                """
            ),
            {"project_id": project_id},
        ).mappings().all()
    ]

    task_rows = [
        dict(row)
        for row in db.execute(
            text(
                """
                SELECT
                    t.id,
                    t.tree_id,
                    t.custodian_id,
                    LOWER(COALESCE(t.task_type, '')) AS task_type,
                    LOWER(COALESCE(t.status, '')) AS status,
                    LOWER(COALESCE(t.review_state, 'none')) AS review_state,
                    t.assignee_name,
                    t.created_at,
                    t.completed_at,
                    t.due_date,
                    t.submitted_at,
                    t.reviewed_at
                FROM tree_tasks t
                JOIN trees tr ON tr.id = t.tree_id
                WHERE tr.project_id = :project_id
                  AND t.custodian_id IS NOT NULL
                  AND LOWER(COALESCE(t.task_type, '')) IN :task_types
                ORDER BY COALESCE(t.reviewed_at, t.submitted_at, t.created_at) DESC, t.id DESC
                """
            ).bindparams(bindparam("task_types", expanding=True)),
            {"project_id": project_id, "task_types": tuple(SUPPORT_ALLOCATION_TASK_TYPES)},
        ).mappings().all()
    ]

    allocation_summary_by_beneficiary: dict[int, dict] = {}
    for row in allocation_rows:
        custodian_id = int(row.get("custodian_id") or 0)
        if custodian_id <= 0:
            continue
        summary = allocation_summary_by_beneficiary.setdefault(
            custodian_id,
            {
                "allocation_count": 0,
                "allocated_units": 0.0,
                "support_target": 0,
                "latest_support_item": "",
                "latest_event_date": None,
            },
        )
        summary["allocation_count"] += 1
        summary["allocated_units"] += float(row.get("quantity_allocated") or 0.0)
        summary["support_target"] += int(row.get("supervision_target") or 0)
        if not summary["latest_support_item"] and str(row.get("support_item") or "").strip():
            summary["latest_support_item"] = str(row.get("support_item") or "").strip()
        if summary["latest_event_date"] is None and row.get("event_date") is not None:
            summary["latest_event_date"] = row.get("event_date")

    task_summary_by_beneficiary: dict[int, dict] = {}
    task_summary_by_site: dict[int, dict] = {}
    for row in task_rows:
        custodian_id = int(row.get("custodian_id") or 0)
        site_id = int(row.get("tree_id") or 0)
        task_type = _normalize_name(row.get("task_type"))
        is_complete = _is_export_task_complete(row)
        for target_map, target_id in ((task_summary_by_beneficiary, custodian_id), (task_summary_by_site, site_id)):
            if target_id <= 0:
                continue
            summary = target_map.setdefault(
                target_id,
                {
                    "field_capture_assigned": 0,
                    "field_capture_done": 0,
                    "support_visit_assigned": 0,
                    "support_visit_done": 0,
                    "last_task_date": None,
                },
            )
            date_candidate = row.get("reviewed_at") or row.get("submitted_at") or row.get("completed_at") or row.get("created_at")
            if date_candidate and summary["last_task_date"] is None:
                summary["last_task_date"] = date_candidate
            if task_type == FIELD_CAPTURE_TASK_TYPE:
                summary["field_capture_assigned"] += 1
                if is_complete:
                    summary["field_capture_done"] += 1
            elif task_type == SUPERVISION_TASK_TYPE:
                summary["support_visit_assigned"] += 1
                if is_complete:
                    summary["support_visit_done"] += 1

    site_summary_by_beneficiary: dict[int, dict] = {}
    asset_type_counts: dict[str, dict] = {}
    total_area_ha = 0.0
    total_population_served = 0
    total_estimated_repair_cost = 0.0
    polygon_site_count = 0
    photo_site_count = 0
    linked_beneficiary_site_count = 0
    damage_profile_count = 0
    response_profile_count = 0
    reviewed_site_count = 0
    for row in site_rows:
        site_id = int(row.get("id") or 0)
        custodian_id = int(row.get("custodian_id") or 0)
        record_profile = row.get("record_profile_data") or {}
        linked_beneficiary = beneficiary_by_id.get(custodian_id) or {}
        if linked_beneficiary:
            for key in (
                "phone",
                "alt_phone",
                "email",
                "address_text",
                "local_government",
                "community_name",
                "verification_status",
                "contact_person",
            ):
                row[key] = linked_beneficiary.get(key)

        area_ha = float(record_profile.get("area_hectares") or row.get("existing_area_ha") or 0.0)
        asset_type = str(record_profile.get("asset_type") or row.get("species") or "").strip()
        population_served = int(record_profile.get("population_served") or 0)
        estimated_repair_cost = float(record_profile.get("estimated_repair_cost") or 0.0)
        if area_ha > 0:
            total_area_ha += area_ha
        if population_served > 0:
            total_population_served += population_served
        if estimated_repair_cost > 0:
            total_estimated_repair_cost += estimated_repair_cost
        if _is_polygonal_work_area(row.get("existing_area_geojson")):
            polygon_site_count += 1
        if str(row.get("primary_photo_url") or "").strip():
            photo_site_count += 1
        if custodian_id > 0:
            linked_beneficiary_site_count += 1
            beneficiary_site_summary = site_summary_by_beneficiary.setdefault(
                custodian_id,
                {"site_count": 0, "area_ha": 0.0, "population_served": 0, "estimated_repair_cost": 0.0},
            )
            beneficiary_site_summary["site_count"] += 1
            beneficiary_site_summary["area_ha"] += area_ha
            beneficiary_site_summary["population_served"] += population_served
            beneficiary_site_summary["estimated_repair_cost"] += estimated_repair_cost
        if asset_type:
            key = asset_type.lower()
            item = asset_type_counts.setdefault(key, {"label": asset_type, "site_count": 0, "area_ha": 0.0})
            item["site_count"] += 1
            item["area_ha"] += area_ha
        if record_profile.get("damage_level"):
            damage_profile_count += 1
        if record_profile.get("response_pathway"):
            response_profile_count += 1
        if _normalize_name(row.get("last_review_state")) in {"approved", "metadata_edit", "submitted"}:
            reviewed_site_count += 1

        site_task_summary = task_summary_by_site.get(site_id) or {}
        row["field_capture_assigned"] = int(site_task_summary.get("field_capture_assigned") or 0)
        row["field_capture_done"] = int(site_task_summary.get("field_capture_done") or 0)
        row["field_capture_live"] = max(row["field_capture_assigned"] - row["field_capture_done"], 0)
        row["support_visit_assigned"] = int(site_task_summary.get("support_visit_assigned") or 0)
        row["support_visit_done"] = int(site_task_summary.get("support_visit_done") or 0)
        row["support_visit_live"] = max(row["support_visit_assigned"] - row["support_visit_done"], 0)
        row["latest_task_date"] = site_task_summary.get("last_task_date")

    top_asset_types = sorted(
        asset_type_counts.values(),
        key=lambda item: (int(item.get("site_count") or 0), float(item.get("area_ha") or 0.0)),
        reverse=True,
    )[:8]
    for item in top_asset_types:
        item["area_ha"] = round(float(item.get("area_ha") or 0.0), 4)

    for row in beneficiary_rows:
        beneficiary_id = int(row.get("id") or 0)
        profile = row.get("profile_data") or {}
        allocation_summary = allocation_summary_by_beneficiary.get(beneficiary_id) or {}
        task_summary = task_summary_by_beneficiary.get(beneficiary_id) or {}
        site_summary = site_summary_by_beneficiary.get(beneficiary_id) or {}
        row["allocation_count"] = int(allocation_summary.get("allocation_count") or 0)
        row["allocated_units"] = round(float(allocation_summary.get("allocated_units") or 0.0), 2)
        row["support_target"] = int(allocation_summary.get("support_target") or 0)
        row["site_count"] = int(site_summary.get("site_count") or 0)
        row["mapped_area_ha"] = round(float(site_summary.get("area_ha") or 0.0), 4)
        row["population_served"] = int(site_summary.get("population_served") or 0)
        row["estimated_repair_cost"] = round(float(site_summary.get("estimated_repair_cost") or 0.0), 2)
        row["field_capture_assigned"] = int(task_summary.get("field_capture_assigned") or 0)
        row["field_capture_done"] = int(task_summary.get("field_capture_done") or 0)
        row["field_capture_live"] = max(row["field_capture_assigned"] - row["field_capture_done"], 0)
        row["support_visit_assigned"] = int(task_summary.get("support_visit_assigned") or 0)
        row["support_visit_done"] = int(task_summary.get("support_visit_done") or 0)
        row["support_visit_live"] = max(row["support_visit_assigned"] - row["support_visit_done"], 0)
        row["latest_task_date"] = task_summary.get("last_task_date")
        row["beneficiary_code"] = str(profile.get("beneficiary_code") or "").strip()
        row["government_id"] = str(profile.get("government_id") or "").strip()
        row["displacement_status"] = str(profile.get("displacement_status") or "").strip()
        row["support_category"] = str(profile.get("support_category") or "").strip()
        row["vulnerability_flags"] = str(profile.get("vulnerability_flags") or "").strip()
        row["household_size_value"] = int(profile.get("household_size") or 0)
        row["women_count_value"] = int(profile.get("women_count") or 0)
        row["children_under_five_value"] = int(profile.get("children_under_five") or 0)
        row["elderly_count_value"] = int(profile.get("elderly_count") or 0)
        row["disability_count_value"] = int(profile.get("disability_count") or 0)

    verified_beneficiaries = sum(1 for row in beneficiary_rows if _normalize_name(row.get("verification_status")) == "verified")
    identity_ready_beneficiaries = sum(
        1
        for row in beneficiary_rows
        if str(row.get("beneficiary_code") or "").strip() or str(row.get("government_id") or "").strip()
    )
    displaced_beneficiaries = sum(
        1
        for row in beneficiary_rows
        if _normalize_name(row.get("displacement_status")) in {"idp", "returnee", "refugee", "host_community"}
    )
    vulnerable_beneficiaries = sum(
        1
        for row in beneficiary_rows
        if str(row.get("vulnerability_flags") or "").strip()
        or int(row.get("disability_count_value") or 0) > 0
        or int(row.get("children_under_five_value") or 0) > 0
        or int(row.get("elderly_count_value") or 0) > 0
    )
    institutional_beneficiaries = sum(
        1
        for row in beneficiary_rows
        if _normalize_name(row.get("custodian_type")) in {"school", "health_facility", "community_asset", "small_business"}
    )

    field_capture_assigned_total = sum(int(row.get("field_capture_assigned") or 0) for row in beneficiary_rows)
    field_capture_done_total = sum(int(row.get("field_capture_done") or 0) for row in beneficiary_rows)
    support_visit_assigned_total = sum(int(row.get("support_visit_assigned") or 0) for row in beneficiary_rows)
    support_visit_done_total = sum(int(row.get("support_visit_done") or 0) for row in beneficiary_rows)
    support_target_total = sum(int(row.get("support_target") or 0) for row in beneficiary_rows)
    allocated_units_total = round(sum(float(row.get("allocated_units") or 0.0) for row in beneficiary_rows), 2)

    def _pct(value: int, total: int) -> float:
        return round((float(value) / float(total)) * 100.0, 1) if total > 0 else 0.0

    summary = {
        "registered_beneficiaries": len(beneficiary_rows),
        "verified_beneficiaries": verified_beneficiaries,
        "mapped_sites": len(site_rows),
        "mapped_area_ha": round(total_area_ha, 4),
        "allocated_units": allocated_units_total,
        "field_capture_assigned": field_capture_assigned_total,
        "field_capture_done": field_capture_done_total,
        "field_capture_live": max(field_capture_assigned_total - field_capture_done_total, 0),
        "support_visit_assigned": support_visit_assigned_total,
        "support_visit_done": support_visit_done_total,
        "support_visit_live": max(support_visit_assigned_total - support_visit_done_total, 0),
        "support_target_total": support_target_total,
        "polygon_sites": polygon_site_count,
        "photo_evidence_sites": photo_site_count,
        "linked_beneficiary_sites": linked_beneficiary_site_count,
        "damage_profile_sites": damage_profile_count,
        "response_profile_sites": response_profile_count,
        "reviewed_sites": reviewed_site_count,
        "identity_ready_beneficiaries": identity_ready_beneficiaries,
        "vulnerable_beneficiaries": vulnerable_beneficiaries,
        "displaced_beneficiaries": displaced_beneficiaries,
        "institutional_beneficiaries": institutional_beneficiaries,
        "total_population_served": total_population_served,
        "total_estimated_repair_cost": round(total_estimated_repair_cost, 2),
        "top_asset_types": top_asset_types,
        "geo_readiness_pct": _pct(polygon_site_count, len(site_rows)),
        "photo_readiness_pct": _pct(photo_site_count, len(site_rows)),
        "damage_readiness_pct": _pct(damage_profile_count, len(site_rows)),
        "response_readiness_pct": _pct(response_profile_count, len(site_rows)),
        "review_readiness_pct": _pct(reviewed_site_count, len(site_rows)),
        "identity_readiness_pct": _pct(identity_ready_beneficiaries, len(beneficiary_rows)),
    }

    overview_map_view = None
    overview_map_png = None
    if include_map:
        overview_map_rows = []
        for row in site_rows:
            overview_map_rows.append(
                {
                    "id": row.get("id"),
                    "status": row.get("status"),
                    "lng": row.get("lng"),
                    "lat": row.get("lat"),
                    "existing_area_geojson": row.get("existing_area_geojson"),
                }
            )
        try:
            overview_map_view = _estimate_report_map_view(overview_map_rows, width=800, height=500)
            overview_map_png = (
                _build_report_map_png(
                    overview_map_rows,
                    lng=overview_map_view.get("lng"),
                    lat=overview_map_view.get("lat"),
                    zoom=overview_map_view.get("zoom"),
                    bearing=overview_map_view.get("bearing"),
                    pitch=overview_map_view.get("pitch"),
                    include_markers=False,
                )
                if overview_map_view
                else None
            )
        except Exception:
            overview_map_view = None
            overview_map_png = None

    return {
        "project": project_copy,
        "summary": summary,
        "beneficiary_rows": beneficiary_rows,
        "site_rows": site_rows,
        "overview_map_png": overview_map_png,
        "overview_map_view": overview_map_view,
    }


def _render_agric_programme_pdf_with_fallback(
    pdf_path: str,
    context: dict,
    *,
    include_photos: bool,
) -> None:
    map_png = context.get("overview_map_png")
    map_view = context.get("overview_map_view")

    attempts: list[tuple[bytes | None, dict | None, bool]] = [
        (map_png, map_view, include_photos),
    ]
    if map_png is not None or map_view is not None:
        attempts.append((None, None, include_photos))
    if include_photos:
        attempts.append((map_png, map_view, False))
        if map_png is not None or map_view is not None:
            attempts.append((None, None, False))

    last_error: Exception | None = None
    for next_map_png, next_map_view, next_include_photos in attempts:
        try:
            render_green_agric_programme_pdf(
                pdf_path,
                project=context["project"],
                summary=context["summary"],
                farmer_rows=context["farmer_rows"],
                plot_rows=context["plot_rows"],
                overview_map_png=next_map_png,
                overview_map_view=next_map_view,
                include_photos=next_include_photos,
            )
            return
        except Exception as exc:
            last_error = exc
    if last_error is not None:
        raise last_error


