@router.get("/projects/{project_id}/existing-trees/export/pdf")
def export_existing_trees_pdf(
    project_id: int,
    include_photos: bool = False,
    db: Session = Depends(get_db),
):
    project = get_project(project_id, db)
    workflow_profile = _normalize_workflow_profile(project.get("workflow_profile"))
    if workflow_profile == "agric":
        context = _build_agric_programme_export_context(project_id, db, include_map=True)
        os.makedirs(REPORTS_DIR, exist_ok=True)
        tmp_pdf = tempfile.NamedTemporaryFile(suffix="_agric_programme.pdf", delete=False)
        pdf_path = tmp_pdf.name
        tmp_pdf.close()
        _render_agric_programme_pdf_with_fallback(
            pdf_path,
            context,
            include_photos=include_photos,
        )
        filename = f"project_{project_id}_agric_programme_report.pdf"
        return _pdf_response_with_r2(
            pdf_path,
            filename,
            category="green-agric-programme-report",
            project_id=project_id,
            organization_id=int(context["project"].get("organization_id") or 0) or None,
        )
    if workflow_profile == "relief_recovery":
        context = _build_relief_programme_export_context(project_id, db, include_map=True)
        os.makedirs(REPORTS_DIR, exist_ok=True)
        tmp_pdf = tempfile.NamedTemporaryFile(suffix="_relief_programme.pdf", delete=False)
        pdf_path = tmp_pdf.name
        tmp_pdf.close()
        _render_relief_programme_pdf_with_fallback(
            pdf_path,
            context,
            include_photos=include_photos,
        )
        filename = f"project_{project_id}_relief_programme_report.pdf"
        return _pdf_response_with_r2(
            pdf_path,
            filename,
            category="green-relief-programme-report",
            project_id=project_id,
            organization_id=int(context["project"].get("organization_id") or 0) or None,
        )
    rows = _fetch_existing_tree_export_rows(project_id, db)
    summary = _summarize_existing_tree_export_rows(rows)

    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_pdf = tempfile.NamedTemporaryFile(suffix="_existing_trees_detailed.pdf", delete=False)
    pdf_path = tmp_pdf.name
    tmp_pdf.close()

    photo_rows: list[dict] = []
    if include_photos:
        for row in rows:
            merged_urls = _normalize_photo_urls(row.get("photo_urls"))
            if not merged_urls and str(row.get("photo_url") or "").strip():
                merged_urls = [str(row.get("photo_url") or "").strip()]
            if not merged_urls:
                continue
            for index, photo_url in enumerate(merged_urls, start=1):
                item = dict(row)
                item["photo_url"] = photo_url
                item["photo_index"] = index
                item["photo_total"] = len(merged_urls)
                photo_rows.append(item)
    render_green_existing_trees_report_pdf(
        pdf_path,
        project=project,
        rows=[dict(r) for r in rows],
        summary=summary,
        include_photos=include_photos,
        photo_rows=photo_rows,
    )
    filename = f"project_{project_id}_existing_trees_detailed.pdf"
    return _pdf_response_with_r2(
        pdf_path,
        filename,
        category="green-existing-trees-report",
        project_id=project_id,
        organization_id=int(project.get("organization_id") or 0) or None,
    )


@router.get("/projects/{project_id}/export/csv")
def export_project_csv(project_id: int, db: Session = Depends(get_db)):
    rows = db.execute(text("""
        SELECT
            t.id,
            t.project_id,
            t.species,
            t.planting_date,
            t.status,
            t.notes,
            t.photo_url,
            t.created_by,
            t.created_at,
            t.tree_origin,
            t.attribution_scope,
            t.count_in_planting_kpis,
            t.count_in_carbon_scope,
            t.custodian_id,
            c.name AS custodian_name,
            t.tree_height_m,
            ST_X(t.geom) AS lng,
            ST_Y(t.geom) AS lat
        FROM trees t
        LEFT JOIN green_custodians c ON c.id = t.custodian_id
        WHERE t.project_id = :project_id
        ORDER BY t.created_at DESC
    """), {"project_id": project_id}).mappings().all()
    maintenance_rows = _maintenance_summary_by_tree(project_id, db)
    rows = _attach_maintenance_to_tree_rows(rows, maintenance_rows)
    review_summary = _review_summary_by_tree(project_id, db)
    kpi = _compute_kpi_snapshot(project_id, db)

    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_csv = tempfile.NamedTemporaryFile(suffix="_trees.csv", delete=False)
    csv_path = tmp_csv.name
    tmp_csv.close()

    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = _excel_csv_writer(f)
        writer.writerow(["LandCheck Project Export"])
        writer.writerow([
            "KPI",
            f"Trees {kpi.get('trees_total', 0)}",
            f"Healthy {kpi.get('trees_healthy', 0)}",
            f"Attention {kpi.get('trees_attention', 0)}",
            f"Open Tasks {kpi.get('tasks_open', 0)}",
            f"Submitted {kpi.get('tasks_submitted', 0)}",
            f"Rejected {kpi.get('tasks_rejected', 0)}",
        ])
        writer.writerow([])
        writer.writerow([
            "tree_id", "project_id", "lng", "lat", "tree_origin", "attribution_scope",
            "count_in_planting_kpis", "count_in_carbon_scope", "custodian_id", "custodian_name", "tree_height_m",
            "species", "planting_date",
            "status", "notes", "photo_url", "created_by", "created_at",
            "maintenance_count", "maintenance_done", "maintenance_pending", "maintenance_overdue",
            "maintenance_types", "last_maintenance_type", "last_maintenance_date",
            "review_submitted", "review_approved", "review_rejected", "last_review_state", "last_review_note",
            "last_submitted_at", "last_reviewed_at"
        ])
        for r in rows:
            review = review_summary.get(int(r["id"]), {})
            writer.writerow([
                r["id"], r["project_id"], r["lng"], r["lat"], r.get("tree_origin"), r.get("attribution_scope"),
                r.get("count_in_planting_kpis"), r.get("count_in_carbon_scope"), r.get("custodian_id"), r.get("custodian_name"), r.get("tree_height_m"), r["species"],
                r["planting_date"], r["status"], r["notes"], r["photo_url"],
                r["created_by"], r["created_at"],
                r.get("maintenance_count", 0), r.get("maintenance_done", 0), r.get("maintenance_pending", 0), r.get("maintenance_overdue", 0),
                r.get("maintenance_types", ""), r.get("last_maintenance_type", ""), r.get("last_maintenance_date", ""),
                review.get("review_submitted", 0), review.get("review_approved", 0), review.get("review_rejected", 0),
                review.get("last_review_state", ""), review.get("last_review_note", ""),
                review.get("last_submitted_at", ""), review.get("last_reviewed_at", ""),
            ])

    filename = f"project_{project_id}_trees.csv"
    return FileResponse(csv_path, media_type="text/csv", filename=filename)


def _maintenance_summary_by_tree(project_id: int, db: Session, assignee_name: str | None = None) -> list[dict]:
    rows = db.execute(text("""
        SELECT tr.id AS tree_id,
               COUNT(t.id) AS maintenance_count,
               SUM(
                   CASE
                       WHEN LOWER(COALESCE(t.status, '')) IN ('done', 'completed', 'closed')
                            AND LOWER(COALESCE(t.review_state, 'none')) IN ('approved', 'none')
                       THEN 1 ELSE 0
                   END
               ) AS maintenance_done,
               SUM(
                   CASE
                       WHEN NOT (
                           LOWER(COALESCE(t.status, '')) IN ('done', 'completed', 'closed')
                           AND LOWER(COALESCE(t.review_state, 'none')) IN ('approved', 'none')
                       ) AND LOWER(COALESCE(t.status, 'pending')) <> 'overdue'
                       THEN 1 ELSE 0
                   END
               ) AS maintenance_pending,
               SUM(CASE WHEN t.status = 'overdue' THEN 1 ELSE 0 END) AS maintenance_overdue,
               COALESCE(STRING_AGG(DISTINCT t.task_type, ', ' ORDER BY t.task_type), '') AS maintenance_types,
               MAX(COALESCE(t.completed_at::date, t.due_date, t.created_at::date)) AS last_maintenance_date,
               (ARRAY_AGG(t.task_type ORDER BY COALESCE(t.completed_at, t.created_at) DESC NULLS LAST, t.id DESC))[1]
                 AS last_maintenance_type
        FROM trees tr
        LEFT JOIN tree_tasks t ON t.tree_id = tr.id
        WHERE tr.project_id = :project_id
          AND (:assignee_name IS NULL OR tr.created_by = :assignee_name)
        GROUP BY tr.id
        ORDER BY tr.id
    """), {"project_id": project_id, "assignee_name": assignee_name}).mappings().all()

    cleaned = []
    for row in rows:
        item = dict(row)
        item["maintenance_count"] = int(item.get("maintenance_count") or 0)
        item["maintenance_done"] = int(item.get("maintenance_done") or 0)
        item["maintenance_pending"] = int(item.get("maintenance_pending") or 0)
        item["maintenance_overdue"] = int(item.get("maintenance_overdue") or 0)
        item["maintenance_types"] = item.get("maintenance_types") or ""
        item["last_maintenance_type"] = item.get("last_maintenance_type") or ""
        cleaned.append(item)
    return cleaned


def _attach_maintenance_to_tree_rows(rows: list[dict], summary_rows: list[dict]) -> list[dict]:
    summary_by_tree = {r["tree_id"]: r for r in summary_rows}
    merged = []
    for row in rows:
        item = dict(row)
        summary = summary_by_tree.get(item.get("id")) or {}
        item["maintenance_count"] = summary.get("maintenance_count", 0)
        item["maintenance_done"] = summary.get("maintenance_done", 0)
        item["maintenance_pending"] = summary.get("maintenance_pending", 0)
        item["maintenance_overdue"] = summary.get("maintenance_overdue", 0)
        item["maintenance_types"] = summary.get("maintenance_types", "")
        item["last_maintenance_type"] = summary.get("last_maintenance_type", "")
        item["last_maintenance_date"] = summary.get("last_maintenance_date")
        merged.append(item)
    return merged


@router.get("/projects/{project_id}/export/pdf")
def export_project_pdf(
    project_id: int,
    lng: float | None = Query(default=None),
    lat: float | None = Query(default=None),
    zoom: float | None = Query(default=None),
    bearing: float | None = Query(default=0.0),
    pitch: float | None = Query(default=0.0),
    db: Session = Depends(get_db),
):
    def _coerce_optional_float(value: object) -> float | None:
        if value is None:
            return None
        try:
            if isinstance(value, bool):
                return None
            return float(value)
        except Exception:
            return None

    lng_value = _coerce_optional_float(lng)
    lat_value = _coerce_optional_float(lat)
    zoom_value = _coerce_optional_float(zoom)
    bearing_value = _coerce_optional_float(bearing)
    pitch_value = _coerce_optional_float(pitch)

    project = get_project(project_id, db)
    rows = db.execute(text("""
        SELECT
               t.id,
               t.species,
               t.planting_date,
               t.status,
               t.notes,
               t.tree_origin,
               t.tree_height_m,
               t.attribution_scope,
               t.count_in_planting_kpis,
               t.count_in_carbon_scope,
               t.custodian_id,
               c.name AS custodian_name,
               ST_X(t.geom) AS lng,
               ST_Y(t.geom) AS lat
        FROM trees t
        LEFT JOIN green_custodians c ON c.id = t.custodian_id
        WHERE t.project_id = :project_id
        ORDER BY t.created_at DESC
        LIMIT 200
    """), {"project_id": project_id}).mappings().all()
    map_rows = db.execute(text("""
        SELECT
               t.id,
               t.species,
               t.planting_date,
               t.status,
               t.notes,
               t.tree_origin,
               t.tree_height_m,
               t.attribution_scope,
               t.count_in_planting_kpis,
               t.count_in_carbon_scope,
               t.custodian_id,
               c.name AS custodian_name,
               ST_X(t.geom) AS lng,
               ST_Y(t.geom) AS lat
        FROM trees t
        LEFT JOIN green_custodians c ON c.id = t.custodian_id
        WHERE t.project_id = :project_id
        ORDER BY t.created_at DESC
        LIMIT 1000
    """), {"project_id": project_id}).mappings().all()
    maintenance_rows = _maintenance_summary_by_tree(project_id, db)
    rows = _attach_maintenance_to_tree_rows(rows, maintenance_rows)
    map_rows = _attach_maintenance_to_tree_rows(map_rows, maintenance_rows)

    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_pdf = tempfile.NamedTemporaryFile(suffix="_project_report.pdf", delete=False)
    pdf_path = tmp_pdf.name
    tmp_pdf.close()

    map_png = _build_report_map_png(
        map_rows=map_rows,
        lng=lng_value,
        lat=lat_value,
        zoom=zoom_value,
        bearing=bearing_value,
        pitch=pitch_value,
    )

    map_view = None
    if lng_value is not None and lat_value is not None and zoom_value is not None:
        map_view = {"lng": lng_value, "lat": lat_value, "zoom": zoom_value}
    donor_rows = _build_donor_report_rows(project_id, db)
    kpi_snapshot = _compute_kpi_snapshot(project_id, db)
    try:
        _store_kpi_snapshot(project_id, kpi_snapshot, db)
        db.commit()
    except Exception:
        db.rollback()

    # Carbon data for executive summary
    carbon_trees = db.execute(text("""
        SELECT id, species, planting_date, status, created_at, tree_age_months, COALESCE(inventory_tree_count, 1) AS inventory_tree_count
        FROM trees
        WHERE project_id = :pid
          AND COALESCE(count_in_carbon_scope, TRUE) = TRUE
    """), {"pid": project_id}).mappings().all()
    carbon_data = compute_project_carbon([dict(r) for r in carbon_trees])
    carbon_data["projection"] = generate_co2_projection_table([dict(r) for r in carbon_trees], 30)

    # KPI trend for survival chart
    kpi_trend = _fetch_kpi_trend(project_id, db, days=90)
    species_daily_survival = _build_species_daily_survival_series(project_id, db)

    try:
        render_green_report_pdf(
            pdf_path,
            project,
            rows,
            map_png=map_png,
            map_rows=map_rows,
            map_view=map_view,
            maintenance_rows=maintenance_rows,
            donor_rows=donor_rows,
            kpi_snapshot=kpi_snapshot,
            carbon_data=carbon_data,
            kpi_trend=kpi_trend,
            species_daily_survival=species_daily_survival,
        )
    except Exception:
        render_green_report_pdf(
            pdf_path,
            project,
            rows,
            map_png=None,
            map_rows=map_rows,
            map_view=map_view,
            maintenance_rows=maintenance_rows,
            donor_rows=donor_rows,
            kpi_snapshot=kpi_snapshot,
            carbon_data=carbon_data,
            kpi_trend=kpi_trend,
            species_daily_survival=species_daily_survival,
        )
    filename = f"project_{project_id}_report.pdf"
    return _pdf_response_with_r2(
        pdf_path,
        filename,
        category="green-project-report",
        project_id=project_id,
        organization_id=int(project.get("organization_id") or 0) or None,
    )


def _fetch_kpi_trend(project_id: int, db: Session, days: int = 90, assignee_name: str | None = None) -> list[dict]:
    """Fetch KPI trend series for charts using cohort/activity monthly basis."""
    return _build_kpi_trend_series(project_id, db, days=days, assignee_name=assignee_name)


def _build_tree_stats(rows: list[dict]) -> dict:
    scoped_rows = [r for r in rows if bool(r.get("count_in_planting_kpis", True))]
    total = len(scoped_rows)
    alive = sum(1 for r in scoped_rows if _normalize_tree_status(r.get("status")) in HEALTHY_TREE_STATUSES)
    dead = sum(1 for r in scoped_rows if _normalize_tree_status(r.get("status")) in DEAD_TREE_STATUSES)
    needs_attention = sum(1 for r in scoped_rows if _normalize_tree_status(r.get("status")) in ATTENTION_TREE_STATUSES)
    pending = sum(1 for r in scoped_rows if _normalize_tree_status(r.get("status")) == "pending_planting")
    survival_rate = round((alive / total) * 100, 1) if total else 0.0
    return {
        "total": total,
        "total_all": len(rows),
        "alive": alive,
        "dead": dead,
        "needs_attention": needs_attention,
        "pending_planting": pending,
        "survival_rate": survival_rate,
    }


def _render_work_report_to_pdf(
    db: Session,
    *,
    project_id: int,
    assignee_name: str | None,
    include_photos: bool,
    lng: float | None,
    lat: float | None,
    zoom: float | None,
    bearing: float | None,
    pitch: float | None,
    pdf_path: str,
) -> tuple[str, int | None]:
    def _coerce_optional_float(value: object) -> float | None:
        if value is None:
            return None
        try:
            if isinstance(value, bool):
                return None
            return float(value)
        except Exception:
            return None

    lng_value = _coerce_optional_float(lng)
    lat_value = _coerce_optional_float(lat)
    zoom_value = _coerce_optional_float(zoom)
    bearing_value = _coerce_optional_float(bearing)
    pitch_value = _coerce_optional_float(pitch)

    assignee_clean = assignee_name.strip() if isinstance(assignee_name, str) else None
    project = get_project(project_id=project_id, db=db, assignee_name=assignee_clean)
    workflow_profile = _normalize_workflow_profile(project.get("workflow_profile"))
    if workflow_profile == "agric":
        context = _build_agric_programme_export_context(project_id, db, include_map=True)
        _render_agric_programme_pdf_with_fallback(
            pdf_path,
            context,
            include_photos=include_photos,
        )
        return f"project_{project_id}_agric_programme_report.pdf", int(context["project"].get("organization_id") or 0) or None
    if workflow_profile == "relief_recovery":
        context = _build_relief_programme_export_context(project_id, db, include_map=True)
        _render_relief_programme_pdf_with_fallback(
            pdf_path,
            context,
            include_photos=include_photos,
        )
        return f"project_{project_id}_relief_programme_report.pdf", int(context["project"].get("organization_id") or 0) or None
    if assignee_name:
        rows = db.execute(text("""
            SELECT
                   t.id,
                   t.species,
                   t.planting_date,
                   t.status,
                   t.notes,
                   t.photo_url,
                   t.created_by,
                   t.tree_origin,
                   t.tree_height_m,
                   t.attribution_scope,
                   t.count_in_planting_kpis,
                   t.count_in_carbon_scope,
                   t.custodian_id,
                   c.name AS custodian_name,
                   ST_X(t.geom) AS lng,
                   ST_Y(t.geom) AS lat
            FROM trees t
            LEFT JOIN green_custodians c ON c.id = t.custodian_id
            WHERE t.project_id = :project_id AND t.created_by = :assignee_name
            ORDER BY t.created_at DESC
            LIMIT 200
        """), {"project_id": project_id, "assignee_name": assignee_name}).mappings().all()
        map_rows = db.execute(text("""
            SELECT
                   t.id,
                   t.species,
                   t.planting_date,
                   t.status,
                   t.notes,
                   t.photo_url,
                   t.created_by,
                   t.tree_origin,
                   t.tree_height_m,
                   t.attribution_scope,
                   t.count_in_planting_kpis,
                   t.count_in_carbon_scope,
                   t.custodian_id,
                   c.name AS custodian_name,
                   ST_X(t.geom) AS lng,
                   ST_Y(t.geom) AS lat
            FROM trees t
            LEFT JOIN green_custodians c ON c.id = t.custodian_id
            WHERE t.project_id = :project_id AND t.created_by = :assignee_name
            ORDER BY t.created_at DESC
            LIMIT 1000
        """), {"project_id": project_id, "assignee_name": assignee_name}).mappings().all()
    else:
        rows = db.execute(text("""
            SELECT
                   t.id,
                   t.species,
                   t.planting_date,
                   t.status,
                   t.notes,
                   t.photo_url,
                   t.created_by,
                   t.tree_origin,
                   t.tree_height_m,
                   t.attribution_scope,
                   t.count_in_planting_kpis,
                   t.count_in_carbon_scope,
                   t.custodian_id,
                   c.name AS custodian_name,
                   ST_X(t.geom) AS lng,
                   ST_Y(t.geom) AS lat
            FROM trees t
            LEFT JOIN green_custodians c ON c.id = t.custodian_id
            WHERE t.project_id = :project_id
            ORDER BY t.created_at DESC
            LIMIT 200
        """), {"project_id": project_id}).mappings().all()
        map_rows = db.execute(text("""
            SELECT
                   t.id,
                   t.species,
                   t.planting_date,
                   t.status,
                   t.notes,
                   t.photo_url,
                   t.created_by,
                   t.tree_origin,
                   t.tree_height_m,
                   t.attribution_scope,
                   t.count_in_planting_kpis,
                   t.count_in_carbon_scope,
                   t.custodian_id,
                   c.name AS custodian_name,
                   ST_X(t.geom) AS lng,
                   ST_Y(t.geom) AS lat
            FROM trees t
            LEFT JOIN green_custodians c ON c.id = t.custodian_id
            WHERE t.project_id = :project_id
            ORDER BY t.created_at DESC
            LIMIT 1000
        """), {"project_id": project_id}).mappings().all()

    photo_rows: list[dict] = []
    if include_photos:
        if assignee_name:
            photo_rows = db.execute(text("""
                SELECT
                       t.id,
                       t.species,
                       t.planting_date,
                       t.status,
                       t.tree_origin,
                       t.tree_height_m,
                       t.attribution_scope,
                       t.created_by,
                       t.custodian_id,
                       c.name AS custodian_name,
                       t.photo_url
                FROM trees t
                LEFT JOIN green_custodians c ON c.id = t.custodian_id
                WHERE t.project_id = :project_id
                  AND t.created_by = :assignee_name
                  AND COALESCE(TRIM(t.photo_url), '') <> ''
                ORDER BY t.created_at DESC, t.id DESC
            """), {"project_id": project_id, "assignee_name": assignee_name}).mappings().all()
        else:
            photo_rows = db.execute(text("""
                SELECT
                       t.id,
                       t.species,
                       t.planting_date,
                       t.status,
                       t.tree_origin,
                       t.tree_height_m,
                       t.attribution_scope,
                       t.created_by,
                       t.custodian_id,
                       c.name AS custodian_name,
                       t.photo_url
                FROM trees t
                LEFT JOIN green_custodians c ON c.id = t.custodian_id
                WHERE t.project_id = :project_id
                  AND COALESCE(TRIM(t.photo_url), '') <> ''
                ORDER BY t.created_at DESC, t.id DESC
            """), {"project_id": project_id}).mappings().all()

    maintenance_rows = _maintenance_summary_by_tree(project_id, db, assignee_name)
    rows = _attach_maintenance_to_tree_rows(rows, maintenance_rows)
    map_rows = _attach_maintenance_to_tree_rows(map_rows, maintenance_rows)

    project_copy = dict(project)
    project_copy["stats"] = _build_tree_stats(map_rows)
    project_copy["report_assignee"] = assignee_name

    map_png = _build_report_map_png(
        map_rows=map_rows,
        lng=lng_value,
        lat=lat_value,
        zoom=zoom_value,
        bearing=bearing_value,
        pitch=pitch_value,
    )

    map_view = None
    if lng_value is not None and lat_value is not None and zoom_value is not None:
        map_view = {"lng": lng_value, "lat": lat_value, "zoom": zoom_value}
    donor_rows = _build_donor_report_rows(project_id, db, assignee_name=assignee_clean)
    kpi_snapshot = _compute_kpi_snapshot(project_id, db, assignee_name=assignee_clean)
    try:
        _store_kpi_snapshot(project_id, kpi_snapshot, db)
        db.commit()
    except Exception:
        db.rollback()

    carbon_trees = db.execute(text("""
        SELECT id, species, planting_date, status, created_at, tree_age_months, COALESCE(inventory_tree_count, 1) AS inventory_tree_count
        FROM trees
        WHERE project_id = :pid
          AND COALESCE(count_in_carbon_scope, TRUE) = TRUE
          AND (:assignee_name IS NULL OR LOWER(TRIM(COALESCE(created_by, ''))) = LOWER(TRIM(:assignee_name)))
    """), {"pid": project_id, "assignee_name": assignee_clean}).mappings().all()
    carbon_data = compute_project_carbon([dict(r) for r in carbon_trees])
    carbon_data["projection"] = generate_co2_projection_table([dict(r) for r in carbon_trees], 30)

    kpi_trend = _fetch_kpi_trend(project_id, db, days=90, assignee_name=assignee_clean)
    species_daily_survival = _build_species_daily_survival_series(project_id, db, assignee_name=assignee_clean)

    try:
        render_green_report_pdf(
            pdf_path,
            project_copy,
            rows,
            map_png=map_png,
            map_rows=map_rows,
            map_view=map_view,
            maintenance_rows=maintenance_rows,
            donor_rows=donor_rows,
            kpi_snapshot=kpi_snapshot,
            carbon_data=carbon_data,
            kpi_trend=kpi_trend,
            species_daily_survival=species_daily_survival,
            photo_rows=photo_rows,
            include_photos=include_photos,
        )
    except Exception:
        render_green_report_pdf(
            pdf_path,
            project_copy,
            rows,
            map_png=None,
            map_rows=map_rows,
            map_view=map_view,
            maintenance_rows=maintenance_rows,
            donor_rows=donor_rows,
            kpi_snapshot=kpi_snapshot,
            carbon_data=carbon_data,
            kpi_trend=kpi_trend,
            species_daily_survival=species_daily_survival,
            photo_rows=photo_rows,
            include_photos=include_photos,
        )
    filename = (
        f"project_{project_id}_work_report_{assignee_clean}.pdf"
        if assignee_clean
        else f"project_{project_id}_work_report_all.pdf"
    )
    return filename, int(project_copy.get("organization_id") or 0) or None


@router.get("/work-report/pdf")
def export_work_report_pdf(
    project_id: int,
    assignee_name: str | None = None,
    include_photos: bool = False,
    lng: float | None = None,
    lat: float | None = None,
    zoom: float | None = None,
    bearing: float | None = 0.0,
    pitch: float | None = 0.0,
    db: Session = Depends(get_db),
):
    os.makedirs(REPORTS_DIR, exist_ok=True)
    tmp_pdf = tempfile.NamedTemporaryFile(suffix="_work_map_report.pdf", delete=False)
    pdf_path = tmp_pdf.name
    tmp_pdf.close()
    filename, organization_id = _render_work_report_to_pdf(
        db,
        project_id=project_id,
        assignee_name=assignee_name,
        include_photos=include_photos,
        lng=lng,
        lat=lat,
        zoom=zoom,
        bearing=bearing,
        pitch=pitch,
        pdf_path=pdf_path,
    )
    return _pdf_response_with_r2(
        pdf_path,
        filename,
        category="green-work-report",
        project_id=project_id,
        organization_id=organization_id,
    )


def _run_work_report_export_job(job_id: str):
    db = SessionLocal()
    pdf_path = ""
    try:
        job = _get_green_export_job(db, job_id)
        if not job:
            return
        _set_green_export_job_status(db, job_id, status="running", started=True)
        os.makedirs(REPORTS_DIR, exist_ok=True)
        tmp_pdf = tempfile.NamedTemporaryFile(suffix="_work_map_report.pdf", delete=False)
        pdf_path = tmp_pdf.name
        tmp_pdf.close()
        filename, organization_id = _render_work_report_to_pdf(
            db,
            project_id=int(job.get("project_id") or 0),
            assignee_name=str(job.get("assignee_name") or "").strip() or None,
            include_photos=bool(job.get("include_photos")),
            lng=job.get("lng"),
            lat=job.get("lat"),
            zoom=job.get("zoom"),
            bearing=job.get("bearing"),
            pitch=job.get("pitch"),
            pdf_path=pdf_path,
        )
        upload_meta = upload_export_file_best_effort(
            pdf_path,
            filename,
            category="green-work-report",
            project_id=int(job.get("project_id") or 0) or None,
            organization_id=organization_id,
            content_type="application/pdf",
        )
        if not upload_meta or not str(upload_meta.get("public_url") or "").strip():
            raise RuntimeError("Report generated but upload to cloud storage failed.")
        _set_green_export_job_status(
            db,
            job_id,
            status="completed",
            object_key=str(upload_meta.get("object_key") or ""),
            public_url=str(upload_meta.get("public_url") or ""),
            file_name=filename,
            completed=True,
        )
    except Exception as exc:
        try:
            _set_green_export_job_status(db, job_id, status="failed", error_text=str(exc), completed=True)
        except Exception:
            pass
    finally:
        try:
            if pdf_path and os.path.exists(pdf_path):
                os.remove(pdf_path)
        except Exception:
            pass
        db.close()


@router.post("/work-report/export-jobs")
def create_work_report_export_job(
    payload: WorkReportExportJobPayload,
    request: Request,
    db: Session = Depends(get_db),
):
    project = get_project(
        project_id=int(payload.project_id),
        db=db,
        assignee_name=(payload.assignee_name or "").strip() or None,
    )
    job_id = uuid.uuid4().hex
    file_name = (
        f"project_{int(payload.project_id)}_work_report_{payload.assignee_name}.pdf"
        if (payload.assignee_name or "").strip()
        else f"project_{int(payload.project_id)}_work_report_all.pdf"
    )
    db.execute(
        text(
            """
            INSERT INTO green_export_jobs (
                id,
                export_type,
                project_id,
                organization_id,
                assignee_name,
                include_photos,
                status,
                file_name,
                requested_by,
                started_at,
                completed_at,
                created_at,
                updated_at
            )
            VALUES (
                :id,
                'green-work-report',
                :project_id,
                :organization_id,
                :assignee_name,
                :include_photos,
                'queued',
                :file_name,
                :requested_by,
                NULL,
                NULL,
                NOW(),
                NOW()
            )
            """
        ),
        {
            "id": job_id,
            "project_id": int(payload.project_id),
            "organization_id": int(project.get("organization_id") or 0) or None,
            "assignee_name": (payload.assignee_name or "").strip() or None,
            "include_photos": bool(payload.include_photos),
            "file_name": file_name,
            "requested_by": (payload.requested_by or "").strip() or None,
        },
    )
    db.commit()
    db.execute(
        text(
            """
            UPDATE green_export_jobs
            SET object_key = NULL,
                public_url = NULL,
                error_text = NULL,
                updated_at = NOW()
            WHERE id = :job_id
            """
        ),
        {"job_id": job_id},
    )
    db.commit()
    db.execute(
        text(
            """
            UPDATE green_export_jobs
            SET lng = :lng,
                lat = :lat,
                zoom = :zoom,
                bearing = :bearing,
                pitch = :pitch,
                updated_at = NOW()
            WHERE id = :job_id
            """
        ),
        {
            "job_id": job_id,
            "lng": payload.lng,
            "lat": payload.lat,
            "zoom": payload.zoom,
            "bearing": payload.bearing,
            "pitch": payload.pitch,
        },
    )
    db.commit()
    threading.Thread(target=_run_work_report_export_job, args=(job_id,), daemon=True).start()
    job = _get_green_export_job(db, job_id)
    return _serialize_green_export_job(job, request=request)


@router.get("/export-jobs/{job_id}")
def get_green_export_job_status(job_id: str, request: Request, db: Session = Depends(get_db)):
    job = _get_green_export_job(db, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Export job not found")
    return _serialize_green_export_job(job, request=request)
